COLLDATA("asabahur","ur",[[1184,"§۱۱۸۴ ۔ جمرہ بن عوف(1)\nکنیت ابو یزید۔ اہل فلسطین میں شمار ہوتے ہیں۔ دار قطنی نے موتلف میں وہاس بن علاق بن ہاشم بن یزید بن جمرہ کے طریق سے روایت کیا ہے، فرماتے ہیں: میں نے اپنے والد کو اپنے والد سے بحوالہ اپنے دادا یزید بن جمرہ سے روایت کرتے سنا۔ فرمایا: میں اپنے والد جمرہ بن عوف کے ہمراہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا، ہم نے آپ صلی اللہ علیہ وسلم سے بیعت کی۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کے لئے دعا فرمائی اور ان کے سینے پر ہاتھ پھیرا۔(2) ابن مندہ نے اسی سند سے روایت کر کے اس میں کہا: یزید بن جمرہ سے روایت ہے، فرمایا: کہ میرے والد جمرہ بن عوف اور ان کے بھائی حریث نبی صلی اللہ علیہ وسلم کے پاس آئے۔ اس سند کے رجال مجہول ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۷۶)\n(2) جامع المسانید (۱۱۱/۳) اسد الغابۃ (۷۷۷) الاستيعاب (۳۷۴)"}],[1185,"§۱۱۸۵ ۔ جمرہ بن نعمان بن ھوذہ بن مالک بن سمعان العذری(1)\nابن کلبی فرماتے ہیں: یہ پہلے شخص ہیں جو نبی صلی اللہ علیہ وسلم کی خدمت میں بنی عذرہ کی زکوۃ لے کر آئے۔ ابو حاتم رحمہ اللہ فرماتے ہیں: وہ عذرہ کے وفد میں آئے۔ بقول طبری: بنی عذرہ کے سردار تھے نبی صلی اللہ علیہ وسلم کے پاس ان کی زکوۃ لے کر آئے۔ ابن کلبی فرماتے ہیں: اہل حجاز میں سے پہلے شخص ہیں جو اپنی قوم کی زکوۃ لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ آپ نے انہیں ان کے گھوڑے کی دوڑ اور کوڑے کی پھینک کے بقدر وادی قری سے زمین دی۔ جہاں وہ فروکش ہوئے اور موت تک وہیں رہے۔ ابن شاہین نے ان کا ذکر تو کیا ہے لیکن بے نقطی حاء میں۔ ایسا ہی ابن بشکوال نے بحوالہ ابن رشدین اپنے استدراک میں ان کا ذکر کیا ہے۔ لیکن دونوں کو اس میں وہم ہوا ہے جبکہ دارقطنی وغیرہ نے جیم را سے یہ نام قلمبند کیا ہے۔ واقدی شعیب بن میمون سے بحوالہ ابو مرایہ بلوی روایت کرتے ہیں، انہوں نے حمزہ بن نعمان عذری سے جو صحابی ہیں کہ نبی صلی اللہ علیہ وسلم نے انہیں بال اور خون دفن کرنے کا حکم دیا۔(2) دارقطنی نے موتلف میں اپنی سند سے اسے نقل کیا ہے سعد بن مالک عذری کے سوانح میں ان کا تذکرہ آئے گا۔","",{"fn":"(1) الجرح والتعدیل (۵۴۸/۲)\n(2) جامع المسانید (۱۱۲/۳) کنز العمال (۲۸۴۸۷) المصنف لابن ابی شیبہ (۴۱۷/۵) فتح الباری (۲۴۶/۱۰)"}],[1186,"§۱۱۸۶ ۔ (ز) جمرہ (بے نسبت)(1)\nان کا ذکر اس حدیث میں آتا ہے جسے ابن لہیعہ نے حارث بن یزید سے بحوالہ عبدالرحمن بن جبیر، یعیش غفاری سے روایت کیا ہے، آپ صلی اللہ علیہ وسلم نے اپنے پاس کھڑی اوٹنی کے متعلق فرمایا: اسے کون دوہے گا؟ ایک شخص اٹھا، آپ صلی اللہ علیہ وسلم نے فرمایا: تمہارا نام؟ اس نے کہا: مرہ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: بیٹھ جاؤ۔(2) (حدیث) ایسا ہی ابو علی بن السکن نے ذکر کیا ہے اور ابن عبدالبر نے سحنون کے طریق سے بحوالہ ابن وہب، ابن لہیعہ سے اس کا سیاق بیان کیا ہے۔ حرب نامی لوگوں میں (حائے بے نقطی تذکرہ آئے گا۔ انہوں نے جمرہ کی جگہ حرب کہا ہے۔","",{"fn":"(1) موطا مالک کتاب الاستئذان باب ما یکرہ من الاسماء (۱۸۱۹) مجمع الزوائد (۴۷/۸)\n(2) اسد الغابۃ (۷۷۸)"}],[1187,"§۱۱۸۷ ۔ جمھان الاعمیٰ(1)\nابن الاثیر نے ان کا استدراک میں ذکر کیا ہے۔ میں نے فاطمہ بنت عبد الہادی کے سامنے بحوالہ حسن بن عمر کردی، مکرم بن ابی الصقر نے حاضر ہو کر پڑھا کہ سعد بن سہل نے انہیں بتایا، انہیں ابو الحسن بن اخرم نے انہیں ابو نصر فامی نے ان سے اسہم، ان سے ربیع، ان سے اسد بن موسیٰ، ان سے نصر بن طریف، ان سے ایوب بن موسیٰ ان سے مقبری، ذکوان سے بحوالہ ام سلمہ رضی اللہ عنہا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس تھیں اتنے میں جمھان نابینے آئے، آپ نے فرمایا: پردے میں ہو جاؤ، انہوں نے عرض کیا: یا رسول اللہ! جمھان نابینے ہیں آپ نے فرمایا: عورتوں کے لیے مردوں کو دیکھنا ایسے ہی مکروہ ہے جیسے مردوں کا عورتوں کو دیکھنا۔(2) نصر بن طریف ضعیف راوی ہے۔","",{"fn":"(1) کنز العمال (۱۳۰۷۱)\n(2) اسد الغابۃ (۷۷۹)"}],[1188,"§۱۱۸۸ ۔ (ز) الجموح الانصاری\nاز بنی سلمہ، عمر بن شبہ کتاب مکہ میں ان اصنام کے ذکر میں لکھتے ہیں جن کی جاہلیت میں پوجا کی جاتی تھی: بنی سلمہ کا مناف نامی بت تھا۔ اس کے پاس ان میں سے ایک شخص گیا جسے جموح کہا جاتا تھا اس کے ساتھ کتا باندھ دیا اور پھر دونوں کو ایک کنویں میں پھینک کر کہا: تمام تعریفیں احسانوں والے صاحب جلال اللہ کے لئے ہیں، جس نے مناف میل والے کا برا حال کر دیا۔ میں قسم کھا کر کہتا ہوں (اے مناف!) اگر تو الہ و معبود ہوتا تو تو اور کتا دونوں رسی سے بندھے کنویں کے درمیان میں نہ پڑے ہوتے۔"],[1189,"§۱۱۸۹ ۔ (ز) الجموح بن عثمان بن ثابت بن الجذع الغفاری\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ اور عمر بن شبہ نے عبدالعزیز بن عمران کے طریق سے بحوالہ محمد بن ابراہیم بن جعفر مولی بنی غفار، جموح سے روایت کرتے ہیں، فرمایا: ہم لوگ اپنے گھروں میں تھے کہ رات ایک چیخنے والے نے چیخ ماری پھر اشعار ذکر کیے فرماتے ہیں پھر دوسری اور تیسری رات اس نے بلایا زیادہ دن نہ گزرے تھے کہ ہمیں نبی صلی اللہ علیہ وسلم کے ظہور کی اطلاع مل گئی۔"],[1190,"§۱۱۹۰ ۔ جمیع بن مسعود(1)\nبن عمرو بن اصرم بن سالم بن عوف بن عمرو بن عوف بن خزرج انصاری ہشام بن کلبی فرماتے ہیں: انہوں نے نبی صلی اللہ علیہ وسلم کے عہد میں اپنا سارا سامان صدقہ کر دیا تھا۔","",{"fn":"(1) اسد الغابۃ (۷۸۱)"}],[1191,"§۱۱۹۱ ۔ جمیل الغفاری ابو بصرہ\nبے نقطے حرف میں تذکرہ آئے گا۔"],[1192,"§۱۱۹۲ ۔ جمیل بن اسید الفہری\nکنیت ابو معمر تھی۔ فراء نے معانی القرآن میں ان کا نام ذو القلبین (دو دلوں والا) بتایا ہے۔ زبیر بن بکار فرماتے ہیں: ہمیں عمرو بن ابی بکر موصلی نے بحوالہ ذکریا بن عیسیٰ، ابن شہاب سے روایت کر کے بتایا کہ ذو القلبین کا تعلق بنی حارث بن فہر سے تھا۔ کنیت ابو عمر تھی، یہ وہی ہیں جنہوں نے قریش کو سیدنا عمر رضی اللہ عنہ کے اسلام لانے کی خبر دی اور مقاتل اپنی تفسیر میں باری تعالیٰ کے اس ارشاد: ”اللہ تعالیٰ نے کسی مرد کے پیٹ میں دو دل نہیں بنائے“ (سورۃ الاحزاب: ۴) کے بارے میں لکھتے ہیں، یہ آیت ابو معمر فہری کے بارے میں نازل ہوئی۔ ایسا ہی اسمعیل بن ابی زیاد شامی نے کہا ہے کہ ابو معمر فہری کے بارے میں نازل ہوئی وہ عرب کے ذہین ترین اور حافظے والے انسان تھے۔ ابو ذکریا فراء معانی القرآن میں فرماتے ہیں: یہ آیت ابو معمر جمیل بن اسید کے حق میں نازل ہوئی۔ اہل مکہ کہتے تھے کہ ابو معمر کے سینے میں دو دل ہیں۔ اور دو عقلیں ہیں۔ کیونکہ ان کا حافظہ بہت تیز تھا۔ اسی طرح واحدی نے ”لاسباب“ میں ان کا ذکر تو کیا۔ رہے ابن درید تو انہوں نے ان کا نام عبد اللہ بن وہب اور بقول بعض ذو القلبین جمیل بن معمر ہیں جن کا ذکر آئے گا۔ یہ سہیلی کا قول ہے جبکہ مشہور یہی ہے کہ یہ اور ہیں۔ واللہ اعلم"],[1193,"§۱۱۹۳ ۔ جمیل بن ردام العذری(1)\nابن مندہ نے عقیق بن یعقوب کے طریق سے بحوالہ عبد الملک بن ابی بکر بن محمد بن عمرو بن حزم، اپنے والد سے وہ اپنے دادا عمرو بن حزم سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے جمیل بن ردام عذری کے لیے ایک تحریر لکھوائی: یہ مقام زید کی وہ تحریر ہے جو محمد رسول اللہ (صلی اللہ علیہ وسلم) نے جمیل بن ردام عذری کو عطا کیا، اس میں کوئی اسے جھگڑ نہیں سکتا۔ سیدنا علی(2) رضی اللہ عنہ نے اسے تحریر کیا۔","",{"fn":"(1) السنن الکبریٰ (۱۴۵/۶) المستدرک (۵۱۷/۳) الطبقات (۴۵/۲/۱) کنز العمال (۳۰۳۰۷) جامع المسانید (۱۱۳/۳)\n(2) اسد الغابۃ (۷۸۲) الاستيعاب (۳۳۵)"}],[1194,"§۱۱۹۴ ۔ جمیل بن عامر(1)\nبن حذیم الجمحی سعید کے بھائی۔ نافع بن عمر بن عبد اللہ بن جمیل بن عامر الجمحی المکی مشہور محدث کے دادا۔ ابو عمر کہتے ہیں: مجھے ان کی روایت کا علم نہیں۔","",{"fn":"(1) اسد الغابۃ (۷۸۳) الاستيعاب (۳۳۶)"}],[1195,"§۱۱۹۵ ۔ جمیل بن معمر(1)\nبن حبیب بن وہب بن حذافہ بن جمحی۔ ابو العباس مبرد کامل میں لکھتے ہیں یہ صحابی ہیں۔ سیدنا عمر بن خطاب رضی اللہ عنہ کے خصوصی آدمی تھے۔ ان میں اور جمیل بن عبد اللہ بن معمر عذری کے درمیان کوئی نسب نہیں۔ جو بثینہ والے مشہور شاعر ہیں۔ انہی نے قریش کو سیدنا عمر رضی اللہ عنہ کے اسلام لانے کی خبر دی۔ جیسا کہ سیرۃ ابن اسحاق میں بحوالہ نافع، ابن عمر رضی اللہ عنہما سے مروی ہے، فرماتے ہیں: جب میرے والد مسلمان ہوئے آپ نے فرمایا: کونسا قریشی بات جلدی پہنچاتا ہے؟ کسی نے کہا: جمیل بن معمر جمحی۔ تو انہوں نے اسے اپنے اسلام کی تو خبر دی لیکن کہا کہ اسے پوشیدہ رکھنا۔ وہ اونچی آواز سے پکار کر بولے: عمر بے دین ہو گیا۔ پھر قصہ ذکر کیا۔ بعد میں جمیل بھی اسلام لے آئے اور حنین میں شریک ہوئے۔ زہیر بن انجر کو قتل کیا جس کا مشہور قصہ ہے۔ ابو خراش ہذلی نے مشہور زمانہ اشعار میں زہیر کا مرثیہ کہا۔ کامل میں مبرد لکھتے ہیں: جمیل بن معمر فتح مکہ میں شریک تھے اور ابو حراش ہذلی کے بھائی کو قتل کیا۔ ابن یونس فرماتے ہیں: جمیل بن معمر فتح مصر میں موجود تھے اور سیدنا عمر رضی اللہ عنہ کی خلافت میں فوت ہوئے۔ آپ کو ان کی وفات کا بہت صدمہ ہوا۔ میرے خیال میں جب وہ فوت ہوئے سو(۱۰۰) سال کے لگ بھگ تھے۔ کیونکہ جب وہ حرب الفجار میں شریک تھے نو جوان مرد تھے، اور ان کے والد کا اکابر صحابہ میں سے تھے، جیسا کہ آئے گا۔ زبیر لکھتے ہیں کہ سیدنا عمر بن خطاب سیدنا عبد الرحمن بن عوف کے پاس آئے سنا کہ وہ حدی کی طرح کا ایک راگ گا رہے ہیں: ”جب جمیل بن عمر کا مدینہ میں کوئی کام نہیں رہا تو اس کے بعد میرا ٹھہرنا کیا ہوگا“۔ فرمایا: ابو محمد یہ کیا الاپ رہے ہو؟ فرمایا: ہم جب تنہائی میں ہوتے ہیں تو ویسا ہی کہتے ہیں جیسا لوگ کہتے ہیں (یعنی اشعار گنگناتے ہیں) مبرد نے یہ قصہ ذکر کیا ہے تو سیدنا عمر رضی اللہ عنہ بھی یہ شعر گنگنانے لگے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۳۳۷/۱) الاستيعاب (۷۸۴)"}],[1196,"§۱۱۹۶ ۔ جمیل النجرانی(1)\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے اور یعقوب بن شبہ کے طریق سے ان کی سند جو جمیل نجرانی تک ہے روایت کرتے ہیں، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس تھا آپ نے اپنی وفات سے ایک سال پہلے فرمایا: ”میں ہر دوستی والے کی دوستی سے بری ہوں (میں نے اگر کسی کو دوست بنانا ہوتا تو ابو بکر کو بناتا وہ بھی میرے بھائی اور یار غار ہیں)۔ (الحدیث)(2) ابن الاثیر نے اسے مختصر ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۸۴)\n(2) جامع المسانید (۱۱۴/۳)"}],[1197,"§۱۱۹۷ ۔ جناب بن حارثہ\nبن صخر بن مالک بن عبد مناة العذری۔ ابو حاتم بجستانی(1) نے معمرین میں ان کا ذکر کیا ہے کہ حارثہ نے اسلام کا زمانہ پایا لیکن مسلمان نہیں ہوا، البتہ اس کا بیٹا جناب مسلمان ہو گیا اور مدینہ ہجرت کی۔ جس سے ان کے والد نے بہت بے صبری کا مظاہرہ کیا۔ اس کے وہ اشعار بھی ذکر کیے جوان کے متعلق اس نے کہے تھے: ”جب ٹہنیوں پر کبوتری چہکتی ہے تو میرے آنسوؤں کے قطرے لگا تار بہنے لگتے ہیں۔ کبوتری مجھے میری زندگی کی پسندیدہ چیز جناب کی یاد دلاتی ہے۔ جناب سے صلح کے لیے میرا کون مددگار ہے؟ میری جدائی میں تو نے اپنے رب کی طرف سے ثواب کا ارادہ کر لیا ہے جبکہ میری نزدیکی ثواب کے زیادہ نزدیک ہے“۔ یہ اشعار امیہ بن اسکر کے ان اشعار کے مشابہ ہیں جو انہوں نے اپنے بیٹے کلاب کے متعلق کہے تھے۔ ان اشعار سے یہ بھی معلوم ہوتا ہے کہ حارثہ اسلام لے آئے۔","",{"fn":"(1) المعمرین (۷۰/۱)"}],[1198,"§۱۱۹۸ ۔ (ز) جناب بن زید انصاری\nحائے بے نقطی میں تذکرہ آئے گا۔"],[1199,"§۱۱۹۹ ۔ جناب الکنانی (حائط کے والد)(1)\nابن مندہ، عبد اللہ بن العلاء کے طریق سے بحوالہ زہری، سعید بن المسیب سے وہ حائط بن جناب کنانی سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: میں ایک دفعہ جنگل میں تھا کہ ہمارے پاس سے بہت بڑی تعداد میں ایک لشکر گزرا، کسی نے کہا: ”یہ رسول اللہ صلی اللہ علیہ وسلم ہیں“۔ پھر بھی ہم حدیث ذکر کی(2)، جبکہ اس کی اسناد ضعیف ہے۔","",{"fn":"(1) اسد الغابۃ (۷۸۵)\n(2) جامع المسانید (۱۱۵/۳)"}],[1200,"§۱۲۰۰ ۔ جناب الکلبی(1)\nابو عمر نے ان کا ذکر کیا کہ وہ فتح مکہ کے موقع پر اسلام لائے۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ سے سنا آپ ایک درمیانے قد والے شخص سے فرما رہے تھے: میری دائیں طرف جبرائیل بائیں طرف میکائیل ہے۔ فرشتوں نے میرے لشکر پر سایہ کر رکھا ہے تو تم اپنے کوئی اشعار سناؤ۔ اس شخص نے سر جھکا کر پھر کچھ کہنا شروع کیا۔ وہ اشعار ذکر کیے۔ اللہ فرماتے ہیں(2): وہ شخص حسان بن ثابت تھے۔ میں کہتا ہوں: یہ اس حدیث کا ٹکڑا ہے جس کا ذکر پہلے ہو گیا۔ شاید ان کے نسب میں اختلاف ہو۔","",{"fn":"(1) اسد الغابۃ (۷۸۷) الاستيعاب (۳۷۹)\n(2) کنز العمال (۳۲/۴۴) جامع المسانید (۱۱۶/۳)"}],[1201,"§۱۲۰۱ ۔ جنادح بن میمون(1)\nابن مندہ بحوالہ ابن یونس لکھتے ہیں: صحابہ میں ان کا شمار ہے۔ فتح مصر میں شریک ہوئے۔ میں نے مغلطائی کے قلم سے لکھا دیکھا: مجھے ابن یونس کی تاریخ میں ان کا تذکرہ نہیں ملا۔","",{"fn":"(1) اسد الغابۃ (۷۸۸)"}],[1202,"§۱۲۰۲ ۔ جنادہ بن ابی امیہ ازدی(1)\nامام احمد(2)، نسائی اور بغوی نے یزید بن ابی حبیب کے طریق سے بحوالہ ابو الخیر حذیفہ بارقی وہ جنادہ بن ابی امیہ ازدی سے روایت کرتے ہیں کہ وہ آٹھ افراد جس میں سے وہ آٹھویں تھے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ جمعہ کا روز تھا آپ نے ان کے سامنے کھانا پیش کیا۔ حدیث جس میں جمعہ کے دن نفلی روزہ رکھنے کی ممانعت ہے۔ بعض نے ”جنادہ ازدی“ کہا، ابن ابی امیہ نہیں کیا۔ امام احمد(3) بھی یزید کے طریق سے بحوالہ ابو الخیر روایت کرتے ہیں کہ جنادہ بن ابی امیہ نے ان سے بیان کیا کہ بعض صحابہ کہنے لگے: ہجرت ختم ہو گئی جس میں اختلاف ہو گیا تو میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، آپ نے فرمایا: ”جب تک جہاد ہوتا رہے گا ہجرت ختم نہیں ہوگی۔ ابن یونس نے تاریخ مصر میں ذکر کیا ہے کہ وہ فتح مصر میں شریک تھے۔ ان سے ان کی اہلیہ روایت کرتی ہیں۔ جن روایات سے ان کے صحابی ہونے کا پتہ چلتا ہے ان میں اہل مصر کے علاوہ کسی کی ان سے روایت کرنا ثابت نہیں۔ ہاں البتہ طبرانی(4) نے ضعیف سند سے بحوالہ شہر بن حوشب، ابو عبد الرحمن صنعانی سے نقل کیا کہ جنادہ ازدی نے ایک قوم کو نماز پڑھائی۔ (حدیث) اسی میں ہے میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو شخص کسی ایسی قوم کی امامت کرائے جو اسے ناپسند کریں تو اس کی نماز ان کی ناک سے آگے نہیں بڑھتی (یعنی قبول نہیں ہوتی)۔ طبرانی نے اسے انہی جنادہ کے سوانح میں درج کیا ہے۔ یہ پہلی دو حدیثیں صحیح ہیں جن میں ان کے صحابی ہونے کی صحیح صراحت موجود ہے۔ میرے نزدیک ان کے والد کا نام صحیح نہیں۔ ابن السکن نے جنادہ بن مالک ازدی کے حالات میں وہ حدیث ذکر کی ہے جو جنادہ بن ابی امیہ کے سوانح میں گزر چکی ہے۔ ابن مندہ اور ابو نعیم نے بھی ان کی پیروی کی ہے۔ بظاہر یہ وہم ہے۔ واللہ اعلم ادھر ابن سعید (سعد)، ابو حاتم(5)، ابن عبد البر اور کئی ایک نے جنادہ بن ابی امیہ ازدی اور جنادہ بن مالک ازدی کے درمیان فرق کیا ہے۔ عبد الغنی بن سرور مقدسی نے ابو نعیم پر دونوں کو یکجا کرنے پر رد کیا ہے میں پیچھے ذکر کر آیا ہوں۔ ان کے ہاں جنادہ بن ابی امیہ ایک اور شخص بھی ہیں، جن کے والد کا نام کبیر ہے۔ وہ مخضرمی ہیں۔ یعنی نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ شیخین وغیرہ نے ان کی بحوالہ عبادہ بن الصامت روایت نقل کی ہے۔ وہ شام میں رہتے تھے وہیں ۶۷ھ میں فوت ہوئے۔ جن کے متعلق عجلی(6) لکھتے ہیں: اکابر تابعین میں سے ثقہ تابعی ہیں۔ تابعین میں ابن حبان(7) لکھتے ہیں: ان کا صحابی ہونا صحیح نہیں۔ ابن سعد، یعقوب بن سفیان اور ابن جریر نے اکابر تابعین میں ان کا ذکر کیا ہے۔ ابن ابی حاتم بحوالہ اپنے والد فرماتے ہیں: جنادہ ازدی صحابی ہیں۔ لیث، یزید سے وہ حذیفہ ازدی سے وہ (ان جنادہ ازدی) سے روایت کرتے ہیں۔ میں کہتا ہوں: یہی عنوان والی شخصیت ہے جن کے والد کا نام ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۷۸۹) الاستيعاب (۳۴۰)\n(2) مسند احمد (۲۹۶/۳)\n(3) مسند احمد (۶۲/۴)\n(4) المعجم الکبیر (۳۱۷/۲)\n(5) الجرح والتعدیل (۵۳۷/۲)\n(6) تاریخ الثقات (۹۹/۱)\n(7) الثقات (۱۰۳/۴)"}],[1203,"§۱۲۰۳ ۔ جنادہ بن تمیم مالکی کنانی\nسیف نے فتوح میں ذکر کیا کہ ۱۵ھ کو عمرو بن العاص رضی اللہ عنہ نے انہیں اجنادین کے روز لڑائی میں فوج کے ایک دستے کا امیر مقرر فرمایا تھا۔ اور یہ پہلے گزر چکا ہے کہ سیدنا عمر رضی اللہ عنہ کے زمانہ میں صرف صحابہ ہی امیر بنائے جاتے تھے۔ ابن فتحون نے اپنے ذیل میں اس کا تذکرہ کیا ہے۔"],[1204,"§۱۲۰۴ ۔ جنادہ بن جراد عیلانی باہلی(1)\nدارقطنی نے موتلف میں ابن السکن اور ابن شاہین نے زیاد بن قرطج (جو بنی عیلان بن جاؤہ کے ایک فرد ہیں) کے طریق سے بحوالہ ان کے والد وہ جنادہ بن جنادہ ابن جراد (جو بنی عیلان بن جاؤہ بن معن کے ایک شخص ہیں) سے روایت کرتے ہیں: میں نبی صلی اللہ علیہ وسلم کے پاس اپنا اونٹ لے کر گیا جس کی ناک پر میں داغ لگایا تھا۔ آپ نے فرمایا: ”تمہیں سوائے چہرے کے داغنے کے کوئی عضو نہ ملا؟“ (حدیث) ابن السکن(2) فرماتے ہیں: مجھے اس کے علاوہ ان کی کوئی روایت معلوم نہیں جبکہ اس کی بھی سند غیر مشہور ہے۔ میں کہتا ہوں: لفظ عیلانی کو دشاطی نے عین بے نقطہ قلمبند کیا ہے کہ ابن عیلان باہلہ سے تعلق رکھتے ہیں۔ ابن ماکولا(3) اور ابن نقطہ اس نسبت سے ”مشتبه النسبة“ میں بیان کرنے سے غافل رہے ہیں۔ البتہ ابن ماکولا نے عیلان اور غیلان دونوں ذکر کیے ہیں۔ فرماتے ہیں: نقطے والا زیادہ مشہور ہے اور جو بے نقطہ ہے وہ قیس عیلان ہے۔ اور عیلان کی طرف قیس کی نسبت کے سب میں اختلاف کو ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۷۹۲) الاستيعاب (۳۴۲)\n(2) المعجم الکبیر (۲۸۳/۲) مجمع الزوائد (۱۱۰/۸) کنز العمال (۲۵۶۳۶)\n(3) الاکمال (۱۷۸/۲)"}],[1205,"§۱۲۰۵ ۔ جنادہ بن زید حارثی(1)\nابن السکن اور باوردی نے عبد الرحمن بن عمرو بن جبلہ کے طریق سے بحوالہ سودہ بنت متلمس وہ اپنی دادی ام المتمس بنت جنادہ بن زید وہ اپنے والد سے روایت کرتی ہیں، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا، میں نے عرض کیا: میں بحرین سے اپنی قوم بلحارث کا قاصد ہوں، دعا کریں کہ اللہ تعالیٰ ہمیں اپنے دشمنوں پر فتح دے۔ فرماتے ہیں: آپ نے دعا فرمائی اور ہمارے لیے ایک نوشتہ لکھوائی(2) اس کی سند ضعیف اور مجہول ہے۔","",{"fn":"(1) اسد الغابۃ (۷۹۳)\n(2) جامع المسانید (۱۲۳/۳)"}],[1206,"§۱۲۰۶ ۔ جنادہ بن سفیان الجمحی\nاپنے بھائی جابر بن سفیان کے ساتھ عنقریب تذکرہ گزر چکا ہے۔"],[1207,"§۱۲۰۷ ۔ جنادہ بن ابی نبطہ(1)\nعبد اللہ بن علقمہ بن مطلب بن عبد مناف۔ ابو عمر نے ذکر کیا کہ وہ یمامہ میں شہید ہوئے ایسا ہی ابو محمد بن حزم نے جمہرہ النسب میں لکھا ہے کہ جنادہ اور ان کے بھائی ہذیم یمامہ میں شہید ہوئے۔ ان دونوں کا بیٹا کوئی نہ تھا۔","",{"fn":"(1) اسد الغابۃ (۷۹۵) الاستيعاب (۳۴۱)"}],[1208,"§۱۲۰۸ ۔ (ز) جنادہ بن عوف\nبن امیہ ابن قلع بن عباد بن حذیفہ بن عبد بن فقیم بن عدی بن زید بن عامر بن ثعلبہ بن حارث بن مالک بن کنانہ ابو ثمامہ کنانی ابن اسحاق نے سیرت کی ابتداء میں اسی کی رسم ذکر کرنے کے بعد کہا: جنادہ بن عوف پر اسلام کا دور آیا، لیکن یہ ذکر نہیں کیا کہ وہ مسلمان ہوئے۔ سہیلی لکھتے ہیں: مجھے ان کے متعلق ایک حدیث ملی ہے جس سے پتہ چلتا ہے وہ اسلام لائے تھے۔ اس واسطے کہ وہ حج کے موسم میں سیدنا عمر رضی اللہ عنہ کے زمانہ میں آئے تھے۔ لوگوں کو دیکھا کہ وہ حجر اسود کو چومنے میں بھیڑ بنائے ہوئے ہیں۔ کہا: لوگو! میں نے یہ پتھر تم سے اجرت پر لے لیا تھا۔ سیدنا عمر رضی اللہ عنہ نے انہیں ڈرے سے آہستہ سے مار کر فرمایا: خاموش رہو! اللہ تعالیٰ نے جاہلیت کے معاملات ختم کر دیئے ہیں۔ ہشام بن کلبی نے ذکر کیا کہ انہوں نے چالیس سال اسی کی رسم رکھی، بہت پرانی یاد اور لمبی عمر والے تھے۔ زبیر نے کتاب النسب میں لکھا کہ قلقطس کے بعد سب سے پہلے جس نے نسی کی رسم شروع کی وہ حذیفہ بن عبد بن فقیم بن عدی تھا۔ وہ قلقطس بن عامر بن ثعلبہ پھر عباد بن حذیفہ پھر قلع پھر امیہ بن قلع پھر عوف بن امیہ پھر جنادہ ہے۔ انبی کے دور میں اسلام کا ظہور ہوا۔ بقول بعض انہوں نے چالیس سال نسی کی رسم جاری رکھی۔ اسی طرح ابو عبیدہ کے حوالہ سے ذکر کیا کہ ابو ثمامہ جنادہ بن عوف کے دور میں اسلام کا ظہور ہوا۔ پھر محمد بن حسن سے بحوالہ معمر، ابن ابی یحیٰ، مجاہد سے نقل کیا کہ سب سے پہلے حارث بن ثعلبہ بن مالک بن کنانہ نے نسی کی رسم شروع کی اور سب سے آخر میں ابو ثمامہ نے، ان کا نام امیہ بن عوف بن جنادہ بن عوف بن عباد بن قلع بن فقیم بن عدی بن عامر بن حارث بن ثعلبہ ہے۔ حارث تک سب نے نسی کی رسم رکھی۔"],[1209,"§۱۲۰۹ ۔ جنادہ بن مالک ازدی(1)\nابو عبد اللہ: ابن سعد۔ ابن السکن اور طبرانی نے ولید بن قاسم کے طریق سے بحوالہ مصعب بن عبد اللہ بن جنادہ وہ اپنے والد وہ اپنے دادا سے وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ آپ نے فرمایا: ”تین باتیں جاہلیت کی ہیں جنہیں مسلمان نہیں چھوڑیں گے:(۱) ستاروں کے ذریعہ بارش کی طلب۔(۲) نسب (میں) پر طعن زنی۔(۳) اور میت پر نوحہ کرنا“۔(2) اسے امام بخاری رحمہ اللہ نے اپنی تاریخ میں روایت کر کے فرمایا: اس کی سند میں تامل ہے۔ اس میں پہلے جنادہ بن ابی امیہ کے سوانح میں بتا چکا ہوں کہ اس کے متعلق ابن مندہ کو وہم ہوا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۹۶) الاستيعاب (۳۳۸)\n(2) التاریخ الکبیر (۲۱۳/۲) اسد الغابۃ (۷۹۸)"}],[1210,"§۱۲۱۰ ۔ جنادہ (بے نسبت)(1)\nابن مندہ نے پہلی سند سے جمیل بن ردام بن عمرو بن حزم کے سوانح میں روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جنادہ کے لیے تحریر لکھوائی: ”یہ خط محمد رسول اللہ (صلی اللہ علیہ وسلم) کی طرف سے جنادہ، اس کی قوم اور اس کے تابعین کے لیے نماز قائم کرنے، زکوۃ ادا کرنے، جو اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت کرے تو اس کے لیے اللہ تعالیٰ اور محمد (صلی اللہ علیہ وسلم) کی ذمہ داری ہے“۔(2)","",{"fn":"(1) جامع المسانید (۱۲۴/۳)\n(2) جامع المسانید (۱۲۴/۳)"}],[1211,"§۱۲۱۱ ۔ (ز) جندب\nجیم پر پیش نون ساکن، اس کے بعد یا پیش والی آخر میں ڈال نقطے والی، بقول بعض نون کے بعد یا پھر دال بے نقطی تصغیر کا صیغہ ہے۔ ابن سبع، بعض نے ابن سباع کہا ہے ابو جمعہ کنیوں میں تذکرہ آئے گا۔ ان کی اسی نام سے معجم طبرانی(1) میں ایک حدیث ہے۔","",{"fn":"(1) المعجم الکبیر (۲۹۰/۲)"}],[1212,"§۱۲۱۲ ۔ (ز) جندب بن الاعجم الاسلمی\nواقدی نے مغازی میں غزوہ حنین کے ذیل میں ان کا ذکر کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کی ترتیب دی پرچم اور جھنڈے بنائے۔ قبیلہ اسلم کے دو جھنڈے تھے، ایک بریدہ بن حصیب کے پاس دوسرا جندب بن اعجم کے پاس۔"],[1213,"§۱۲۱۳ ۔ (ز) جندب بن الادلع الہذلی\nابن اسحاق اور واقدی فرماتے ہیں: فتح مکہ کے موقع پر حراس بن امیہ نے انہیں جاہلیت کے باہمی خون کے بدلہ جو ان میں تھا قتل کر دیا تھا۔ تو نبی صلی اللہ علیہ وسلم نے خزاعہ کو دیت ادا کرنے کو کہا۔ طبری نے بحوالہ ابن اسحاق یہ قصہ ذکر کیا تو ان کا نام جندب تصغیر سے لیا۔"],[1214,"§۱۲۱۴ ۔ جندب بن جنادہ\nابو ذر غفاری، کنیتوں میں تذکرہ آئے گا۔"],[1215,"§۱۲۱۵ ۔ (ز) جندب بن حارث\nبن وحشی ابن مالک الکعبی۔ ابو ظبیان حصین بن جندب جو مشہور تابعی ہیں ان کے والد۔ بقول بعض صحابی ہیں۔ معافی بن ذکریا نے ”جلیس“ میں ان کی ایک روایت سعد بن عامر کے طریق سے بحوالہ قابوس بن ابی ظبیان، ان کے والد سے وہ اپنے دادا سے روایت کرتے ہیں۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ سیدنا حسن کی رانوں میں سے ان کی ناف پر بوسہ دے رہے تھے۔ یہ حدیث اجنبی ہے۔ اسے طبرانی نے کبیر میں دوسری سند سے بحوالہ قابوس روایت فرماتے ہیں ان کے والد سے وہ ابن عباس رضی اللہ عنہما سے۔ واللہ اعلم۔ بقول بعض: صحابی ان کے دادا ہیں، اس لحاظ سے ان کے دادا کی ضمیر ابو ظبیان کی جانب ہوگی۔ حائے بے نقطی میں آئے گا۔"],[1216,"§۱۲۱۶ ۔ جندب بن حیان\nابو رمشہ کنیتوں میں ذکر آئے گا۔ ابن البرقی نے ان کا نام جندب بتایا ہے۔"],[1217,"§۱۲۱۷ ۔ جندب بن خالد\nبن سفیان، ابن عبد اللہ میں تذکرہ ہوگا۔"],[1218,"§۱۲۱۸ ۔ جندب بن زہیر(1)\nبن حارث بن کثیر بن سبخ بن مالک ازدی غامدی۔ بعض لوگ، جندب بن عبد اللہ بن زہیر غامدی کہتے ہیں۔ ابن کلبی نے تفسیر میں ابو صالح سے بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے کہ جندب بن زہیر غامدی جب نماز پڑھتے یا روزہ رکھتے یا صدقہ کرتے تو اس کی وجہ سے بہت راحت محسوس کرتے جس پر آیت: ”پس جسے اپنے رب سے ملنے کی امید ہو (یقین کے درجہ میں) اسے چاہیے کہ وہ نیک عمل کرے“۔ (سورۃ الکہف: ۱۱۰) نازل ہوئی۔ عمیر بن حارث ازدی کے سوانح میں بھی ان کا ذکر ہے کہ وہ اپنی قوم کی جماعت میں نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ان میں جندب بن زہیر، مخف بن سلیم، عبد اللہ بن سلیم اور جندب بن کعب وغیرہ حضرات شامل تھے۔ علی بن سعد ”الطاعة والمعصیة“ نامی کتاب میں مقاتل کے طریق سے بحوالہ عکرمہ سیدنا ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ ازد کا ایک جندب بن زہیر غامدی نامی شخص نبی صلی اللہ علیہ وسلم کے سامنے کھڑے ہو کر عرض کرنے لگا: میرے ماں باپ آپ پر قربان، میں جب آپ کے پاس سے اٹھ کر جاتا ہوں تو نہ مال سے دل بہلتا ہے نہ اولاد سے، جب تک واپس نہ آؤں چین نہیں ملتا۔ آپ صلی اللہ علیہ وسلم کو دیکھتا ہوں تو قرار ملتا ہے۔ کیا قیامت کی ہولناکی میں آپ صلی اللہ علیہ وسلم کا ساتھ میسر ہوگا؟ اس کے بعد قیامت کے ہولناک مناظر کے بارے میں لمبی حدیث ذکر کی۔ مقاتل ضعیف راوی ہے۔ ابن سعد اپنی سند سے روایت کرتے ہیں کہ وہ جنگ جمل میں سیدنا علی رضی اللہ عنہ کے ساتھ تھے۔ خلیفہ علی بن زید کے طریق سے بحوالہ حسن روایت کرتے ہیں کہ جندب بن زہیر جنگ صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ تھے۔ ایسا ہی ان کا ذکر مفضل غلابی نے اپنی تاریخ میں کیا ہے۔ فرماتے ہیں: جنگ جمل کے روز عبد اللہ بن زبیر رضی اللہ عنہما نے ہمارا چناؤ کیا۔ اتنے میں سیدنا علی رضی اللہ عنہ کے حواریوں میں سے ایک شخص گویا ہم سے خیر خواہی کرنے باہر آیا، کہنے لگا: قریشی جوانو! میں تمہیں دو آدمیوں سے آگاہ کرتا ہوں، ایک جندب بن زہیر غامدی دوسرا اشتر۔ ان کی تلواروں کے سامنے تم نہ ٹھہرنا۔ رہا جندب تو وہ ایسا شخص ہے جس کا قد میانہ ہے، وہ جب اپنی زرہ کھینچتا ہے تو اس کا نشان تک(2) منا دیتا ہے۔ ابن عبد البر فرماتے ہیں: زبیر نے ذکر کیا۔ جادوگر کے قاتل یہی جندب بن زہیر ہیں۔ لیکن صحیح یہ ہے کہ وہ اور شخص ہیں۔ جندب بن زہیر کے صحابی ہونے میں اختلاف ہے۔ اور سری بن اسماعیل کی وجہ سے ان کی حدیث کے متعلق ناقدین نے کلام کیا ہے۔ میں کہتا ہوں: زبیر نے بحوالہ اپنے چچا ”کتاب الموفقیات“ میں جندب بن زہیر اور جندب بن کعب ابن کعبہ جادوگر کے قاتل کے درمیان فرق کیا ہے۔ ایسا ہی فرق ابن کلبی نے بھی کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۰۲)\n(2) اسد الغابۃ (۳۴۵/۱)"}],[1219,"§۱۲۱۹ ۔ (ز) جندب بن سفیان ابن عبد اللہ\nتذکرہ آئے گا۔"],[1220,"§۱۲۲۰ ۔ جندب بن ضمرہ\nجندع میں ذکر ہوگا۔"],[1221,"§۱۲۲۱ ۔ (ز) جندب بن عبد اللہ(1)\nبن ارقم ازدی غامدی۔ انہیں جندب الخیر بھی کہا جاتا ہے۔ ابن کلبی نے اس کا ذکر کیا ہے۔ زبیر بن بکار فرماتے ہیں: میرے چچا مصعب نے فرمایا: جنادب جن کا تعلق ازد سے ہے ان کے نام یہ ہیں: جندب بن عبد بن سفیان، جندب بن عبد اللہ بن جبیر، جندب بن زہیر بقول بعض تصغیر ہے جندب بن کعب جادوگر کے قاتل اور جندب بن عفیف۔","",{"fn":"(1) الاستيعاب (۳۴۷)"}],[1222,"§۱۲۲۲ ۔ (ز) جندب بن عبد اللہ بن زہیر\nابن زہیر میں تذکرہ ہو چکا ہے۔"],[1223,"§۱۲۲۳ ۔ (ز) جندب بن عبد اللہ\nجادوگر کے قاتل ابن کعب میں ذکر ہوگا۔"],[1224,"§۱۲۲۴ ۔ (ز) جندب بن عبد اللہ(1)\nبن سفیان بجلی ثم علقی۔ ابو عبد اللہ، اپنے دادا کی طرف منسوب ہو کر جندب بن سفیان بھی کہلاتے ہیں۔ پہلے کوفہ پھر بصرہ میں رہائش پذیر ہوئے، جہاں مصعب بن زبیر کے ساتھ آئے۔ ان سے دونوں شہروں کے لوگ روایت کرتے ہیں۔ میں کہتا ہوں: اہل شام میں سے ان سے شہر بن حوشب روایت کرتے ہیں، فرماتے ہیں: مجھے جندب بن سفیان نے بتایا، ابن السکن فرماتے ہیں کہ اہل بصرہ انہیں جندب بن عبد اللہ اور اہل کوفہ جندب بن سفیان کہتے ہیں، حالانکہ اس میں کوئی اور شریک نہیں وہ ایک ہی شخصیت ہے۔ انہیں جندب الخیر بھی کہا جاتا ہے۔ جس کا ابن کلبی نے انکار کیا ہے۔ بغوی فرماتے ہیں: انہیں جندب الخیر، جندب الفاروق اور جندب بن ام جندب کہا جاتا ہے۔ ابن حبان(2) فرماتے ہیں: جندب بن عبد اللہ بن سفیان، جس نے انہیں ابن سفیان کہا تو دادا کی نسبت سے۔ بقول بعض جندب بن خالد بن سفیان جبکہ پہلا نسب زیادہ صحیح ہے۔ طبرانی نے بھی اسی سے ملتا جلتا قول ذکر کیا ہے۔ طبرانی(3) میں ابو عمران جونی کے طریق سے روایت کرتے ہیں، فرماتے ہیں: مجھے جندب نے بتایا کہ میں نبی صلی اللہ علیہ وسلم کے عہد میں طاقتور لڑکا تھا۔ صحیح مسلم(4) میں صفوان بن محرز کے طریق سے مروی ہے کہ جندب بن عبد اللہ بجلی نے عبد اللہ بن زبیر کی شورش کے زمانہ میں عسعس بن سلامہ کی طرف پیام بھیجا کہ میرے لیے اپنے بھائیوں کو یکجا کرو۔ طبرانی میں حسن کے طریق سے مروی ہے، فرمایا: میں مصعب بن زبیر کی امارت کے دور میں جندب کے پاس بیٹھا۔","",{"fn":"(1) اسد الغابۃ (۸۰۴) الاستيعاب (۳۴۴)\n(2) الثقات (۵۶/۳)\n(3) المعجم الکبیر (۱۵۸/۲)\n(4) مسلم کتاب الایمان باب تحریم قتل الکافر بعد ان قال: لا الہ الا اللہ (۲۷۵)"}],[1225,"§۱۲۲۵ ۔ (ز) جندب بن عفیف ازدی\nجندب بن کعب میں تذکرہ آئے گا۔"],[1226,"§۱۲۲۶ ۔ جندب بن عمار\nبن نعیم بن شہاب ابن لام بن عمرو بن طریف الطائی ثم الملآئی۔ ابن کلبی نے ان کا نسب بیان کیا کہ وہ شاعر تھے قادسیہ میں شریک ہوئے۔ مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے پھر قادسیہ میں شریک ہوئے۔ وہی یہ اشعار کہتے ہیں: طعنہ زنوں کا گمان ہے کہ جندب کی اونٹنی گاؤں کے ایک طرف بے پالان جھاڑیوں کے جھنڈ میں تھی۔ طعنہ زنوں نے جھوٹ کہا وہ اگر قادسیہ میں اس کے بیٹھنے کی جگہ دیکھ لیتے تو کہتے اس کا سوار صفوں میں گھسا رہا اور اونٹنی اس کے تابع رہی ہے۔ اگر کوئی بھدی آواز والا شخص اس کی گردن کے نیچے ستار بجاتا ہوا ترنم سے گاتا تو یہ بھی چیخنے لگتی۔"],[1227,"§۱۲۲۷ ۔ جندب بن عمرو(1)\nبن حممہ دوسی۔ بنی امیہ کے حلیف۔ موسیٰ بن عقبہ نے بحوالہ ابن شہاب اور ابو الاسود نے بحوالہ عروہ اجنادین کے روز شہید ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: ان کی کوئی حدیث مشہور نہیں۔ زبیر نے کتاب النسب میں عبد العزیز بن عمران کے طریق سے بحوالہ محرز بن جعفر وہ اپنے دادا سے روایت کرتے ہیں۔ فرمایا: جندب بن عمرو بن حممہ دوسی ہجرت کر کے آئے۔ پھر شام کی طرف چل نکلے اور اپنی بیٹی ام ابان سیدنا عمر رضی اللہ عنہ کے پاس چھوڑ گئے اور یہ کہہ گئے کہ اگر کوئی کفو (برابری کا رشتہ) ملا تو اس کی شادی کر دینا، اگر چہ (ہونے والے خاوند کے) تتے کے بدلے ہو ورنہ اس وقت تک روکے رکھنا جب تک وہ اپنی قوم کے گھرانے سے نہیں جا ملتی۔ چنانچہ وہ بچی سیدنا عمر رضی اللہ عنہ کے ہاں ٹھہری رہی۔ وہ آپ کو ابا کہہ کر بلاتی یہاں تک کہ سیدنا عمر رضی اللہ عنہ نے سیدنا عثمان رضی اللہ عنہ سے اس کی شادی کر دی۔ اور سیدنا عمر رضی اللہ عنہ کے دور میں ہی ان سے عمرو بن عثمان پیدا ہوئے جن کا تذکرہ طفیل بن عمرو کے سوانح میں آئے گا۔ ابن کلبی فرماتے ہیں: جندب بن عمرو بن حممہ بن حارث بن رافع بن ربیعہ بن ثعلبہ بن لوی بن عامر بن غانم بن دہمان بن منہب بن دوس کے والد عرب کے فیصل لوگوں میں سے تھے۔ ابن درید فرماتے ہیں: ہمیں سکن بن سعید نے بحوالہ محمد بن عباد، شرقی سے وہ مجالد شعبی سے روایت کر کے بتاتے ہیں: ہم لوگ ابن عباس رضی اللہ عنہما کے پاس تھے، آپ اس وقت زمزم کے کنارے لوگوں کو مسائل بتا رہے تھے۔ اچانک ایک شخص آپ کے پاس آ کر کہنے لگا: آپ نے لوگوں کو تو بتا دیا اب ہمیں بتائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: بولو! اس نے کہا: شاعر کے اس قول کا کیا مطلب ہے: ”فیصلے والے کے لیے آج سے پہلے لاٹھی نہیں کھٹکھٹائی جاتی تھی، انسان کو اسی لیے سکھایا گیا تھا کہ وہ جان جائے“۔ تو سیدنا ابن عباس رضی اللہ عنہما نے اس سے فرمایا: اس سے مراد عمرو بن حممہ دوسی ہے۔ انہوں نے تین سال تک عربوں کے فیصلے کیے جب وہ بوڑھے ہو گئے تو ان کی اولاد میں سے ساتویں یا نویں بیٹے کو ان کے ساتھ کر دیا۔ تو وہ جب غافل ہو جاتے تو وہ نوجوان لاٹھی کھٹکھٹاتا۔ جب ان کی وفات کا وقت ہوا تو ان کے پاس ان کی قوم اکٹھی ہوئی، انہوں نے انہیں بہت اچھی وصیت کی جس میں حکمت کی باتیں تھیں۔","",{"fn":"(1) اسد الغابۃ (۸۰۵)"}],[1228,"§۱۲۲۸ ۔ (ز) جندب بن کعب(1)\nبن عبد اللہ بن جزء بن عامر بن مالک بن دہمان بن ازدی غامدی ابو عبد اللہ، بسا اوقات اپنے دادا کی طرف منسوب کیے جاتے ہیں۔ جندب الخیر اور جادوگر کے قاتل بھی یہی ہیں۔ جندب بن زہیر کے سوانح میں پہلے ان کا تذکرہ ہوا ہے۔ ابن حبان(2) فرماتے ہیں: جندب بن کعب ازدی صحابی ہیں۔ ابو حاتم(3) فرماتے ہیں: جندب بن کعب جادوگر کے قاتل ہیں۔ بقول بعض جندب بن زہیر یوں انہوں نے دونوں شخصوں کو ایک کر دیا۔ ابن سعد بحوالہ ہشام بن کلبی فرماتے ہیں، ہمیں لوط بن یحییٰ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ابو ظبیان ازدی ابن عامد کو خط لکھ کر انہیں اور ان کی قوم کو اسلام کی دعوت دی۔ تو انہوں نے اپنی قوم کی ایک جماعت سمیت یہ دعوت قبول کی۔ جن میں مخنف، عبد اللہ اور زہیر بنی سلیم، عبد شمس بن عفیف بن زہیر شامل تھے۔ یہ لوگ تو مکہ میں آپ کے پاس آئے۔ مدینہ میں آپ کے ہاں آنے والوں میں جندب بن زہیر، جندب بن کعب، اور حجر بن مرقع تھے۔ بعد میں چالیس آدمیوں کے ساتھ حکم بن مغفل آئے۔ امام بخاری رحمہ اللہ(4) نے اپنی تاریخ میں خالد الحذاء کے طریق سے بحوالہ ابو عثمان روایت کی ہے کہ ولید بن عقبہ بن ابی معیط کے پاس ایک ساحر تھا جو انسان کو ذبح کر کے اس کا سر جدا کرتا تھا، ہمیں اس سے بڑا تعجب ہوتا، وہ پھر سر کو جوڑ دیتا۔ جندب ازدی نے آ کر اسے قتل کر دیا اور عاصم کے طریق سے بحوالہ ابو عثمان مروی ہے جندب بن کعب نے اسے قتل کیا۔ دلائل میں بیہقی نے ابن وہب کے طریق سے بحوالہ ابن لہیعہ، ابو الاسود سے روایت کیا ہے کہ ولید بن عقبہ بن ابی معیط عراق کے امیر تھے۔ ان کے سامنے ایک انسان کرتب دکھاتا وہ ایک شخص کا سر کاٹ دیتا پھر چھج کر اسے پکارتا تو وہ کپڑے سے باہر نکل کر کھڑا ہو جاتا۔ وہ شخص دوبارہ اس میں سر لگا دیتا۔ جس پر لوگ کہنے لگے: سبحان اللہ! یہ تو مردوں کو زندہ کرتا ہے۔ مہاجرین میں سے ایک نیک شخص کی نظر اس پر پڑی تو دوسرے دن اپنی تلوار لیے آ پہنچے۔ وہ شخص اپنا کرتب دکھانے لگا، انہوں نے اپنی تلوار سونتی اور اس کی گردن اتار کر فرمایا: اگر سچا ہے تو اپنے آپ کو زندہ کرے۔ ولید نے انہیں قید کا حکم سنا دیا۔ تھانیدار کا نام دینار تھا۔ وہ بھی نیک آدمی تھا۔ اسے اس طرح کا آدمی اچھا لگا۔ وہ ان سے گویا ہوا: ”آپ چلے جائیں آپ کے متعلق اللہ تعالیٰ مجھ سے کبھی نہیں پوچھے گا“۔ زید بن صوحان کے سوانح میں اس کا حدیث بریدہ سے دوسرا طریق آئے گا۔ ابن کلبی فرماتے ہیں: مذکورہ جادوگر کا نام بستانی تھا۔ استیعاب میں ابو بستان لکھا ہے۔ ”نصوص“ صاعد لغوی اس کا نام بطورونا بتاتے ہیں۔ ابن السکن، یحییٰ بن کثیر بصری کے شاگرد کے طریق سے بحوالہ اپنے والد وہ جریری وہ عبد اللہ بن بریدہ سے وہ اپنے والد سے روایت کرتے ہیں: آپ صلی اللہ علیہ وسلم اپنے صحابہ کی جماعت کو کہیں لے کر گئے۔ آپ فرمانے لگے: جندب کہاں ہے؟ جندب کی کیا شان ہے! یہاں تک کہ صبح ہو گئی۔ صحابہ نے سیدنا ابو بکر رضی اللہ عنہ سے کہا: آپ علیہ السلام نے دو لفظ بولے ہیں جن کا مطلب ہم نہیں سمجھے؟ اس پر آپ نے فرمایا: ”وہ ایک تلوار مارے گا اور اس کیلئے پوری امت جتنا کارنامہ سر انجام دے گا“۔ فرماتے ہیں: جب سیدنا عثمان رضی اللہ عنہ نے ولید بن عقبہ کو کوفہ کا گورنر بنایا تو انہوں نے ایک ایسا شخص بٹھایا جو انہیں یہ کرتب دکھاتا گویا وہ زندہ کرتا اور مارتا ہے۔ پھر جندب کا اسے قتل کرنے کا قصہ ذکر کیا۔ ان کا مقدمہ سیدنا عثمان رضی اللہ عنہ کے ہاں پیش ہوا۔ آپ نے ان سے فرمایا: تم نے اسلام میں تلوار اٹھائی؟ اگر میں نے رسول اللہ صلی اللہ علیہ وسلم سے تمہارے متعلق نہ سنا ہوتا تو تمہیں مدینہ کی عمدہ تلوار سے قتل کر دیتا۔ پھر انہیں جبل دخان(5) کی جانب چلے جانے کا حکم دیا۔ استیعاب میں دوسری سند سے مروی ہے کہ جندب کے بھتیجے نے تھانیدار کو مار کر اپنے چچا کو نکال لیا اور اس کے متعلق اشعار کہے: ”کیا جادوگر کو مارنے کی وجہ سے جندب کو جیل میں ڈالا جاتا ہے اور نبی صلی اللہ علیہ وسلم کے پہلے صحابہ کو قتل کی دھمکی دی جاتی ہے“۔ ع ترمذی(6) نے حسن کے طریق سے بحوالہ جندب بن کعب روایت کیا ہے کہ جادوگر کی حد تلوار سے اس کا قتل ہے اور اس حدیث کے موقوف ہونے کو راجح کہا ہے۔ طبرانی(7) نے جندب بن عبد اللہ بجلی کے سوانح میں جادوگر کی حد کی حدیث نقل کی ہے۔ درست یہی ہے کہ وہ دو سرے ہیں۔ ابن قانع اور حسن بن سفیان نے حضرت حسن کے حوالہ سے دو سندوں سے اسے جندب الخیر سے نقل کیا ہے کہ وہ ساحر کے پاس آئے اور تلوار سے اس کی گردن اتار دی۔ وہ مر گیا اور فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، پھر وہ حدیث ذکر کی۔","",{"fn":"(1) اسد الغابۃ (۸۰۶)\n(2) الثقات (۵۷/۳)\n(3) الجرح والتعدیل (۵۱۱/۲)\n(4) التاریخ الکبیر (۲۲۲/۱)\n(5) تہذیب تاریخ دمشق (۱۴/۶) الطبقات الکبریٰ (۸۶/۶) کنز العمال (۳۲۲۳۴) (۳۶۹۱۹)\n(6) ترمذی کتاب الحدود باب ما جاء فی حد الساحر (۱۴۶۰)\n(7) المعجم الکبیر (۱۷۷/۲)"}],[1229,"§۱۲۲۹ ۔ جندب بن مکیث(1)\nشروع کا زبر آخر میں تا ہے۔ ابن عمرو بن جراد بن یربوع بن غیل بن عدی بن ربعہ بن رشدان جہنی، رافع بن مکیث کے بھائی۔ ابن سعد(2) فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے انہیں جہینہ کی زکوٰۃ پر مقرر فرمایا، بغوی نے ابن اسحاق کے طریق سے بحوالہ یعقوب بن عقبہ، مسلم بن عبد اللہ وہ جندب بن مکیث سے روایت کرتے ہیں، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے غالب لیثی کو ایک سریہ میں بھیجا، میں بھی ان میں شامل تھا۔ پھر لمبا قصہ ذکر کیا۔ عسکری(3) لکھتے ہیں: جندب بن عبد اللہ بن مکیث اپنے دادا کی طرف منسوب کیے جاتے ہیں، جبکہ اور دوں نے دونوں میں فرق کیا ہے اور دوسرے شخص کو پہلے کا بھتیجا بتایا ہے۔ ابن الاثیر نے اسی کو راجح قرار دیا ہے۔ لیکن اس کے بعض طرق میں اس حدیث کے متعلق جسے ابن اسحاق نے ذکر کیا اور وہ طبرانی میں ہے جندب بن عبد اللہ جہنی سے مروی لکھا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۰۷) استیعاب (۳۴۵)\n(2) الطبقات الکبریٰ (۶۷/۴)\n(3) ابوداؤد کتاب الجہاد باب فی الاسیر یوثق (۲۶۷۸) المعجم الکبیر (۱۷۸/۲) السیرة النبویة (۲۸۲/۴) جامع المسانید (۱۴۹/۳)"}],[1230,"§۱۲۳۰ ۔ جندب بن ناجیہ\nناجیہ بن جندب میں ذکر ہوگا۔"],[1231,"§۱۲۳۱ ۔ (ز) جندب بن نعمان ازدی\nابو عزیز۔ ابن عساکر نے اپنی تاریخ میں لکھا ہے: میں نے ابو الحسین رازی کی کتاب میں پڑھا ہے: ابو ظفر بن محمد بن عمر بن حفص بن عمر بن سعید بن ابی عزیز ازدی نے مجھ سے اپنے والد کے حوالہ سے وہ اپنے والد ظفر سے وہ اپنے والد عمر سے وہ اپنے والد حفص سے وہ اپنے والد عمر سے وہ اپنے والد سعید بن ابی عزیز سے روایت کرتے ہیں کہ ابو عزیز جندب بن نعمان ازدی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ اسلام قبول کیا۔ ان کا اسلام بہت اچھا رہا وہ اپنی قوم کے ناظم بنائے گئے۔ بعد میں خلافت فاروقی میں شام ہجرت کر گئے دمشق رہائش رکھی دار نخلہ سے ان کا گھر مشہور ہے۔ وہیں وہ خود ان کا بیٹا سعید اور پوتا عمر بن سعید دفن ہوئے تھے۔ پھر حفص بن عمر بن سعید(1) زملکا منتقل ہو کر وہیں مقیم ہو گئے۔ اس کی سند اوپر کی ہے۔ اس کے راویوں کو میں صرف اسی سند میں جانتا ہوں۔ یہی روایت ابو عمر نے کنیٰ میں مختصر ذکر کی لیکن انہوں نے ابو عزیز بن جندب کہا، فرماتے ہیں: بقول وہی جندب ہیں۔","",{"fn":"(1) جامع المسانید (۱۵۲/۳)"}],[1232,"§۱۲۳۲ ۔ جندب (بے نسبت)(1)\nبقی بن مخلد نے اپنی مسند میں قیس بن ربیع کی روایت سے بحوالہ زہیر بن ابی ثابت سے وہ ابن جندب سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اے اللہ! میرے ستر پر پردہ ڈال۔ مجھے میرے خوف میں امن دے، اور میرا قرض ادا فرما“۔(2) ابن مندہ نے دوسری سند سے بحوالہ قیس اسے روایت کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۱۰)\n(2) مسند احمد (۲۵/۲) المعجم الکبیر (۴/۹۴، ۱۲/۳۴۲) جمع الجوامع (۹۷۱۷) موارد الظمآن (۲۳۵۶) کنز العمال (۴۹۹۷) جامع المسانید والسنن (۱۵۷/۲)"}],[1233,"§۱۲۳۳ ۔ جندرہ بن خیشنہ ابو قرصافہ کنانی\nکنیتوں میں ذکر آئے گا۔"],[1234,"§۱۲۳۴ ۔ جندع بن ضمرہ(1)\nبن ابی العاص جندعی ضمری یا لیثی۔ سیرہ میں ابن اسحاق بحوالہ یزید بن عبد اللہ بن قسیط ان کی قوم کے رجال سے روایت کرتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے مدینہ ہجرت کی، اس وقت جندع بن ضمرہ بن ابی العاص مسلمان شخص تھے، ان سے تاخیر ہو گئی۔ پھر وہ حدیث ذکر کی جس میں وہ اپنے بیٹوں سے کہتے ہیں: مجھے مکہ سے باہر لے چلو۔ چنانچہ وہ ہجرت کی غرض سے نکلے اور راستے میں ہی انتقال کر گئے۔ جس پر یہ آیت نازل ہوئی: ”جو شخص اپنے گھر سے اللہ تعالیٰ اور اس کے رسول کی طرف ہجرت کر کے نکلا۔۔۔“۔ (سورۃ النساء: ۱۰۰) ابن اسحاق سے یہی مشہور ہے۔ اسی روایت کو حماد بن سلمہ نے ابن اسحاق سے روایت کر کے ”جندب بن ضمرہ“ کہا، اسی پر واقدی نے اعتماد کیا ہے اور ابن مندہ نے جابر بن عبد اللہ کے طریق سے بحوالہ سفیان بن عیینہ، ابن طاؤس سے وہ اپنے والد سے وہ ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں۔ بنی لیث کا ایک شخص تھا جس کا نام جندب بن ضمرہ تھا پھر وہ روایت ذکر کی۔ ابو یعلی اور ابن ابی حاتم اشعث کے طریق سے بحوالہ عکرمہ، ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں، فرمایا: ”ضمرہ بن جندب“ نکلے اور ابن مندہ نے حکم بن ابان کے طریق سے بحوالہ عکرمہ، ابن عباس رضی اللہ عنہما سے نقل کیا: ”ضمرہ یا ابن ضمرہ“ اسی سند سے ابن ابی حاتم روایت کرتے ہیں: ”ضمرہ“ شک کا اظہار نہیں کیا۔ اور فاکہی نے ابن جریج کے طریق سے فرمایا: جندب بن ضمرہ، اور فرماتے ہیں: مولٰی ابن عباس ضمرہ کہتے تھے۔ ابن عیینہ کے طریق سے بحوالہ عمرو بن دینار عکرمہ سے مروی ہے کہ بنی بکر کے ایک شخص نے کہا، پھر وہ واقعہ ذکر کیا۔ ابن عیینہ فرماتے ہیں: ہمیں یہ روایت ملی ہے کہ وہ ضمرہ بن جندب ہیں اور سعید بن جبیر نے فرمایا: ضمرہ بن العیص، بقول بعض جوان سے مروی ہے، ابو ضمرہ بن العیص۔ واللہ اعلم بلاذری اور سراج نے ابو بشر کے طریق سے بحوالہ سعید بن جبیر نقل کیا، فرماتے ہیں: خزاعہ کے ضمرہ بن العیص یا العیص بن ضمرہ بن زنباع نامی ایک شخص تھے۔ ابن ابی حاتم نے سالم افطس کے طریق سے بحوالہ سعید بن جبیر روایت کیا ہے کہ ”ابو ضمرہ بن العیص“ نکلے۔ عبد الغنی بن سعید ثقفی اپنی تفسیر میں عطاء اور ضحاک کے طریق سے بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں، ضمضم بن عمرو نکلے۔ ان کے علاوہ نے ضمرہ بن عمرو کہا ہے۔ ابن عبد البر نے اشعث کے سابقہ طریق سے جو انہوں نے ذکر کیا، ضمرہ بن جندب کہا بقول بعض ابن حبیب اور ابن انس۔ واقد عطاء خراسانی کے طریق سے ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں۔ آپ نے ”حبیب بن ضمرہ“ فرمایا۔","",{"fn":"(1) اسد الغابۃ (ت ۸۱۲)"}],[1235,"§۱۲۳۵ ۔ جندع الانصاری الاوسی(1)\nحماد بن سلمہ، ثابت سے وہ عبد اللہ بن حارث بن نوفل کے بیٹے سے وہ اپنے والد سے وہ جندع انصاری سے روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”جس نے جان بوجھ کر میرے متعلق جھوٹ کہا اس کا ٹھکانا جہنم ہے“۔(2) اسے ابو نعیم نے نقل کیا۔ ابن عبد البر فرماتے ہیں: ان سے حارثہ بن نوفل نے اسی طرح روایت کیا ہے۔ ابن الجوزی نے عجیب کام کیا کہ ان کا عنوان موضوعات میں جندع بن ضمرہ قائم کر کے ان کے حالات لکھ دیے شاید اس بارے انہوں نے ابن مندہ کی پیروی کی ہے جبکہ انہوں نے ان کو پہلی شخصیت سے ملا دیا ہے، جو غلطی ہے، اس واسطے کہ پہلی شخصیت عہد نبوی میں فوت ہوئی جیسا کہ گزر چکا ہے۔ وہ اتنا زندہ نہیں رہے کہ ان سے کوئی روایت لیتا۔ جدجد میں بھی ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۱۲) الاستيعاب (۳۸۶)\n(2) بخاری کتاب العلم باب اثم من کذب علی النبی (۱۰۶) مسلم مقدمہ باب تغلیظ الکذب علی رسول اللہ (۴) ابوداؤد باب فی التشدید فی الکذب علی رسول اللہ (۳۶۵۱) مسند احمد (۱۶۵/۱) جامع المسانید (۱۶۲/۳)"}],[1236,"§۱۲۳۶ ۔ (ز) جندل\nسحر میں ان کی حدیث آئے گی۔"],[1237,"§۱۲۳۷ ۔ (ز) جندل(1)\nجندل بن نصلہ بن عمر بن بہدلہ بھی کہلاتے ہیں۔ اعلام النبوۃ میں ان کی ایک حسن حدیث ہے۔ ایسا ہی ابو عمر نے مختصر کہا ہے۔ ”شرف المصطفٰی“ میں ابو سعد نیشاپوری نے نقل کیا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! میں جنگلی شاعر تھا، ایک جن میرا دوست تھا، ایک دفعہ وہ اچانک آ کر کہنے لگا: ہوشیار ہو جاؤ اس لیے کہ صادق مہذب امین کی وجہ سے دین کا چراغ چمک اٹھا ہے، تو ایسی اونٹنی پر سفر کر جو محفوظ اور ٹھوکر لگنے سے مامون ہو، جو ہموار اور بلند زمین پر چل سکتی ہو۔ میں چونک کر متنبہ ہوا، میں نے کہا: کیا ہو گیا ہے؟ اس نے کہا: ”زمین کو پھیلانے والے اور مقرر کرنے والے کی قسم، زمین کے طول عرض پر محمد مبعوث ہو چکے ہیں۔ وہ حرمت والی بڑی جگہوں میں پہلے بڑھے اور امن والی زمین مدینہ کی طرف ہجرت کر آئے ہیں“۔ فرماتے ہیں: میں چل پڑا، مجھے ایک غیبی آواز والے نے کہا: ”اے سوار جو اپنی سواری کو رسول (صلی اللہ علیہ وسلم) کی طرف لے جانے والا ہے، تجھے ہدایت کی توفیق دی گئی“۔ تو وہ میرا جن دوست ہی تھا۔ پھر وہ قصہ ذکر کیا جس میں کہا: نبی صلی اللہ علیہ وسلم نے میرے سامنے اسلام پیش کیا تو میں مسلمان ہو گیا۔","",{"fn":"(1) اسد الغابۃ (۸۱۴) الاستيعاب (۳۸۲)"}],[1238,"§۱۲۳۸ ۔ جنید بن سبع یا جمعہ\nکنیتوں میں تذکرہ ہوگا، ان کے اور ان کے والد کے نام میں اختلاف ہے۔"],[1239,"§۱۲۳۹ ۔ (ز) جنید بن سمیع المزنی\nعقیلی نے صحابہ میں ان کا تذکرہ کیا ہے۔ ایسا ہی تجرید میں ہے۔(1) مجھے خدشہ ہے کہ یہ پہلے والی شخصیت ہے۔ والد کے نام میں لفظی غلطی ہوئی ہے۔","",{"fn":"(1) التجريد (۲۷/۱)"}],[1240,"§۱۲۴۰ ۔ جنید بن عبد الرحمن(1)\nبن عوف بن خالد بن عفیف بن نجید بن رواس بن کلاب عامری رواسی ہشام بن کلبی نے ذکر کیا کہ وہ، ان کے بھائی عمرو بن مالک اور حمید آئے۔ ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۱۶)"}],[1241,"§۱۲۴۱ ۔ (ز) جنید بن عوف\nبن عبدس بن عمرو بن عابس بن ظرب بن حارث بن فہر قرشی فہری۔ حارث بن عباس بن عبد المطلب کے نانا۔ ان کی والدہ کا نام فاطمہ بنت جنید تھا۔ زبیر نے ان کا ذکر کیا ہے۔ ان کے بیٹے کو بھی شرف صحابیت حاصل ہے لیکن اصحاب سیر نے دونوں کا ذکر نہیں کیا۔"],[1242,"§۱۲۴۲ ۔ جنیدب\nاس نام سے نبی صلی اللہ علیہ وسلم نے ابو ذر غفاری رضی اللہ عنہ کو مخاطب کیا تھا۔ یہ بات سنن ابن ماجہ کی کتاب الادب میں لکھی ہے۔"],[1243,"§۱۲۴۳ ۔ (ز) جنیدب بن الادلع\nجندب بن الادلع میں ذکر ہو چکا ہے۔"],[1244,"§۱۲۴۴ ۔ جہیش\nجیم کے زبر سے ہیش تصغیر کے صیغہ میں ذکر ہوگا۔"],[1245,"§۱۲۴۵ ۔ جہبل بن سیف(1)\nاز بنی جلاج، ابن شاہین نے محمد بن ابراہیم سے بحوالہ محمد بن یزید اپنے رجال سے ان کا ذکر کیا، فرماتے ہیں یہ وہی شخص ہیں جنہوں نے حضرموت نبی صلی اللہ علیہ وسلم کی وفات کی خبر پہنچائی تھی۔ انھی کو امرو القیس بن عابس کہتا ہے۔ اس دن سے موت کی خبریں بلند ہو گئیں جس دن جہبل نے احمد نبی ہدایت والے کی خبر دی۔ جہبل(2) فرماتے ہیں: جہبل اور ان کے گھرانے کا تعلق کلب سے ہے اور یہ لوگ حضرموت میں رہتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۱۷)\n(2) جامع المسانید (۱۶۳/۳)"}],[1246,"§۱۲۴۶ ۔ جہجاہ بن سعید(1)\nبقول بعض ابن قیس اور بقول بعض ابن مسعود غفاری، حدیبیہ میں بیعت رضوان میں شریک تھے۔ شیخین نے حدیث جابر سے روایت کیا ہے کہ ہم غزوہ بنی مصطلق میں تھے ایک مہاجر شخص نے ایک انصاری کو لات مار دی، حدیث جو اللہ تعالیٰ کے اس ارشاد ”ایسا ضرور ہو کر رہے گا کہ مدینہ کے عزت مند وہاں کے ذلیل لوگوں کو نکال باہر کریں گے“،(2)(3) کے متعلق ہے، ابن عبد البر فرماتے ہیں: مہاجری جہجاہ اور انصاری سنان تھے۔ واقدی کا بیان ہے کہ وہ غزوہ مریسیع میں شریک تھے، جہاں ان میں اور سنان بن وبرہ میں جھگڑا ہو گیا، یہاں تک کہ دونوں نے اپنے اپنے قبیلوں کو بلا لیا۔ جہجاہ سیدنا عمر بن خطاب رضی اللہ عنہ کے مزدور تھے۔ پھر وہ قصہ ذکر کیا۔ جعال کے سوانح میں ان کا تذکرہ ہو چکا ہے۔ ابن ابی شیبہ، عبید الاغر کے طریق سے بحوالہ عطاء بن یسار، جہجاہ غفاری سے نقل کرتے ہیں کہ وہ اپنی قوم کے کچھ لوگوں کے ساتھ اسلام لانے کے ارادے سے آئے۔ اس وقت آپ صلی اللہ علیہ وسلم مغرب کی نماز پڑھا رہے تھے۔ جب آپ صلی اللہ علیہ وسلم نے سلام پھیرا تو فرمایا: تم میں سے ہر شخص اپنے ساتھ بیٹھے آدمی کا ہاتھ پکڑ لے۔ پھر ان کے اسلام لانے سے پہلے سات بکریوں کا دودھ پینے کی حدیث ذکر کی۔ اور جب مسلمان ہو گئے تو ایک بکری کا دودھ بھی مکمل نہیں پی سکے۔(4) حدیث انوکھی ہے جس میں موسیٰ بن عبیدہ، عبید سے روایت کرنے میں متفرد ہے۔ سوانح میں ترمذی نے اس کی طرف اشارہ کر دیا ہے۔ جہجاہ خلافت عثمانی تک زندہ رہے۔ باوردی ولید بن مسلم کے طریق سے بحوالہ امام مالک رحمہ اللہ وغیرہ نافع سے وہ ابن عمر رضی اللہ عنہما سے روایت کرتے ہیں، فرمایا: جہجاہ غفاری سیدنا عثمان رضی اللہ عنہ کے پاس آئے۔ آپ منبر پر تشریف فرما تھے۔ انہوں نے لاٹھی لے کر توڑ ڈالی۔ ابھی جہجاہ کو سال بھی نہیں ہوا تھا کہ اللہ تعالیٰ نے ان کے ہاتھ میں خارش لگا دی جس سے وہ فوت ہو گئے۔ ابن السکن سلیمان بن بلال اور عبد اللہ بن ادریس کے طریق سے بحوالہ عبد اللہ بن عمر، نافع سے وہ ابن عمر رضی اللہ عنہما سے یہی روایت نقل کرتے ہیں۔ اور اسے سلیمان بن سلیمان کے طریق سے بحوالہ اپنی پھوپھی، اپنے والد اور ان کے چچا سے روایت کرتے ہیں کہ وہ دونوں سیدنا عثمان رضی اللہ عنہ کے پاس تھے۔ فرماتے ہیں: جہجاہ بن سعید غفاری ان کی طرف بڑھے اور ان کے ہاتھ سے لاٹھی لے کر اپنے گھٹنے پر توڑ دی، لوگوں نے انہیں پکڑا (ارے یہ کیا!) سیدنا عثمان رضی اللہ عنہ منبر سے اتر کر گھر تشریف لے گئے۔ اللہ تعالیٰ نے غفاری کے گھٹنے میں بیماری پیدا فرما دی۔ ابھی سال بھی نہ گزرا تھا کہ فوت ہو گئے۔(5) اسی روایت کو ہم نے محاملیات میں حماد بن زید کے طریق سے بحوالہ یزید بن حازم، سلیمان بن یسار سے نقل کیا ہے کہ جہجاہ غفاری۔۔۔۔ پہلے واقعہ کی طرح۔ ابن السکن فرماتے ہیں: سیدنا عثمان رضی اللہ عنہ کے بعد سال سے کم عرصہ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابۃ (۸۱۸) الاستيعاب (۳۶۰)\n(2) سورۃ المنافقون (۸)\n(3) البخاری (حدیث: ۴۹۰۵) مسلم (حدیث: ۶۵۲۶ و ۶۵۲۷) مصنفہ (الحدیث: ۱۸۰۴۱) دلائل النبوۃ (۵۴/۴) الدر المنثور (۲۲۵/۶)\n(4) المعجم الکبیر (۲۷۴/۲) مسند ابی یعلی (۵۸/۲) فتح الباری (۵۳۸/۹) کنز العمال (۳۶۲۸۳)\n(5) جامع المسانید والسنن (۱۶۵/۳)"}],[1247,"§۱۲۴۷ ۔ جہر ابو عبد اللہ(1)\nطبرانی(2) اور ابن قانع ایک ہی شیخ سے عثمان بن عبد الرحمن وقاص کے طریق سے بحوالہ زہری، عبد اللہ بن جہر سے وہ اپنے والد جہر سے روایت کرتے ہیں، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی تو آپ نے فرمایا: ”جہر! مجھے نہیں اپنے رب کو سناؤ“۔ طبرانی نے اسے حرف جیم میں نقل کیا تو عبد اللہ بن جہر سے مروی ہے کہا، اور ابن قانع نے حرف حاء میں نقل کیا تو عبد اللہ بن جحر کہا اور ابو احمد عسکری نے ایک طریق سے بحوالہ وقاص نقل کیا، فرماتے ہیں: عبد اللہ بن جابر سے مروی ہے۔ یہ تین اقوال ہیں، ان میں پہلا قول راجح ہے۔ میں نے ابن السکن کی کتاب میں ابن عبد البر کے قلم سے لکھا حاشیہ پڑھا ہے جن کا ابن السکن نے ذکر نہیں کیا۔ ان میں سے ایک جہر ہیں ستم سے بیان کیا، پھر اپنی سند سے دوسری طرح عثمان بن عبد الرحمن محزومی تک سلسلہ کو پہنچایا۔ جو وقاص ہیں، جن کا ابھی ذکر ہوا، اور یہی روایت ذکر کی۔ فرماتے ہیں: جہر نے اس کے علاوہ کوئی حدیث روایت نہیں کی۔ میں کہتا ہوں: وقاص ضعیف راوی ہے۔ چنانچہ نعمان بن راشد نے ان کے مخالف روایت کی۔ وہ زہری سے بحوالہ ابو سلمہ، ابو ہریرہ روایت کرتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے دیکھا کہ عبد اللہ بن حذافہ دن میں نماز پڑھتے ہوئے جہر (اونچی آواز سے) قراءت کر رہے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”عبد اللہ! اللہ کو سناؤ ہمیں نہ سناؤ“۔ اسے امام احمد، ابن ابی خیثمہ اور حاکم ابو احمد نے کنیٰ میں نقل کیا ہے۔ ہم نے چوتھے درجہ میں عالی سند سے یہ حدیث، حدیث ابی جعفر بن بختری سے اسی سند سے سنی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۲۰)\n(2) المعجم الکبیر (۲۸۸/۲)"}],[1248,"§۱۲۴۸ ۔ جہم بن قثم العبدی(1)\nحدیث زارع کی روایت سے مطر بن ہلال عنزی کے سوانح میں ان کا ذکر آتا ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، ان کے ساتھ جہم بن قثم بھی تھے۔ ابو عمر کندی نے ذکر کیا کہ نبی صلی اللہ علیہ وسلم نے ماریہ کی بہن جہم عبدی کو بخش دی تھی جن سے زکریا بن جہم پیدا ہوئے۔ ابن زولاق فرماتے ہیں: مشہور یہ ہے کہ آپ نے وہ حسان کو عطا کی تھی۔ میں کہتا ہوں: ابو عمر کندی نے اپنی ذکر کردہ بات ابن اسحاق کی مغازی سے لی ہے۔ اس واسطے کہ وہ ان دونوں کے متعلق کہتے ہیں: مجھے زہری نے بحوالہ عبد الرحمن بن عبد القاری بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے حاطب بن ابی بلتعہ کو مقوقس کی طرف بھیجا، پھر وہ قصہ ذکر کیا، اس میں ہے اس نے آپ کو دو باندیاں ہبہ کیں ان میں سے ایک کا نام ام ابراہیم اور دوسری آپ نے جہم بن قثم العبدی کو عطا کر دی۔ جو ام زکریا بن جہم ہے۔ یہ وہی ہیں جو عمرو بن العاص کے خلیفہ تھے۔(2) بیہقی نے دلائل میں ابو بشر دولابی کے طریق سے پھر عبد الرحمن بن زید بن اسلم کی روایت سے وہ اپنے والد سے وہ یحییٰ بن عبد الرحمن بن حاطب سے وہ اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں، فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے مقوقس کی طرف بھیجا، پھر وہ قصہ ذکر کیا اس میں ہے اس نے آپ کی خدمت میں تین باندیاں ہبہ کیں بھیجیں، لیکن حدیث میں کہا: ان میں کی ایک کی آپ نے جہم بن حذیفہ کو بخش دی۔","",{"fn":"(1) اسد الغابۃ (۸۲۳)\n(2) اسد الغابۃ (۴۲۲/۱)"}],[1249,"§۱۲۴۹ ۔ جہم بن قیس(1)\nبن عبد شرحبیل بن ہاشم بن عبد مناف بن عبد الدار بن قصی العبدری، ابو خزیمہ انہیں جہیم (تصغیر) بھی کہا جاتا ہے۔ جہیم بن الصلت کے ماں شریک بھائی۔ ابن اسحاق نے حبشہ ہجرت کرنے والوں میں ان کا ذکر کیا ہے۔ ابن مندہ نے ابو ہند داری تک ضعیف سند سے روایت کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ان کے لیے ایک تحریر لکھوائی، جس میں تھا، عباس بن عبد المطلب، جہم بن قیس اور شرحبیل بن حسنہ موجود تھے۔ اگر یہ حدیث اس سلسلہ میں ثابت ہو جائے تو احتمال ہے یہ شاہد صاحب عنوان کے علاوہ کے لیے ہو۔","",{"fn":"(1) اسد الغابۃ (۸۲۴) الاستيعاب (۳۴۸)"}],[1250,"§۱۲۵۰ ۔ (ز) جہم الاصم العامری\nبشر بن معاویہ بکائی کے حالات میں ان کا تذکرہ گزر چکا ہے۔"],[1251,"§۱۲۵۱ ۔ جہم البلوی(1)\nبغوی نے عبد العزیز بن عمران کے طریق سے بحوالہ جہم بن مطیع، علی بن جہم بلوی سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: ہمارا رسول اللہ صلی اللہ علیہ وسلم سے سامنا ہوا، آپ نے فرمایا: ”تم کون لوگ ہو؟“ ہم نے عرض کیا: ہم بنی عبد مناف ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم اللہ کے بندے کی اولاد ہو!“۔(2) اس کی سند ضعیف ہے۔ ابو حاتم(3) فرماتے ہیں: عبد العزیز بن عمران ضعیف راوی ہے، اس کی روایت پر اعتماد نہیں۔ ابن مندہ فرماتے ہیں: میں نے زبرقان نامی لوگوں میں ان کا ذکر کیا ہے۔ انہیں فضیلت حاصل ہے۔ انہوں نے ایسا کہا: لیکن مجھے ان کی کتاب میں زبرقان نامی لوگوں میں ان کا تذکرہ نہیں ملا۔","",{"fn":"(1) اسد الغابۃ (۸۲۲) الاستيعاب (۲۴۹)\n(2) المعجم الکبیر (۲۱۵۵/۲) کنز العمال (۱۴۱۲۷) جامع المسانید (۱۶۸/۳)\n(3) الجرح والتعدیل (۵۲۱/۲)"}],[1252,"§۱۲۵۲ ۔ جہم (بے نسبت)(1)\nابن ابی غرزہ نے اپنی مسند میں لیث کے طریق سے بحوالہ مجاہد، ابو وائل سے روایت کیا کہ ذو الکلاع کا گمان ہے کہ اس نے جہم کو فرماتے سنا، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”حسن اور حسین جنتی نوجوانوں کے سردار ہیں“۔(2) اس کی سند ضعیف ہے۔ ابن مندہ نے یہ روایت اسی سند سے نقل کی ہے۔ ابو نعیم نے یہ امکان ظاہر کیا ہے کہ ہو سکتا ہے کہ یہ بلوی ہوں۔ جبکہ ابن قانع نے دونوں میں فرق کیا ہے اور اسے لیث کے طریق سے نقل تو کیا لیکن انہوں نے ابو وائل سے بحوالہ زبرقان بن حکیم روایت کیا کہ ذو الکلاع نے ان سے بیان کیا، پھر اسی حدیث کا ذکر کیا۔ مجاہد کا تو ذکر نہیں کیا البتہ حکیم کا اضافہ کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۵۲۱/۲)\n(2) کنز العمال (۳۷۶۹۳) البدایہ والنہایہ (۱۷۹/۸) جامع المسانید (۱۶۹/۳) ترمذی کتاب المناقب باب مناقب الحسن والحسین (۳۷۶۸) مسند احمد (۶۲/۳، ۶۴، ۸۲)"}],[1253,"§۱۲۵۳ ۔ جہم الاسلمی\nجہیم میں ذکر ہوگا۔"],[1254,"§۱۲۵۴ ۔ جہم بن سعد\nقضاعی نے کتاب النبی صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے کہ وہ اور زبیر دونوں زکوٰۃ کی مالیت لکھتے تھے۔ ایسا ہی مفتقر قرطبی نے ان کا ذکر اپنی کتاب المولد النبوی میں کیا ہے۔"],[1255,"§۱۲۵۵ ۔ جہیش(1)\nآخر میں شین تصغیر ہے، بقولی بعض شروع میں زبر ھا کے نیچے زبر اور یا ساکن ہے۔ اور بعض نے شروع کا زبر ھا ساکن اور اس کے بعد یا لکھی ہے۔ اسی پر ابن الامین بن اویس نخعی نے اعتماد کیا ہے۔ ابن مندہ نے عمار بن عبد الجبار کے طریق سے بحوالہ ابن المبارک اور زائی وہ یحییٰ بن ابی سلمہ سے وہ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں، فرمایا: جہیش بن اویس نخعی رسول اللہ صلی اللہ علیہ وسلم کے پاس مذحج قبیلے سے اپنے ساتھیوں کی جماعت میں آئے یہ لوگ کہنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! ہم مذحج قبیلے کے لوگ ہیں، پھر لمبی حدیث ذکر کی جس میں شعر ہیں جن میں سے چند ایک یہ ہیں: ”یا رسول اللہ صلی اللہ علیہ وسلم! آپ تصدیق یافتہ ہیں، ہدایت پانے اور ہدایت کرنے میں بابرکت ہیں۔ آپ صلی اللہ علیہ وسلم نے ہمارے لیے دین حنیف مقرر کیا جب کہ ہم لوگ گدھوں کی طرح بتوں کی پوجا کرتے تھے“۔ خطابی نے غریب الحدیث میں ان کا طویل ذکر کیا اور ان کی تشریح کی۔ ابن سعد نے طبقات میں وفد کے ذیل میں فرمایا: ہشام بن محمد بن سائب کلبی نے ہمیں اپنے والد کے حوالہ سے وہ نخع کے بوڑھوں سے روایت کرتے ہیں، انہوں نے کہا کہ قبیلہ نخع نے اپنے دو آدمی نبی صلی اللہ علیہ وسلم کے پاس اپنے اسلام کی خبر دینے کے لیے بھیجے۔ ان میں سے ایک ارطاۃ بن شراحیل بن کعب، دوسرے جہیش جن کا نام ارقم تھا۔ ان کا تعلق بنی بکر بن عمرو بن عوف بن نخع سے تھا۔ وہ دونوں وہاں سے نکلے یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ آپ نے ان کے سامنے اسلام پیش کیا تو دونوں نے قبول کر کے اپنی قوم کی طرف سے آپ صلی اللہ علیہ وسلم سے بیعت کر لی۔ رسول اللہ صلی اللہ علیہ وسلم کو ان دونوں کی حالت اور شائستگی پسند آئی۔ فرمایا: کیا تم لوگ اپنے پیچھے اپنی قوم میں سے اپنے جیسے آدمی چھوڑ آئے ہو؟ انہوں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم اپنے پیچھے اپنی قوم کے ستر آدمی چھوڑ آئے ہیں جو ہم سے بھی افضل ہیں۔ وہ دونوں قطعی فیصلہ کرتے اور کئی امور نافذ کرتے۔ جب کوئی کام درپیش ہوتا وہ ہمارے ساتھ شریک نہ ہوتے۔ آپ نے ان دونوں اور ان کی قوم کے لیے دعا فرمائی۔ فرمایا: ”اللہ! نخع کو برکت دے“۔(2) پھر ارطاۃ کے لیے جھنڈا بنایا اور ان کا قصہ ذکر کیا۔ ”تجرید“ میں ذہبی(3) لکھتے ہیں: انہیں خزاعی کہا جاتا ہے، پھر ایک حدیث ذکر کی گویا وہ موضوع ہے۔","",{"fn":"(1) اسد الغابۃ (۸۲۷)\n(2) الطبقات الکبریٰ (۷۷/۲)\n(3) التجريد (۲۷/۱)"}],[1256,"§۱۲۵۶ ۔ (ز) جہیش بن زید\nبن مالک بن عبد اللہ بن حارث بن بشر بن یاسر نخعی۔ ہشام بن کلبی فرماتے ہیں: نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، ان میں اور سابقہ شخصیت میں فرق کیا ہے۔"],[1257,"§۱۲۵۷ ۔ جہیم بن الصلت(1)\nبن مخرمہ بن المطلب بن عبد مناف مطلبی۔ ابن سعد لکھتے ہیں: فتح مکہ کے بعد مسلمان ہوئے، مجھے ان کی روایت کا علم نہیں۔ ایسا ہی بلاذری نے کہا، اور یہ اضافہ کیا کہ جاہلیت میں انہوں نے لکھنا پڑھنا سیکھ لیا، اسلام آیا تو وہ لکھتے تھے انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت لکھائی کا کام بھی کیا۔ ابو عمر فرماتے ہیں: خیبر کے سال اسلام لائے۔ آپ نے انہیں خیبر کی کھجوروں میں سے تین وسق کھانے کے لیے دیے۔ مغازی میں ابن اسحاق(2) نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب تبوک پہنچے آپ کے پاس سحنہ بن روکبہ آیا اور آپ سے صلح کی۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے ایک تحریر لکھوائی، اس کے آخر میں ہے وہ تحریر جہیم بن صلت نے لکھی۔ یہ وہی ہیں جنہوں نے بدر کے دنوں میں ایک گھڑسوار دیکھا جو کہہ رہا تھا: عقبہ اور شیبہ ربیعہ کے بیٹے قتل ہو گئے۔ پھر وہ قصہ ذکر کیا جس کے آخر میں ہے: ابو جہل نے کہا: یہ بنی عبد المطلب کا سند یا (پیام) دینے والا۔ تاریخ والے حمادی لکھتے ہیں: زبیر اور جہیم بن صلت زکوٰۃ کی مالیت لکھتے تھے۔","",{"fn":"(1) اسد الغابۃ (ت ۸۲۸) الاستيعاب (ت ۳۵۰)\n(2) السیرة النبویة (۱۹۶/۲)"}],[1258,"§۱۲۵۸ ۔ (ز) جہیم بن قیس\nوہی جہم ہیں۔"],[1259,"§۱۲۵۹ ۔ جہیم بن ابی جہیمہ الاسلمی\nجیسا کہ آ رہا ہے۔ وہ حنین کی غنیمتیں لانے پر مقرر تھے۔ ان کا ذکر عثمان بن ابی جہیمہ کے حالات میں ہے۔"],[1260,"§۱۲۶۰ ۔ (ز) جودان العبدی (بے نسبت)(1)\nابن شاہین نے شعیب بن صفوان کے طریق سے بحوالہ عطاء بن سائب، اشعث بن عمیر، وہ جودان سے روایت کرتے ہیں، فرمایا: وفد عبد القیس رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے مشروبات کے متعلق پوچھا۔ (حدیث) ابن مندہ فرماتے ہیں: اسے عطاء بن سائب نے بحوالہ اپنے والد جودان روایت کیا ہے۔ ابن حبان نے روضۃ العقلاء میں وکیع کے طریق سے بحوالہ سفیان وہ ابن جریج وہ عباس بن عبد الرحمن بن مینا وہ جودان سے وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں، آپ نے فرمایا: ”جس نے اپنے بھائی سے معذرت کی اور اس نے اس کا عذر قبول نہیں کیا تو اس پر ٹیکس لینے والے جیسا گناہ ہے“۔(2) ابن حبان(3) فرماتے ہیں: اگر ابن جریج نے ان سے سنا ہے تو یہ روایت حسن غریب ہے۔ اسے ابن ماجہ اور طبرانی نے اسی سند سے روایت کیا ہے اور ابو داؤد نے مراسیل میں سہل بن صالح سے بحوالہ وکیع، ابن جودان سے وہ اپنے والد سے۔ ابن ابی حاتم(4) نے فرمایا: میں نے اپنے والد سے ان کے متعلق پوچھا، فرمایا: جودان نامعلوم شخص ہیں جو صحابی نہیں۔ شاید جودان عبدی اس راوی کے علاوہ کوئی شخص ہوں جن کی حدیث پر ابو داؤد اور ابو حاتم کا اتفاق ہے کہ وہ مرسل ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۸۳۰) الاستيعاب (۳۷۶)\n(2) ابن ماجہ باب المعاذیر (۳۷۱۸) المعجم الکبیر (۲۷۵/۲)\n(3) الثقات (۶۵/۳)\n(4) الجرح والتعدیل (۵۴۲/۲)"}],[1261,"§۱۲۶۱ ۔ (ز) الجون بن قتادہ\nبن الاعور بن ساعدہ بن عوف بن کعب التمیمی۔ ان کے صحابی ہونے میں اختلاف ہے۔ ان شاء اللہ تعالیٰ قسم رابع میں ہم ان کا تذکرہ کریں گے۔"],[1262,"§۱۲۶۲ ۔ (ز) الجون بن مجاسر\nبن الضبین بن مالک بن مرہ بن عامر بن حارث بن انمار عبدی ابن اشج العصری کے ماموں زاد، آمدی فرماتے ہیں: نبی صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے اپنی قوم کے کام کے متعلق پوچھا جو ان کے لیے عیب بتاتے تھے۔ آپ نے انہیں ایسا جواب دیا جس میں توریہ تھا (دونوں پہلو تھے)۔ آپ نے فرمایا: ”اگر تم میں سخاوت نہ ہوتی تو اس کی وجہ سے اللہ تعالیٰ تمہیں سزا دیتا اور میں تمہیں ملک بدر کر دیتا تم پر تف ہے کہ اپنی قوم کے قاصد بن کر آئے ہو“۔(1) رشاطی نے ان کا ذکر کیا ہے۔","",{"fn":"(1) مجمع الزوائد (۴۷۱۲)"}],[1263,"§۱۲۶۳ ۔ جویرہ العصری(1)\nمحمد بن محمد بن مزدوق نے فرمایا: ہمیں سہلہ بنت سہیل نے بتایا کہ میں نے اپنی دادی حمادہ بنت عبد اللہ سے بحوالہ جویریہ العصری سے سنا، فرمایا: میں وفد عبد القیس میں نبی صلی اللہ علیہ وسلم کے پاس آیا، ہمارے ساتھ منذر بھی تھے آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: ”تمہاری دو خصلتیں بردباری اور حزم اور وقار اللہ تعالیٰ کو پسند ہے“۔(2) اسے ابن مندہ نے تعلیقاً اور ابو نعیم نے موصولاً ذکر کیا ہے، روایت کی سند میں جن دو عورتوں کا ذکر ہے وہ غیر معروف ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۳۲) الاستيعاب (۳۸۴)\n(2) کنز العمال (۵۸۳۸) (۳۷۵۱۸) الطبقات الکبریٰ (۵۴/۲/۱) جامع الحدیث (۶۶۸/۴) جامع المسانید (۱۷۱/۳)"}],[1264,"§۱۲۶۵ ۔ جبیر بن حویرث(1)\nبن نقید بن عبد الدار بن قصی بن کلاب۔ انہیں دیدار اور سیدنا ابو بکر الصدیق رضی اللہ عنہ سے روایت کرنے کا شرف حاصل ہے۔ ان سے عبد الرحمن بن سعید بن یربوع روایت لیتے ہیں۔ ابن شاہین نے صحابہ میں ان کا تذکرہ کیا ہے۔ ابو عمر فرماتے ہیں: ”انہوں نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا آپ کا دیدار کیا (لیکن) آپ سے کچھ روایت نہیں کیا۔ ان کے والد فتح مکہ کے موقع پر کافر مارے گئے جنہیں علی بن ابی طالب(2) نے قتل کیا“۔ ابو عمر فرماتے ہیں: ان کے صحابی ہونے میں تامل ہے۔ میں کہتا ہوں: کسی نے یہ حدیث روایت کی تو ان کا نام جبلہ بتایا، جو تبدیلی ہے درست جبیر ہے۔","",{"fn":"(1) اسد الغابۃ (۶۹۵) الاستيعاب (۳۱۹)\n(2) اسد الغابۃ (۳۰۹/۱) الاستيعاب (۳۰۶/۱)"}],[1265,"§۱۲۶۶ ۔ جعدہ بن ابی ہبیرہ(1)\nبن ابی وہب بن عمرو بن عائذ بن عمران بن مخزوم قرشی مخزومی، ان کی والدہ ام ہانی بنت ابی طالب ہیں۔ نبی صلی اللہ علیہ وسلم کے عہد میں پیدا ہوئے اور آپ سے مرسل روایت کرتے ہیں۔ اور سیدنا علی رضی اللہ عنہ کی جانب سے خراسان کے گورنر بنے۔ ابن مندہ فرماتے ان کے صحابی ہونے میں اختلاف ہے۔ امام بخاری(2) فرماتے ہیں: صحابی ہیں۔ ازدی وغیرہ نے انہیں ان لوگوں میں شمار کیا ہے جن سے صحابی کے علاوہ کسی نے روایت نہیں کیا۔ حاکم اپنی تاریخ میں لکھتے ہیں: ان کے متعلق کہا جاتا ہے: انہیں دیدار کی دولت نصیب ہے۔ ابن حبان(3) فرماتے ہیں: مجھے ان کے صحابی ہونے کے متعلق کوئی معتمد روایت نہیں ملی۔ بغوی فرماتے ہیں: عہد نبوی میں پیدا ہوئے لیکن صحابی نہیں۔ ابن السکن نے اسی جیسا قول اختیار کیا ہے۔ اجری فرماتے ہیں: میں نے ابو داؤد سے پوچھا: کیا جعدہ بن ہبیرہ صحابی ہیں؟ فرمایا: انہوں نے نبی صلی اللہ علیہ وسلم سے کچھ نہیں سنا۔ میں کہتا ہوں: ان کی رویت تو برحق ہے اس واسطے کہ وہ عہد نبوی میں پیدا ہوئے۔ وہ آپ کی چچا زاد بہن کے بیٹے ہیں۔ اور ام ہانی کی خصوصیت نبی صلی اللہ علیہ وسلم سے مشہور ہے۔ طبرانی نے ابن جریج کے طریق سے ابو زبیر سے وہ مجاہد سے وہ جعدہ بن ہبیرہ سے روایت کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی پہننے سے منع فرمایا ہے۔ (حدیث) حافظ ضیاء نے مختارہ میں طبرانی کے طریق سے نقل کیا ہے کیونکہ باوردی نے اسے طبرانی کے شیخ سے اپنی سند کے ذریعے بحوالہ جعدہ سے روایت کیا ہے، فرمایا: مجھے میرے ماموں علی نے منع فرمایا، پھر وہ روایت ذکر کی حدیث صحیح میں سیدنا علی رضی اللہ عنہ کی روایت سے بذریعہ دوسری سند مشہور ہے۔ طبرانی نے جعدق بن ہبیرہ بے نسبت کے سوانح میں ایک دوسری حدیث نقل کی ہیں جس میں فرماتے ہیں بنی عبد المطلب کے ایک غلام کا نبی صلی اللہ علیہ وسلم کے سامنے ذکر ہوا کہ وہ نماز پڑھتا رہتا ہے سوتا نہیں۔ (حدیث) یہ روایت مرسل ہے۔ امام بخاری(4) وغیرہ نے فرمایا جعدہ امیر معاویہ کی خلافت میں فوت ہوئے۔ میں کہتا ہوں: ام ہانی کے حالات میں آئے گا کہ انہوں نے زمانہ نبوی پایا ہے۔ اگر یہ ثابت ہو جائے تو ان کے صحابی ہونے کے منکر لوگوں کی بات غلط ہو جائے گی۔ جس کی طرف میں نے قسم اول میں اشارہ کر دیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۵۳) الاستيعاب (۳۲۸)\n(2) التاریخ الکبیر (۲۳۹/۲)\n(3) الثقات (۱۱۵/۴)\n(4) التاریخ الکبیر (۲۳۹/۲)"}],[1266,"§۱۲۶۷ ۔ (ز) جنیدب (تصغیر ہے)\nابن جندب بن عمرو بن حممہ دوسی قسم اول میں قریبی ہی ان کے والد کا ذکر گزر چکا ہے۔ یہ جنیدب سیدنا معاویہ رضی اللہ عنہ کے ساتھ جنگ صفین میں شہید ہوئے۔ ابن کلبی نے ان کا ذکر کیا ہے ان کی سے کم عمر ایک بہن تھی جس کے متعلق انہیں والد نے وصیت کر رکھی تھی۔ جن کی شادی سیدنا عمر نے سیدنا عثمان رضی اللہ عنہ سے کر دی تھی اس کا تقاضا یہی ہے کہ انہیں اسی قسم کے لوگوں میں شمار کیا جائے گا۔"],[1267,"§۱۲۶۸ ۔ (ز) جابر بن عمر مزنی\nابن فتحون نے اپنے استدراک میں ان کا ذکر کرتے لکھا ہے: سیدنا عمر رضی اللہ عنہ نے انہیں دجلہ اور فرات سے سیراب زمین پر مقرر کیا لیکن انہوں نے استعفیٰ دے دیا۔ یہ طبری کا قول ہے۔"],[1268,"§۱۲۶۹ ۔ جابر بن کعب\nبن کرمان بن طرفہ، ابن وہب بن مازن بن تیم بن اسد بن حارث بن العتیک الازدی۔ ثابت بن قطبہ بن کعب بن جابر مشہور شاعر کے دادا۔ انہوں نے زمانہ نبوی پایا ہے۔ ابن کلبی نے ان کا ذکر کیا ہے۔ عبد الاعز شاعر ان کے بیٹے ہیں۔ بنی امیہ کی حکومت میں ان کا ذکر آتا ہے۔"],[1269,"§۱۲۷۰ ۔ (ز) جابر بن یاسر(1)\nبن عویلص (سین کے زبر سے) آخر میں رہے ابن فدک رعیثی قتبانی۔ زمانہ نبی صلی اللہ علیہ وسلم حاصل ہے۔ ابن یونس فرماتے ہیں فتح مصر میں شریک تھے۔ اور یہی عباس کے بیٹوں عیاش اور جابر کے دادا ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۵۵)"}],[1270,"§۱۲۷۱ ۔ جابر یا جویر العبدی\nسیدنا عمر رضی اللہ عنہ کے زمانہ میں جوان آدمی تھے، اس لحاظ سے انہوں نے دور نبوی پایا ہے۔ امام بخاری نے ”الادب المفرد“ میں ابو نضرہ کے طریق سے روایت کیا، فرماتے ہیں: ہمارے ایک جابر یا جویر نامی شخص فرماتے ہیں: سیدنا عمر رضی اللہ عنہ کی خلافت میں مجھے ایک ضرورت پیش آئی۔ رات کے وقت میں مدینہ پہنچا، آپ کے پاس گیا، ذہانت و زبان تو مجھے (قدرت سے) ملی تھی۔ آپ رضی اللہ عنہ کے سامنے دنیا کی حقارت بیان کرنے لگا، پھر وہ قصہ ذکر کیا۔"],[1271,"§۱۲۷۲ ۔ (ز) جابر الرعینی\nسعید بن جابر کے والد۔ ابن عساکر نے اپنی تاریخ میں ان کا ذکر کیا کہ انہوں نے دور نبوی پایا اور فتح دمشق میں شریک تھے۔ میں کہتا ہوں: شاید یہ پہلے والے ہوں۔"],[1272,"§۱۲۷۳ ۔ (ز) الجبان (بے نسبت)\nمجھے ان کا نام معلوم نہ ہو سکا۔ ان کا یہ لقب ان کی بہادری کی وجہ سے پڑا۔ ابو موسیٰ اشعری رضی اللہ عنہ کے ساتھ فتح تستر میں شرکت کی۔ زمانہ نبوی پایا ہے۔ ابو بکر بن ابی شیبہ فرماتے ہیں: ہم سے فزاد ابو نوح نے بحوالہ عثمان بن معاویہ قرشی وہ اپنے والد سے وہ عبد الرحمن بن ابی بکرہ سے روایت کر کے بتایا: جب ابو موسیٰ لوگوں کو لے کر ہرمزان کے مقابلہ میں تستر میں فروکش ہوئے۔ پھر ایک قصہ ذکر کیا جس میں ہے: مجراۃ بن ثور ایک سرنگ سے تین سو آدمیوں سمیت شہر میں داخل ہوئے۔ اس تعداد میں سے چھیاسی(۸۶) آدمی مخصوص کر لیے ان سے کہا: جب تک ہمارے باقی ماندہ ساتھی اندر نہیں پہنچا دیتا میں نہیں لوٹوں گا۔ تو ان سے ایک کوفی، جس کی بہادری کی وجہ سے جبان (بزدل) کہا جاتا تھا، کہنے لگا: مجراۃ آپ اپنی فکر کریں، آپ کے علاوہ بھی کوئی یہ کام کر سکتا ہے۔ آپ کو جس کا حکم ہے وہ کریں۔ انہوں نے جواب میں فرمایا: تم نے صحیح کہا۔ پھر وہ انہیں دروازے تک لے گئے اور اس شخص کو ان پر نگران بنا کر ایک جتھہ لے کر دیوار کی طرف چل پڑے۔ ایک کافر سردار ان کی طرف اتر پڑا اور انہیں نیزہ مارا جو نشانے پر لگا۔ مجراۃ نے ان سے کہا: اپنے امیر کی طرف چلو، غفلت میں نہ پڑنا۔ انہوں نے پہچان کے لیے ان پر ٹاٹ ڈال دیا اور چل پڑے۔ دیوار پر مسلمانوں کی تعداد بڑھ گئی اور انہوں نے دروازہ کھول لیا۔ ابو موسیٰ نے بھی اودھر کا رخ کیا، پھر باقی ماندہ حدیث سنائی۔"],[1273,"§۱۲۷۴ ۔ جبیر بن قشعم\nبن یزید بن ارقم بن نعمان بن عمرو بن وہب بن ربیعہ بن معاویہ اکرمین کندی، زمانہ نبوی پایا ہے اور عراق کی فتوحات میں شریک رہے بلکہ خلافت فاروقی میں قادسیہ کے قاضی بھی رہے۔ ابن کلبی نے ان کا ذکر کیا کہ ان کے نسب میں بنی ارقم بن نعمان کی جس جماعت کا ذکر ہے وہ سیدنا علی رضی اللہ عنہ کے زمانہ میں کوفہ میں تھی۔ کچھ کوئی لوگ سیدنا عثمان کے خلاف کچھ کہنے لگے، تو بنی ارقم نے کہا: ہم اس شہر میں نہیں رہتے جہاں عثمان کو برا بھلا کہا جائے۔ چنانچہ یہ لوگ امیر معاویہ کے ہاں منتقل ہو گئے۔ آپ نے انہیں جزیرہ کی زمین رہا پر ٹھہرایا۔"],[1274,"§۱۲۷۵ ۔ جبیر بن نفیر(1)\n(نون، فا سے تصغیر ہے)۔ ابن مالک بن عامر حضرمی ابو عبد الرحمن، اکابر تابعین میں سے مشہور شخص، ان کے والد صحابی ہیں۔ ابن حبان(2) ثقات میں لکھتے ہیں: انہوں نے دور جاہلیت پایا ہے۔ باوردی اور ابن السکن نے عبد الرحمن بن جبیر بن نفیر کے طریق سے بحوالہ اپنے والد روایت کرتے ہیں، فرمایا: میں نے جاہلیت کا دور دیکھا ہے، ہمارے پاس یمن میں رسول اللہ صلی اللہ علیہ وسلم کا قاصد آیا تو ہم لوگ اسلام لے آئے۔ ابن شاہین نے یہ روایت طویل ذکر کی ہے۔ ابو احمد عسکری کا گمان ہے کہ جبیر بن نفیر دو ہیں۔ ایک کندی جو آئے، دوسرے حضرمی ہیں جو صحابی نہیں اور وفد میں آئے۔ میں کہتا ہوں: انہیں اس میں غلطی لگی ہے، جس کا سبب یہ ہے ان کے پاس حدیث اس طرح لکھی ہے جبیر بن نفیر کی روایت ہے کہ ”وہ نبی صلی اللہ علیہ وسلم کے پاس آئے“۔ جبکہ درست یہ ہے جبیر بن نفیر سے بحوالہ ان کے والد جیسا کہ آ رہا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۰) الاستيعاب (۳۱۸)\n(2) الثقات (۱۱۱/۴)"}],[1275,"§۱۲۷۶ ۔ (ز) جد جمیرہ (دونوں جیموں سے)\nانہیں خرہ خسرہ (دونوں نقطوں والی خاؤں اور سین سے) فارسی بھی کہا جاتا ہے۔ کسریٰ کا حکم نبی صلی اللہ علیہ وسلم تک پہنچانے کے لیے باذان کے قاصد، بعد میں اسلام لے آئے۔ ابو سعید نیشاپوری نے ”شرف المصطفیٰ“ میں ابن اسحاق کے طریق سے بحوالہ زہری، ابو سلمہ بن عبد الرحمن روایت کرتے ہیں، فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم کا خط کسریٰ کے پاس پہنچا تو اس نے پڑھ کر چاک کر دیا اور یمن میں اپنے گورنر باذان کو لکھا: کہ حجاز والے اس شخص کی طرف اپنے پاس سے دو مضبوط آدمی بھیجو۔ جو اسے میرے پاس لے آئیں۔ باذان نے ذمہ دار ابنوہ کو بھیجا، وہ فارسی زبان لکھنے اور حساب کتاب کرنے والا تھا۔ اور اس کے ساتھ ایک فارسی شخص روانہ کیا جس کا نام ”جد جمیرہ“ تھا۔ انہیں ایک خط دے کر نبی صلی اللہ علیہ وسلم کی طرف روانہ کیا جس میں آپ کو ان دونوں کے ساتھ کسریٰ کی طرف متوجہ ہونے کا کہا، ذمہ دار سے کہا: اس شخص کی طرف سے پوری چھان بین کرنا اور اس سے گفتگو کر کے مجھے اس کی اطلاع دینا۔ یہ دونوں وہاں سے نکل کر طائف پہنچے۔ جہاں انہیں قریش کے چند تاجر ملے ان سے آپ علیہ السلام کے متعلق پوچھا، ان لوگوں نے بتایا وہ یثرب میں ہیں وہ خوش ہوئے کہنے لگے کسریٰ نے اس کی سزا مقرر کر رکھی ہے۔ وہ شخص تمہیں کافی ہے۔ وہاں سے چلے مدینہ آ گئے۔ ابنوہ نے آپ سے بات کی کہ کسریٰ نے باذان کو حکم دیا ہے کہ وہ آپ کے پاس ایسے شخص بھیجے جو آپ کو لے جائیں۔ اس نے مجھے بھیجا ہے تاکہ آپ میرے ساتھ چلیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اب (سرائے میں) لوٹ جاؤ، کل میرے پاس آنا“۔ دوسرے دن جب وہ آپ صلی اللہ علیہ وسلم کے پاس آئے تو آپ علیہ السلام نے ان سے فرمایا: اللہ تعالیٰ نے کسریٰ کو قتل کرا دیا ہے۔ اور اس کے بیٹے شیرویہ کو فلاں رات فلاں مہینے اس پر مسلط کر دیا ہے۔ انہوں نے کہا: آپ جانتے ہیں جو کچھ آپ کہہ رہے ہیں (اس کا کیا نتیجہ ہوگا)؟ یہ بات ہم باذان کو لکھ بھیجیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں! اس سے کہنا: اگر تم مسلمان ہو گئے تو میں تمہیں تمہارے عہدے پر برقرار رکھوں گا۔ پھر آپ نے جد جمیرہ کو ایک ازار بند عطا کیا جو آپ کو ہدیہ میں ملا تھا۔ اس میں سونا چاندی لگی تھی۔ پھر وہ دونوں باذان کے پاس آئے، اسے حالات سے آگاہ کیا۔ اس نے کہا: اللہ کی قسم! یہ تو بادشاہ کا کلام نہیں، ہم ان کی بات کا ضرور انتظار کریں گے۔ ابھی تھوڑی دیر ہی گزری تھی کہ اس کے پاس شیرویہ کا خط آ پہنچا: صورت حال یہ ہے کہ میں نے فارس کے لیے عہد میں کسریٰ کو قتل کر دیا ہے، کیونکہ اس نے فارس کے بڑے بڑے لوگ قتل کرنا حلال سمجھ لیا تھا۔ اپنی جانب کے لوگوں سے میری فرمانبرداری کا پروانہ لے لو اور اس شخص کی ذرا بھی گستاخی نہ کرنا جس کے لیے کسریٰ نے تمہیں لکھا تھا۔ جب اس نے خط پڑھا، کہنے لگا: بے شک یہ شخص فرستادہ نبی ہے اور وہ اسلام لے آئے جس کی وجہ سے وہاں کے وہ سب فارسی(1) نوجوان بھی مسلمان ہو گئے جو یمن میں رہتے تھے۔ ابو نعیم اصبہانی نے ”دلائل النبوۃ“ میں ایسا ہی لکھا ہے جو ابن اسحاق نے بلا سند مروی ہے لیکن انہوں نے ان کا نام خرخسرہ لیا ہے۔ البتہ ان کے رفیق ”ابانوہ“ کے نام پر اتفاق کیا ہے۔","",{"fn":"(1) دلائل النبوۃ لابی نعیم اصبہانی (۱۲۳)"}],[1276,"§۱۲۷۷ ۔ (ز) جراد بن طہیمہ\nبن ربیعہ بن وحید بن کعب بن عامر بن کلاب کلابی وحیدی، مخضری، زمانہ جاہلیت و اسلام پایا ہے۔ ان کے بیٹے شبیب سیدنا حسین رضی اللہ عنہ کے ساتھ تھے جب وہ شہید ہوئے، مرزبان نے ان کا ذکر کیا ہے۔"],[1277,"§۱۲۷۸ ۔ (ز) جراد بن مالک\nبن نویرہ تمیمی سیف نے فتوح میں ذکر کیا ہے کہ وہ اپنے والد کے ساتھ شہید ہوئے۔ ان کے چچا متمم نے ان کا مرثیہ کہا ہے۔ حرف میم میں ان شاء اللہ تعالیٰ مالک کے قتل ہونے کی روایت آئے گی۔"],[1278,"§۱۲۷۹ ۔ (ز) جراد البجلی\nجاہلیت کا دور پایا اور جریر کے ساتھ فتح قادسیہ میں شریک ہوئے۔ خلال کہتے ہیں: ہمیں جعفر بن احمد بن بسر نے بحوالہ ابو بسر بن مجالد بن جراد بتایا، اور جراد ان لوگوں میں سے ہیں جو جریر کے ساتھ فتح قادسیہ میں شریک تھے۔ پھر ان کا قصہ ذکر کیا ہے۔"],[1279,"§۱۲۸۰ ۔ (ز) جرجہ / جرجیر رومی\nابو یونس ازدی نے فتوح الشام میں ان کا ذکر کیا ہے اور دلائل میں ابو نعیم کے طریق سے مروی ہے، کہا: ”جرجیر“ فتوح میں سیف بن عمر نے جرجہ لکھا ہے۔ اور اس کا ذکر کیا ہے کہ وہ سیدنا خالد بن ولید رضی اللہ عنہ کے ہاتھ پر مشرف با سلام ہوئے۔ یرموک میں شہید ہوئے۔ ابو حذیفہ اسحاق بن بشر نے فتوح میں ان کا ذکر تو کیا ہے لیکن ان کا نام نہیں لیا۔"],[1280,"§۱۲۸۱ ۔ (ز) جرول بن اوس\nحامہ سبطی میں ان کا ذکر ہوگا۔ حطیہ عیسی شاعر ہیں۔"],[1281,"§۱۲۸۲ ۔ (ز) جرول العبسی (دوسرے ہیں)\nنبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے اور عہد فاروقی میں شریک جنگ رہے۔ یعقوب بن شیبہ نے اپنی مسند میں سرج بن نعمان سے بحوالہ ہشام بن عمران بن عبد اللہ، فرماتے ہیں: میرے دادا عبد اللہ نے بحوالہ اپنے والد ابو عبد اللہ جرول بتایا، فرمایا: میں عقبہ بن غزوان کے ساتھ فتح اصطخر میں شریک تھا۔ انہوں نے سیدنا عمر رضی اللہ عنہ کو لکھا، آپ نے شام کے گورنر کو لکھا کہ ابو عبد اللہ کے حساب میں ستر دینار کا اور ان کے اہل و عیال کے وظیفے میں دس دس دینار کا اضافہ کر دو۔"],[1282,"§۱۲۸۳ ۔ (ز) جروہ بن یزید الطائی\nابو حاتم بستائی(1) نے معمرین میں ان کا ذکر کیا کہ وہ سو سال کے قریب زندہ رہے۔ پھر اسلام کا زمانہ پایا۔ سیدنا عثمان رضی اللہ عنہ کی خلافت میں ترکوں سے جنگ میں احنف بن قیس کے ساتھ شریک تھے جس میں ان کا ہاتھ شل ہو گیا تو احنف نے انہیں اس کی دیت عطا کی۔ بعد میں بلخ فروکش ہوئے وہ اکثر ترکوں سے شریک جنگ رہے۔ اس وقت وہ بے حد بوڑھے تھے بالآخر سعید بن انجر کے ساتھ شہید ہوئے اس کے متعلق ان کے بہت سے اشعار بھی ہیں۔","",{"fn":"(1) المعمرین (۶۷/۱)"}],[1283,"§۱۲۸۴ ۔ (ز) جریبہ (جیم اور باء سے تصغیر ہے)\nابن الاشیم بن عمرو بن وہب بن دثار بن فقعس اسدی ثم فقعسی، آمدی فرماتے ہیں: بنی اسد کے شاعروں اور جاہلیت میں ان کے شاعروں میں سے ایک ہیں۔ پھر اسلام لے آئے۔ چنانچہ وہ کہتے ہیں: ”جو مذہب پرانا ہو گیا وہ میرے لیے ایک نئے دین سے تبدیل ہو گیا۔ گناہ کی ایسی کثرت تھی گویا میں اندھیروں میں تھا۔ اے دین کے مالک! ہمیں قائم رکھ تاکہ ہم سیدھے رہیں۔ میں اگر گناہ کا ارادہ بھی کروں گنہگار نہ ہوں“۔ مرزبان لکھتے ہیں: جاہلی شاعر ہیں۔ فرماتے ہیں: ”نشان زدہ گھر سواروں پر فدا، غبار کے تلے میرا ماموں اور چچا تھا۔ ہم نے دشمنوں سے کہا اترو! تو وہ نہیں اترے۔ اترو! اترو! کی ان پر کثرت ہو گئی“۔ ابن کلبی نے ان کا ذکر کیا اور صرف ان کا شاعرانہ وصف بیان کیا۔ عنقریب فقعس تک ان کا نسب آئے گا جیسا کہ یہاں ہے۔"],[1284,"§۱۲۸۵ ۔ جزو بن حارث بن جذیمہ العبسی\nابن کلبی نے ان کا ذکر کیا ہے، ان کے والد دور جاہلیت میں فوت ہوئے۔ اور ان کے چچا قیس بن زہیر اپنے دور میں بنی عبس کے رئیس تھے، وہ بھی دور جاہلیت میں فوت ہوئے۔ رہے یہ جزو تو مجھے کوئی ایسا نظر نہیں آیا جس نے انہیں صحابہ میں ذکر کیا ہو۔ انہوں نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے ان کا بیٹا عباس جو امام الولید بن عبد الملک کے والد ہیں تابعین سے ہیں۔ بنی امیہ کے ساتھ ان کے کئی واقعات ہیں۔"],[1285,"§۱۲۸۶ ۔ (ز) جزو بن ضرار الغطفانی\nمرزبان نے اپنی مجم میں ان کا ذکر کیا ہے کہ وہ مخضرمی شاعر ہیں جو سیدنا عمر بن خطاب رضی اللہ عنہ کا مرثیہ بیان کرتے ہوئے کہتے ہیں: ”اللہ تعالیٰ امیر المومنین کو بہترین بدلہ دے اور اس پچھے ہوئے چہرے میں اللہ تعالیٰ کے ہاتھ میں برکت ہو“۔ (اشعار)"],[1286,"§۱۲۸۷ ۔ (ز) جزو بن مالک اسدی\nحضری بن عامر میں تذکرہ ہوگا۔"],[1287,"§۱۲۸۸ ۔ جشیش الدیلمی(1)\n(جیم کے بعد دو شین سے تصغیر ہے)۔ یہ نام دار قطنی نے لکھا ہے۔ یہ ان لوگوں میں سے تھے جنہوں نے اسود کذاب کے قتل میں امداد بہم پہنچائی تھی۔ طبری نے ان کا ذکر کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ سیف نے کتاب الردہ میں لکھا ہے کہ نبی صلی اللہ علیہ وسلم نے جشیش، دادویہ اور فیروز کی طرف پیغام بھیجا کہ اسود العنسی سے جنگ کرو۔ اسے دوستوں کے لیے ذریعہ بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے۔ فرمایا: اس پیغام کا قاصد وبرہ بن یحنس تھا۔ ایسا ہی واقدی نے درہ میں ہمام بن منبہ کی روایت سے ذکر کیا ہے۔ ایسے ہی سیف نے فرمایا: ہمیں مستنیر بن یزید نے بحوالہ عروہ بن عزید یشنی ضحاک بن فیروز وہ جشیش دیلمی سے روایت کر کے بتاتے ہیں، فرمایا: ہمارے پاس وبرہ بن یحنس نبی صلی اللہ علیہ وسلم کا خط لے کر آئے جس میں آپ صلی اللہ علیہ وسلم ہمیں اپنے دین پر قائم رہنے، جنگ میں ثابت قدم رہنے اور اسود کذاب کے خلاف متحرک رہنے کا حکم دے رہے تھے۔ پھر ان کا وہ لمبا قصہ ذکر کیا جس میں انہوں نے اسود کو قتل کیا۔ اس کے آخر میں ہے پھر میں نے اذان دی اور ان کے سامنے اس کا (کٹا ہوا) سر ڈال دیا۔ وبرہ نے نماز قائم کی پھر ہم نے ان پر پہلہ بول دیا اور نبی علیہ السلام کو حالات کی خبر دی۔ آپ صلی اللہ علیہ وسلم اس وقت با حیات تھے۔ اسی رات آپ صلی اللہ علیہ وسلم کے پاس وحی آ چکی تھی۔ آپ صلی اللہ علیہ وسلم نے صحابہ کو اس کی اطلاع دی آپ کے بعد ہمارے قاصد صدیق اکبر کے پاس آئے اور انہوں نے ہی ہمارے خطوط کا جواب دیا۔ دادو کے حالات میں آئے گا کہ یہ ان لوگوں میں سے ایک تھے جنہوں نے اسود کے قتل میں اعانت کی تھی۔","",{"fn":"(1) اسد الغابۃ (۷۴۶)"}],[1288,"§۱۲۸۹ ۔ جرجست فارسی\nاگر اس میں لفظی غلطی نہیں تو یہ دوسرے شخص ہیں۔ اس میں بھی کوئی مشکل نہیں کہ وہ متعدد ہوں۔"],[1289,"§۱۲۹۰ ۔ (ز) جعدہ سلمی\nجہالت کا زمانہ پایا ہے۔ سیدنا عمر رضی اللہ عنہ کے زمانے میں مدینے میں ان کا ایک قصہ ہے۔ آمدی(1) نے ان کا ذکر کیا کہ وہ غزل گو عورتوں والے شاعر تھے۔ عورتوں سے باتیں کرتے، انہیں ہنساتے اور ان سے مذاق کرتے وہ بھی ان کے پاس جمع ہو جاتیں۔ انہوں نے ایک عورت کو پکڑا اسے باندھا اور کہا کہ اب چلو وہ لڑکھڑا کر گری جس سے اس کے کپڑے کھل گئے اور سب عورتیں ہنسنے لگیں۔ یہ بات بقیلہ اشجعی کو پتہ چلی، وہ سیدنا عمر رضی اللہ عنہ کے زمانے میں شریک جہاد تھے انہوں نے آپ کی طرف خط لکھا۔ کوئی قاصد ابو حفص کو یہ پیغام پہنچا دے میرا بھائی آپ پر قربان ہو اللہ آپ کی رہنمائی کریں ہماری اونٹنیوں کا خیال کرو، ہم محاصرہ کے زمانے میں آپ لوگوں سے غافل رہے۔ ان اونٹنیوں کا کون مہبان ہوگا جو بیریاں ڈال کے چھوڑ دی گئیں۔ مختلف جھگڑوں کو لے کر صلح پہاڑ چل پڑا کچھ اونٹنیاں بنی کعب ابن عمرو کی کچھ قبیلہ اسلم، جہینہ اور غفار کی ہیں۔ جنہیں سفید شرارتی باندھتا ہے اور وہ شخص کیا ہی برا جو اچھے اونٹوں کو باندھتا ہے۔ فرماتے ہیں سیدنا عمر رضی اللہ عنہ نے جعدہ کی طرف پیغام بھیجا اور انہیں جلا وطن کر دیا۔ قصہ مشہور ہے جو ان کے علاوہ کسی اور کی طرف سے تھی نقل کیا جاتا ہے۔ میں نے تاریخ ابن عساکر میں جعفر بن خزابہ کے طریق سے اصمعی تک ان کی سند سے مروی پڑھا ہے۔ فرمایا: ہمیں ابو عمرو بن العلاء نے بتایا، فرمایا کہ مدینہ میں بنی سلیم کا جعدہ نامی ایک شخص تھا جس کے پاس مدینہ کے درمیان میں عورتیں آ کر باتیں کرتیں۔ وہ ایک عورت کو رسی سے باندھتا پھر کہتا: رسی سے بندھا گھوڑا اچھلا نگ لگائے گا۔ جب وہ عورت کودتی تو گر جاتی جس سے اس کی شرمگاہ کھل جاتی، جہاد میں شریک کچھ لوگوں کو اس کی اطلاع ملی جن میں سے ایک شخص نے سیدنا عمر رضی اللہ عنہ کو خط لکھا پھر وہ اشعار ذکر کیے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: میرے پاس جعدہ بن سلیم لایا جائے۔ چنانچہ وہ لایا گیا۔ سعید بن المسیب فرمایا کرتے تھے: میں ان جوانوں میں شامل تھا جو جعدہ کو پکڑ کر سیدنا عمر رضی اللہ عنہ کے پاس لائے۔ آپ نے جب اسے دیکھا تو فرمایا: جیسا تمہارے متعلق کہا گیا کہ وہ سفید رنگ شرارتی ہے، تو ایسا ہی ہے، پھر اسے کوڑے مارے اور عمان کی طرف جلا وطن کر دیا۔","",{"fn":"(1) الامدی (۸۲/۱)"}],[1290,"§۱۲۹۱ ۔ جعفر بن علس\nبن ربیعہ بن حارث بن عبد یغوث بن حارث بن معاویہ حارثی۔ ابو الفرج اصبہانی فرماتے ہیں: دور جاہلیت پایا پھر اسلام لے آئے۔"],[1291,"§۱۲۹۲ ۔ (ز) جعفر بن قرط العامری\nابو حاتم بستائی(1) نے معمرین میں ان کا ذکر کیا کہ وہ تین سو سال تک زندہ رہے، اسلام کا زمانہ پایا تو مسلمان ہو گئے۔","",{"fn":"(1) المعمرین (۵۴/۱)"}],[1292,"§۱۲۹۳ ۔ (ز) جعونہ بن شعوب اللیثی\nابو کبر بن شداد بن شعوب کے بھائی، زمانہ نبوی پایا ہے۔ فاکہی نے ابو اویس کے طریق سے بحوالہ اپنے والد کے چچا ربیع بن مالک سے وہ اپنے والد سے وہ جعونہ بن شعوب لیثی سے روایت کرتے ہیں، فرمایا: میں سیدنا عمر بن خطاب کے ساتھ باہر نکلا آپ نے میرا ہاتھ پکڑ رکھا تھا یا میرے ساتھ ٹیک لگائی ہوئی تھی۔ آپ کی نظر ایک قافلے پر پڑی جو گھائی سے نکل رہا تھا اور اپنی سواریاں ہنکچ چکا تھا۔ آپ نے فرمایا: اگر قافلے کو اس فضیلت کا علم ہو جائے جو وہ لے کر جا رہے ہیں۔۔۔۔ (حدیث)"],[1293,"§۱۲۹۴ ۔ جعونہ بن مرثد الاسدی\nطغمر بن طلیحہ بن خویلد نے جب نبوت کا دعویٰ کیا اس کے متعلق اشعار ہیں: ”بنی اسد نے جو کچھ کہا مجھے برا لگا، جو قوم اللہ سے جنگ کرنے لگے اس کا کوئی رشتہ دار نہیں ہوتا، میں دین حنیف کا پیروکار ہوں اگر تم بے وقوفی کی وجہ سے دین مستقیم پر قائم رہنے کی بنا پر برا بھلا کہو، پھر بھی میں مسلمان ہوں“۔"],[1294,"§۱۲۹۵ ۔ (ز) الجعید (بے نسبت)\nمیرے خیال میں وہ بنی تغلب کے فرد ہیں۔ مدائنی نے کتاب الکائد میں ان کا ذکر کیا ہے۔ یہ ان عربوں میں سے تھے جو اجنادین کی جنگ کے بعد رومیوں کے ساتھ تھے اور ان کی قید سے چھوٹ گئے۔ سیدنا خالد بن ولید رضی اللہ عنہ کے پاس آئے تو انہیں دشمنوں کے خفیہ ٹھکانوں کی اطلاع دی۔ اور ان کے لیے ایک تدبیر سوچی جس پر عمل کر کے ناقوصہ کے روز انہیں شکست دے دی۔ اور ان کے دس لاکھ سے زائد مار قتل کر دیے۔ اور ذکر کیا کہ یرموک اور ناقوصہ کے درمیان چار فرسخ کا فاصلہ ہے۔"],[1295,"§۱۲۹۶ ۔ (ز) جعیدہ بن عبیدہ کلابی\nارتداد کے خلاف جنگ کے دوران اور فتح شام میں سیدنا خالد بن ولید رضی اللہ عنہ کے ساتھ تھے۔ وہی کہتے ہیں: ”مجنون کی بیٹی کہتی ہے: کیا تو بیٹھا ہوا ہے۔ نہیں اس کے باپ کی قسم کھا کر کہتا ہوں اس کی بات نہیں مانوں گا جس کا خالد کے لشکر میں بکثرت آنا جاتا ہو۔ رومیوں کی طرف سے اس پر آنے والے بہت ہوں گے“۔"],[1296,"§۱۲۹۷ ۔ الجلندی\nشروع کا پیش لام پر زبر نون ساکن اور دال پر زبر، عمان کے بادشاہ۔ وہیمہ نے ردۃ میں ابن اسحاق سے نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم نے عمرو بن العاص کو انہیں اسلام کی دعوت دینے کے لیے بھیجا تو انہوں نے کہا: تم نے مجھے اس نبی امی کے متعلق بتایا کہ وہ جس بھلائی کا حکم دیتا ہے سب سے پہلے خود اس پر عمل کرتا ہے اور جس شر سے منع کرتا ہے سب سے پہلے خود اس سے باز رہتا ہے۔ جب وہ غالب آتا ہے تو نہ ٹھکراتا ہے اور نہ جھڑکتا ہے۔ وہ عہد کی پاسداری اور وعدے کی وفاداری کرتا ہے۔ میں گواہی دیتا ہوں وہ نبی ہے۔ پھر چند اشعار کہے جن میں سے چند ایک یہ ہیں: ”عمرو میرے پاس وہ بات لے کر آیا جس کے بعد نہ کوئی حق ہے اور نہ خیر خواہی۔ میں نے اس سے کہا: جو کچھ تم لے کر آئے اس میں اضافہ نہیں کیا، عمان کا جلندی چیتا ہے۔ اے عمرو! میں کھلے عام اللہ تعالیٰ کے لیے مسلمان ہو چکا ہوں جس کی صدا دونوں وادیوں میں پھیل رہی ہے“۔ عنقریب جیفر بن جلندی کے سوانح میں آئے گا کہ جن کی طرف پیام بھیجا گیا عمرو تھے، اس لیے امکان ہے کہ باپ اور بیٹے دونوں کی طرف آپ نے پیام بھیجا ہو۔ مدائنی نے ذکر کیا کہ کسی عجمی بادشاہ نے جلندی بن عبد العزیز ازدی کو گورنر بنایا، انہیں جاہلیت میں عبد جمل کہا جاتا تھا، پھر قصہ ذکر کیا۔"],[1297,"§۱۲۹۸ ۔ (ز) جماع بن ضرار\nشماخ بن ضرار کے حالات میں تذکرہ ہوگا۔"],[1298,"§۱۲۹۹ ۔ (ز) جمرہ بن شہاب\nمخضرمی ہیں۔ ان کا سیدنا عمر رضی اللہ عنہ کے ساتھ ایک قصہ پیش آیا جسے ہم نے ”فوائد ابی القاسم بن بشران“ میں موسیٰ بن عقبہ کے طریق سے بحوالہ نافع، ابن عمر رضی اللہ عنہما سے روایت کیا ہے، فرمایا: سیدنا عمر بن خطاب رضی اللہ عنہ نے ایک شخص سے پوچھا: تمہارا کیا نام ہے؟ اس نے کہا: جمرہ۔ آپ نے فرمایا: کس کے بیٹے ہو؟ کہا: شہاب کا۔ فرمایا: کن سے ہو؟ کہنے لگا: آگ جلانے والوں میں سے۔ فرمایا: تمہارا گھر کہاں ہے؟ اس نے کہا: حرہ میں۔ فرمایا: کس محلہ میں؟ کہا: ذات لظیٰ (لپٹ والی) میں۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: پہنچو! پہنچو! تمہارے گھر والے تو جل گئے۔ چنانچہ وہ شخص آیا، دیکھا تو واقعی اس کے گھر والے جل چکے تھے۔ عبد الرزاق نے معمر سے بحوالہ زہری ابن المسیب سے روایت کیا، فرمایا کہ سیدنا عمر رضی اللہ عنہ نے فرمایا: پھر اسی سے ملتے جلتے مفہوم کی روایت ذکر کی۔ امام مالک رضی اللہ عنہ نے موطا(1) میں یحییٰ بن سعید سے نقل کیا کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ایک شخص سے پوچھا: تمہارا نام؟ اس نے کہا: جمرہ۔ پھر اسی مفہوم کی روایت ذکر کی۔ اس روایت کا ابو بلال اشعری کی روایت سے ایک اور طریق ہے جو خالد اشعری سے بحوالہ مجالد ایک شیخ سے جس نے دور جاہلیت کا دور دیکھا ہے، کہا: میں سیدنا عمر رضی اللہ عنہ کے پاس بیٹھا تھا کہ ایک شخص آیا پھر اسی مفہوم کا قصہ ذکر کیا۔ اخبار منثورہ میں ابن درید لکھتے ہیں: ہمیں ابو حاتم بستائی نے بحوالہ ابو عبیدہ بن مثنیٰ بتایا کہ شہاب بن جمرہ یعنی سیدنا عمر رضی اللہ عنہ کے پاس آئے۔ انہوں نے ایسا ہی الٹ ذکر کیا ہے جبکہ صحیح نام پہلے والا ہے۔ ابن کلبی نے ”الجامع“ میں ان کا ذکر کیا کہ وہ جمرہ بن شہاب بن ضرام بن مالک اجہنی ہیں اور سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آمدہ ان کا قصہ بھی ذکر کیا ہے۔","",{"fn":"(1) موطا مالک کتاب الاستئذان والتشمیت باب ما یکرہ من الاسماء (۱۸۲۰)"}],[1299,"§۱۳۰۰ ۔ جناب بن مرثد (ابو ہانی الرعینی)\nنبی صلی اللہ علیہ وسلم کے دور میں اسلام لائے اور یمن میں سیدنا معاذ رضی اللہ عنہ کے ہاتھ پر بیعت کی۔ پھر فتح مصر میں شریک ہوئے۔ ابن یونس وغیرہ نے ان کا ذکر کیا ہے۔"],[1300,"§۱۳۰۱ ۔ جنادہ بن ابی امیہ الدوسی\nان کے والد کا نام کبیر (باء سے) ہے۔ عبادہ بن الصامت رضی اللہ عنہ کے ساتھی ہیں۔ میں نے ان کے ہمنام کے سوانح میں فرق پہلے بتا دیا ہے جس سے فائدہ ہوگا۔ یہ کہ انہوں نے دور جاہلیت اور اسلام پایا ہے۔ ۷۴ھ میں ان کا انتقال ہوا۔"],[1301,"§۱۳۰۲ ۔ (ز) جندب بن سلامہ الہذلی\nدور جاہلیت دیکھا ہے، عہد فاروقی میں مدینہ کے تاجر تھے۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں سلمہ بن جندب کے طریق سے بحوالہ جندب بن سلامہ روایت کیا ہے، فرمایا: ہم لوگ اس بازار کے تاجر تھے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: ہم اپنے اور تمہارے درمیان اس چیز کو راستہ نہیں دیں گے جسے تم ذخیرہ کر سکو۔ مسلم بن جندب کہتے ہیں: جندب بن سلامہ کا تعلق میری قوم سے تھا۔"],[1302,"§۱۳۰۳ ۔ (ز) جندب بن سلمی مدلجی\nبنی سوق کے فرد، ان لوگوں میں سے جو صدیق اکبر رضی اللہ عنہ کے دور میں (نعوذ باللہ منہ) مرتد ہو گئے۔ ان کی طرف عتاب بن اسید گورنر مکہ نے اپنا بھائی خالد بن اسید بھیجا جو انہیں ابارق میں جا ملے۔ انہیں شکست دی اور ان کی جمعیت منتشر ہو گئی۔ اس کے بعد انہیں ندامت ہوئی اور دوبارہ مسلمان ہو گئے، چنانچہ وہ کہتے ہیں: مجھے ندامت ہوئی اور میں نے یہ یقین کر لیا کہ میں نے اس کا انکار کر دیا جس کی عار ہمیشہ زمانے کے ساتھ رہے گی۔"],[1303,"§۱۳۰۴ ۔ جندع بن صمیل\nنبی صلی اللہ علیہ وسلم کے عہد میں اسلام لائے آپ کی طرف رخت سفر باندھا لیکن رستے میں فوت ہو گئے۔ رافع بن خداش کے سوانح میں ان کا تذکرہ آئے گا وہ ان کے چچا زاد ہیں۔"],[1304,"§۱۳۰۵ ۔ جندل العجلی\nمخضرمی ہیں۔ اھ کو جابان کے قتل کی خوشخبری سیدنا ابو بکر رضی اللہ عنہ تک پہنچانے کے لیے خالد بن ولید کے قاصد تھے۔ سیف اور طبری نے ان کا تذکرہ کیا ہے کہ جندل فصیح آدمی تھے۔ ابو بکر رضی اللہ عنہ نے انہیں ایک قیدی لڑکی ہبہ کی جس سے ان کی اولاد ہوئی۔ ابن فتحون نے ان کا استدراک کیا ہے۔"],[1305,"§۱۳۰۶ ۔ (ز) جہمہ بن عوف الدوسی\nابو حنیف لوط بن یحییٰ نے معمرین میں ان کا ذکر کیا ہے کہ وہ تین سو ساٹھ(۳۶۰) برس زندہ رہے۔ اسلام کا زمانہ پایا۔ چنانچہ جب وہ کسی کو لا الہ الا اللہ کہتے ہوئے سنتے تو فرماتے، میں نے اپنی جوانی میں لوگوں کو یہ کلمہ پڑھتے سنا ہے وہ ایک وادی سے گزرتے جو ہے اب و گیاہ تھی، فرماتے ہیں: میں اس وادی سے گزرتا جس میں کوئی درخت نہ ہوتا وہ اتنا زندہ رہے کہ ان کی ابروئیں ان کی آنکھوں پر پڑ گئی تھیں۔ مندرجہ ذیل اشعار کے قائل وہی ہیں: ”میں بوڑھا ہو گیا اور عمر لمبی ہو گئی یہاں تک کہ مجھے رات کے اڑدھوں کے ڈسے شخص کا قائم مقام بنا دیا جو ودیعت اور امانت نہیں رکھا گیا۔ نہ تو مجھے بیماری کی مصیبت ہے نہ کوئی اور غم ہے، ہاں موسم گرما اور بہار کے لگا تار سال مجھ پر گزرے جن میں تین سو سال مکمل گزرے۔ دیکھو اب میں چو تھے کی امید پر ہوں۔ میں گزشتہ سالوں کی باتیں بتاتا ہوں۔ ایک ایسا ضروری ہے جس میں پھرنے کے لیے مجھے اڑایا جائے“۔"],[1306,"§۱۳۰۷ ۔ (ز) جہم بن کلدہ الباہلی\nدار قطنی کی ”المختلف و المؤتلف“ میں مظہر بن سعید باہلی کے طریق سے ان کا ذکر آیا ہے۔ فرماتے ہیں: مجھ سے میرے دادا مظہر بن جہم بن کلدہ نے بحوالہ اپنے والد بیان کیا کہ ہم لوگ سوق میں تھے جو رستلا علاقہ ہے۔ جب ہمارے پاس نبی صلی اللہ علیہ وسلم کی وفات کی اطلاع پہنچی تو لوگوں نے اپنے گھر گرانا شروع کر دیے پھر سات دن تک تعمیر نہیں ہوئے۔"],[1307,"§۱۳۰۸ ۔ (ز) جہم الحضرمی\nعامر بن جہدم میں ذکر آئے گا۔"],[1308,"§۱۳۰۹ ۔ (ز) جویریہ بن قدامہ التمیمی\nخود سیدنا عمر رضی اللہ عنہ سے اور ان سے ابو جمرہ (جیم سے) روایت کرتے ہیں بخاری میں ہے بقول بعض نام ان کا جاریہ اور جویریہ لقب ہے۔ اور کسی نے کہا کہ اکابر تابعین میں سے وہ آخری شخص ہیں۔ اور جو روایت ابن عساکر نے سعید بن عمرو واللاموی کے طریق سے زوایت کی ہے اس سے اس کی تائید ہوتی ہے کہ وہ دونوں ایک ہی شخص ہیں۔ سیدنا امیر معاویہ رضی اللہ عنہ نے اپنے دربان سے کہا: جاریہ بن قدامہ کو اندر آنے کی اجازت دو! جب وہ اندر آئے تو آپ نے ان سے فرمایا: جویریہ! پھر قصہ ذکر کیا۔"],[1309,"§۱۳۱۰ ۔ جیفر(1)\nبروزن جعفر لیکن عین کی جگہ یا ہے بن جلندی ازدی شاہ عمان۔ ابو عمر نے مختصر ان کا ذکر کیا ہے۔ عسکری فرماتے ہیں: انہوں نے اور ان کے بھائی نے نبی صلی اللہ علیہ وسلم کا دیدار نہیں کیا۔ ان کے والد کا تذکرہ پہلے ہو چکا ہے۔ ابن سعد نے عمرو بن شعیب کے طریق سے عمرو بن العاص کے مولیٰ سے روایت کی ہے، فرمایا: میں نے عمرو بن العاص کو فرماتے سنا: میں نجاشی کے پاس مسلمان ہوا پھر اپنی ہجرت کا واقعہ ذکر کیا۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مجھے جیفر اور عبید کی طرف بھیجا جو جلندی کے صاحجزادے اور عمان میں رہتے تھے۔ ان میں سے بادشاہ جیفر تھا۔ ان دونوں کا تعلق قبیلہ ازد سے تھا۔ پھر ان کے اسلام لانے کا واقعہ ذکر کیا۔ اور ان دونوں نے انہیں زکوٰۃ کی عام اجازت دی۔ نبی صلی اللہ علیہ وسلم کی وفات تک وہ عمان میں ہی رہے۔ ادھر عبدان نے زہری تک صحیح سند سے بحوالہ عبد الرحمن بن عبد القاری روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن العاص کو جیفر اور عباد کی طرف بھیجا جو جلندی کے بیٹے اور عمان کے گورنر تھے۔ سیدنا عمرو ان کے ہاں گئے تو وہ دونوں اسلام لے آئے۔ ان کے ساتھ بہت سے لوگ بھی اسلام میں داخل ہو گئے۔ آپ نے اسلام نہ لانے والوں پر جزیہ مقرر کیا۔ میں کہتا ہوں: اس میں اور جلندی تک جو مرسل روایت ہے اس میں کوئی منافات نہیں۔ اور یہ مشکل بھی نہیں کہ جلندی خود بوڑھے ہو گئے ہوں اور اختیار مملکت اپنے دونوں بیٹوں کو دے دیا ہو۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۸۳۳) الاستيعاب (۳۷۵)"}],[1310,"§۱۳۱۱ ۔ (ز) جیفر بن جشم ازدی\nوہیمہ نے کتاب الردۃ میں ذکر کیا ہے کہ وہ نبی صلی اللہ علیہ وسلم کی وفات کے بعد سیدنا عمرو بن العاص کے ساتھ صدیق اکبر رضی اللہ عنہ کے پاس آئے۔"],[1311,"§۱۳۱۲ ۔ (ز) جابر بن عبد اللہ الاشہلی\nان کے متعلق ابن مندہ کو وہم ہوا ہے، درست یوں ہے: جابر بن خالد بن مسعود، پہلے بھی تذکرہ ہوا ہے۔ وہم کی وجہ یہ بنی کہ وہ بنی عبد الاشہل سے تعلق رکھتے ہیں۔ انہوں نے ان کے جد اعلیٰ کی طرف نسبت کر دی اور اسے تبدیل کر کے عبد الاشہلی کر دیا۔"],[1312,"§۱۳۱۳ ۔ (ز) جابر بن عیاش(1)\nابو نعیم فرماتے ہیں: ان کی کوئی حدیث مشہور نہیں۔ انہوں نے ان کا اسی طرح مختصر تذکرہ کیا ہے۔ ابن الاثیر فرماتے ہیں، جبکہ انہیں وہم ہوا ہے: ابو نعیم نے تو جابر بن یاسر بن غویلص (جو عیاش کے دادا ہیں) کے سوانح کے دوران کہا، جابر بن عیاش بن جابر۔ نہ ان کا تذکرہ مشہور ہے اور نہ روایت ہے۔ ابن الاثیر یہ سمجھے کہ انہوں نے جابر بن عیاش کو سابقہ ذکر کردہ ناموں پر عطف کیا ہے حالانکہ ایسا نہیں۔ انہوں نے تو ان کے بھائی عیاش پر عطف کیا۔ اور جابر بن عیاش مصریوں میں صغار تابعین کے طبقہ سے مشہور ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۵۲)"}],[1313,"§۱۳۱۴ ۔ جابر بن نعمان(1)\nفرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”مسکین کو دینا (بری موت سے محفوظ رکھتا ہے)“۔(2) میں نے فوائد ابی الحباس احمد بن علی الابار میں ایسا ہی لکھا دیکھا ہے۔ فرمایا: ہم سے علی بن ہاشم نے بحوالہ ابن فدیک، محمد بن عثمان سے وہ اپنے والد سے وہ جابر بن نعمان سے یہ روایت نقل کرتے ہیں۔ میں نے سلفی کے طریق سے ایک صحیح نسخہ میں ایسا ہی پایا ہے۔ مجھے کوئی مؤرخ ایسا نظر نہ آیا جس نے ان کا تذکرہ صحابہ میں کیا ہو، حالانکہ یہ ان کی شرط کے مطابق ہیں پہلے میں یہ بات جائز قرار دیتا تھا کہ وہ جابر بن نعمان بلوی انصار کے حلیف ہوں جن کا ذکر قسم اول میں گزرا ہے۔ بعد میں مجھے حسن بن سفیان، طبرانی اور ابو نعیم کے ہاں حلیہ میں حارثہ بن نعمان انصاری کے سوانح میں یہ حدیث مل گئی۔ قسم اول میں ان کے سوانح میں آئے گی۔","",{"fn":"(1) اسد الغابۃ (۶۵۴)\n(2) المعجم الکبیر (۲۵۸/۳) مجمع الزوائد (۱۱۲/۳) حلیة الاولیاء (۲۵۶/۱)"}],[1314,"§۱۳۱۵ ۔ جاریہ بن عبدا المنذر\nدرست خارجہ حاء نقطہ والی ہے ہے، آ رہا ہے۔"],[1315,"§۱۳۱۶ ۔ (ز) جاریہ بن عمرو\nبن المؤمل ان شاء اللہ تعالیٰ خواتین کے حصہ میں حرف جیم میں ذکر ہوگا۔"],[1316,"§۱۳۱۷ ۔ (ز) جاریہ بن قعیس الطائی\nدرست حارثہ یا بے نقطی سے ہے، ذکر آئے گا۔"],[1317,"§۱۳۱۸ ۔ (ز) جبیر بن اوس از بنی زریق\nبدری صحابی ہیں۔ البتہ ان سے زیادہ احادیث مروی نہیں، ایسا ہی ابن حبان نے ذکر کیا ہے۔ جزء بن انس کا تذکرہ اور اس میں اختلاف پہلے گزر چکا ہے وہی درست ہے۔"],[1318,"§۱۳۱۹ ۔ (ز) جبر (بے نسبت)\nابو احمد عسکری نے صحابہ میں ان کا تذکرہ کیا ہے اور ایک طریق سے بحوالہ عثمان وقاصی زہری سے انہوں نے عبد اللہ بن جبر سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: ”میں نے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے قراءت کی تو (نماز کے بعد) آپ نے فرمایا: جبر اپنے رب کو سناؤ مجھے نہیں“۔(1) سابقہ شخصیت پر اضافہ کرتے ہوئے ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: یہ لفظی غلطی ہے حالانکہ یہ نام جہر (باء کی جگہ ہاء سے) تھا جس طرح کچھ ہی پہلے تذکرہ ہوا ہے۔ ہم نے وہیں اس کے متعلق سب کچھ تحریر کر دیا ہے۔","",{"fn":"(1) مجمع الزوائد (۱۱۰/۲)"}],[1319,"§۱۳۲۰ ۔ (ز) جبر بن زید\nابو عیس کے والد عنقریب علبہ بن زید کے سوانح میں وہ بات آئے گی جس سے وہم ہوتا ہے کہ وہ صحابی ہیں اور ان سے روایت ہے حالانکہ ایسا نہیں۔ صحابی ہونا اور روایت کرنا ان کے بیٹے ابو عیس کو حاصل ہے۔"],[1320,"§۱۳۲۱ ۔ (ز) جبلہ بن ثابت\nزید کے بھائی۔ بعض رواۃ کو ان کے متعلق وہم ہوا ہے اور انہوں نے حدیث ابن اسحاق بحوالہ فرہ بن نوفل، جبلہ برادر زید سے روایت کر دی جبکہ وہ زید بن حارثہ ہیں اور راوی نے انہیں زید بن ثابت سمجھ لیا ان کے بھائی کا بھی یہی نسب بیان کر دیا۔ حدیث جبلہ بن حارثہ سے مشہور ہے جیسا کہ قسم اول میں تذکرہ ہو چکا ہے۔"],[1321,"§۱۳۲۲ ۔ جبلہ بن شراحیل(1)\nحارثہ کے بھائی۔ ابن مندہ نے ان کا علیحدہ عنوان قائم کیا ہے جس کی ابو نعیم نے تردید کی ہے کہ وہ یہی پہلے والے جبلہ بن حارثہ زید کے بھائی ہیں۔ اور حارثہ ان کے بھائی نہیں بلکہ والد ہیں۔ یہی درست ہے۔ میں کہتا ہوں: اس میں وہم کی وجہ وہ روایت ہے جو زید بن حارثہ کے قصہ میں ان کی اولاد کے طریق سے مروی ہے۔ حارثہ نے کہا: اے بیٹے! میں تمہیں اپنی طرف سے تسلی دیتا ہوں کہ میں اس بات کی گواہی دیتا ہوں کہ اللہ کے سوا کوئی عبادت کے لائق نہیں اور محمد صلی اللہ علیہ وسلم اللہ تعالیٰ کے رسول ہیں۔ پس حارثہ بن شراحیل ایمان لے آئے اور باقی لوگوں نے انکار کر دیا اور واپس جنگل میں آ گئے۔ پھر ان کا بھائی جبلہ واپس گیا اور نبی صلی اللہ علیہ وسلم پر ایمان لے آیا۔ تو ابن مندہ نے اخاہ (ان کے بھائی) کی ضمیر حارثہ کی طرف راجع کی اس لیے کہ وہ قریبی لفظ ہے جس کا ذکر ہوا اور ابو نعیم نے زید کی طرف لوٹائی اس لیے کہ انہی کے متعلق گفتگو ہو رہی ہے۔ جبلہ دونوں کا احتمال ہے البتہ ابو نعیم کا قول راجح اور وزنی ہے۔ کیونکہ جبلہ بن حارثہ صحابہ میں اپنی صحابیت اور نام کے حوالہ سے شہرت رکھتے ہیں۔ بخلاف ان کے چچا زید کے، اس واسطے کہ ان کا صرف اسی روایت میں نام لیا گیا ہے جو قابل احتمال ہے۔ فاللہ اعلم پھر ساتھ ساتھ یہ روایت اس مشہور حدیث کے مخالف اور شاذ ہے کہ زید بن حارثہ نے جب رسول اللہ صلی اللہ علیہ وسلم کو پسند کر لیا تو ان کے والد اور چچا کا جی خوش ہو گیا اور وہ انہیں چھوڑ کر واپس چلے گئے۔ ایسا ہی اہل سیرت نے ذکر کیا ہے۔ اسی طرح ابن مردویہ نے اپنی تفسیر میں کلبی کے طریق سے بحوالہ ابو صالح، سیدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۸۵)"}],[1322,"§۱۳۲۳ ۔ جبلہ(1)\n(بے نسبت) ابن شاہین نے ان میں اور جبلہ بن حارثہ میں فرق کیا ہے حالانکہ یہ وہی ہیں۔ اور جو حدیث انہوں نے درج کی وہ بھی انہی کی ہے۔ وہ ابن اسحاق کی حدیث بحوالہ ایک شخص جبلہ سے ((قُلْ يَا أَيُّهَا الْكَافِرُونَ)) (سورۃ الکافرون: ۱) کی سونے(2) کے وقت قراءت کے بارے میں مروی ہے۔ اسے ابن مندہ نے شریک کی روایت سے بحوالہ ابن اسحاق فرہ بن نوفل سے انہوں نے جبلہ بن حارثہ سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۹۰)\n(2) ابوداؤد کتاب الادب باب ما یقول عند النوم (۵۰۵۰) ترمذی فی کتاب الدعوات باب منہ (۳۴۰۳) المستدرک (۵۶۵/۱) المعجم الکبیر (۲۸۷/۲) الصحیح لابن حبان (۲۳۶۳) الدر المنثور (۴۰۶/۶)"}],[1323,"§۱۳۲۴ ۔ جبیر بن حارث\nدرست حیب (باؤں سے ہے) پہلے گزر چکا ہے۔"],[1324,"§۱۳۲۵ ۔ جبیر بن حارث اعرابی\nآثھری نے اپنے سفرنامہ کے فوائد میں امیر ابو البکارم عبد الکریم ابن الامیر نصر دیلمی تک ایک لمبی سند سے ذکر کیا ہے، فرماتے ہیں: میں امام ناصر عباسی کی خدمت میں تھا ایک دفعہ وہ شکار کی غرض سے باہر نکلے۔ شکار کے پیچھے گھوڑے کو ایڑ لگائی، ان کے پیچھے کچھ خواص بھی چل پڑے۔ آخر کار ہم ایک ویران زمین میں جا پہنچے۔ کیا دیکھتے ہیں کہ وہاں کچھ عرب ہیں ان کے بوڑھے آ گئے بڑھے وہ خلیفہ کو پہچان کر زمین بوس ہونے لگے اور جو میسر ہوا وہ کھانا پیش کر کے کہنے لگے: امیر المومنین! ہمارے پاس ایک تحفہ ہے جو ہم آپ کو دینا چاہتے ہیں۔ فرمایا: وہ کیا ہے؟ ہم سب ایک شخص کی اولاد ہیں اور ابھی تک زندہ کھاتے پیتے ہیں۔ انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے اور خندق کی کھودائی میں آپ کے ساتھ حاضر تھے۔ خلیفہ نے کہا ان کا نام؟ وہ بولے جبیر بن حارث۔ خلیفہ نے کہا: مجھے ان کی زیارت کراؤ۔ تو انہوں نے انہیں بچہ کی طرح ایک پنگھوڑے میں ڈالا پھر رتن ہندی جیسا قصہ ذکر کیا۔ فرماتے ہیں: یہ ۷۵۴ھ کی بات ہے۔ لسان المیزان(1) میں، میں نے پورا قصہ ذکر کیا ہے۔","",{"fn":"(1) لسان المیزان (۲۹۷/۲)"}],[1325,"§۱۳۲۶ ۔ جبیر بن نعمان(1)\nبن امیہ انصاری، خوات بن جبیر بن جبیر کے والد۔ سعید بن یعقوب بن السراج نے افراد میں ان کا ذکر کیا ہے اور زید بن اسلم کے طریق سے بحوالہ خوات بن جبیر وہ اپنے والد سے روایت کرتے ہیں، فرمایا: ایک دفعہ میں عورتوں کے پاس بیٹھا تو نبی صلی اللہ علیہ وسلم نے مجھے فرمایا: تمہیں کیا ہوا ہے؟ میں نے عرض کیا: میرا ایک اونٹ بدک گیا ہے۔ (حدیث)۔(2) یہ غلطی ہے جو ایک لفظ رہ جانے سے پیدا ہوئی۔ یوں ہے خوات کے بیٹے سے مروی ہے صحابی خوات ہیں اور مذکورہ قصہ انہی سے مشہور ہے۔","",{"fn":"(1) اسد الغابۃ (۶۹۹)\n(2) اسد الغابۃ (۳۷۰/۱)"}],[1326,"§۱۳۲۷ ۔ الجحاف بن حکیم(1)\nبن عاصم بن سباع بن خزاعی بن محارب بن ہلال بن فالج بن ذکوان بن ثعلبہ بن بہثہ بن سلیم سلمی فارسی، عبد الملک بن مروان کے دور میں مشہور واقعات والے ابن الاثیر نے سابقہ شخصیت پر اپنے استدراک میں ان کا تذکرہ کیا ہے۔ اور ان اشعار سے استدلال کیا ہے جن میں وہ بنی سلیم کے گھوڑوں کی صفات بیان کرتے ہیں۔ یہ ایسے نشان زدہ گھوڑے ہیں جو نبی صلی اللہ علیہ وسلم کے ساتھ حنین میں شریک ہوئے جن کے اطراف خون آلود ہیں۔(2) میں کہتا ہوں: ان اشعار سے ان کے صحابی ہونے کا پتہ تو نہیں چلتا، البتہ انہوں نے اپنی قوم بنی سلیم پر فخر کیا ہے اور غزوہ حنین میں وہ بکثرت تھے۔ اس بارے میں عباس بن مرداس کا قصہ مشہور ہے۔ مجھے ابن الاثیر کے لیے ایک گزشتہ شخصیت مل گئی، لیکن جس نے اس کے رد پر کمر باندھی ہے وہ اس سے زیادہ با علم شخص ہے۔ چنانچہ ابن عساکر، محمد بن سلام تک صحیح سند سے روایت کرتے ہیں کہ ابان اعرج نے مجھے بتایا کہ جحاف نے دور جاہلیت دیکھا ہے میں نے ان سے کہا: آپ ایسا کیوں کہتے ہیں؟ فرمایا: ان کے ان اشعار کی وجہ سے پھر یہ بیت ذکر کی۔ محمد بن سلام فرماتے ہیں: میں نے کہا: انہوں نے تو اپنی قوم بنی سلیم مراد لی ہے۔ فرماتے ہیں: بعد میں میں نے یہ بات عاصم بن سری سے ذکر کی، انہوں نے فرمایا: مجھے قیس بن بیشم نے بتایا کہ انہوں نے حکیم بن امیہ کو ایک لونڈی جس سے جحاف ہمارے گھر کے کمرے میں پیدا ہوئے۔ اس سے معلوم ہوا وہ نبی صلی اللہ علیہ وسلم سے کافی زمانہ بعد پیدا ہوئے۔ ہمارے میں ابو تمام نے یہ گمان ظاہر کیا کہ یہ اشعار کسی اور کے ہیں۔ وہ حریش بن ہلال قریشی ہے۔ فاللہ اعلم ابن سید الناس نے شعراء صحابہ میں ان کا لکھا ہے: ابن الامین نے ابن عبد البر پر اپنے استدراک میں ان کا ذکر کیا ہے۔ میں نے انہی کے قلم سے تحریر کردہ نقل کیا ہے وہ فرماتے ہیں: ہشام نے ان کا تذکرہ کیا ہے، فرمایا: فتح مکہ کے متعلق ان کے اشعار ہیں۔ میں نے جو سیرت بحوالہ ابن اسحاق دیکھا کہ کسی کہنے والے نے کہا جس کا تعلق بنی جذیمہ سے تھا۔ بقول بعض وہ سلمی نامی کوئی خاتون تھیں۔ پھر اشعار کا ذکر کیا جن کا مطلع یہ ہے: ”اگر ایک قوم کی مسلمان قوم سے بات نہ ہوتی تو سلیم اس دن لشکر مارنے والے کے لائق ہوتے“۔ فرماتے ہیں: اسے عباس بن مرداس اور بقول بعض جحاف بن حکیم نے جواب دیا: رہنے دو، گمراہانہ گفتگو بس کرو، ہمیں شب و روز لڑائی کا ذبہ لشکر مارنے کے لیے کافی ہے۔ میں کہتا ہوں: اس میں ان کے صحابی ہونے کی کوئی دلیل نہیں ہے۔ جیسا پہلے گزر چکا انہوں نے اپنی قوم پر فخر کرتے ہوئے یہ سب کچھ کہا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۴)\n(2) اسد الغابۃ (۳۷۲/۱) السیرة النبویة (۵۸، ۵۹/۴)"}],[1327,"§۱۳۲۸ ۔ جحش الجہنی(1)\nطبرانی نے ان کا ذکر کیا ہے جو خطا پر بنی ہے اور وہ لفظی غلطی سے پیدا ہوئی۔ اس واسطے کہ انہوں نے ابن اسحاق کے طریق سے بحوالہ محمد بن ابراہیم تیمی عبد اللہ بن جحش جہنی سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! میرا ایک (جانا پہچانا) جنگل ہے جہاں میں فروش ہو کر اس میں نماز پڑھتا ہوں۔ اب مجھے اجازت دیجیے کہ میں اس مسجد میں ایک رات نماز پڑھ لوں۔ (آپ صلی اللہ علیہ وسلم نے فرمایا تمیو یں رات اترو، چاہے تو نماز پڑھو اور چاہے چھوڑ دو۔ مراد نفل نماز ہے)۔ (الحدیث)۔ انہوں نے ایسا ہی درج کیا ہے، اسے ابو داؤد(2) نے ابن اسحاق کے طریق سے نقل کیا تو انہوں نے کہا: تیمی سے وہ عبد اللہ بن انیس الجہنی سے وہ اپنے والد سے، یوں اسناد سے لفظ ابن رہ گیا اور جحش انیس سے بدل گیا۔ ابن عبد اللہ کا نام ضمرہ ہے جو زہری نے اس حدیث کی روایت کرتے ہوئے بتایا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۷)\n(2) ابوداؤد کتاب الصلاۃ باب فی لیلۃ القدر (۱۳۸۰)"}],[1328,"§۱۳۲۹ ۔ (ز) جدیہ (بے نسبت)\nابن شاہین نے ان کا ذکر کیا ہے جو غلط ہے۔ اور ذیال بن عبید کے طریق سے بحوالہ حنظلہ بن حذیفہ، جدیہ سے نقل کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بلوغت کے بعد یتیمی نہیں رہتی“۔(1) ابو موسیٰ فرماتے ہیں: یہ لفظی غلطی ہے، روایت کی سند تو یوں ہے ان کے دادا سے جن کا نام حنظلہ ہے۔ میں کہتا ہوں: اپنے مقام پر درست آئے گا، میرے خیال میں صحیح حذیم سے مروی ہے جیسا کہ حاء بے نقطی میں آئے گا۔","",{"fn":"(1) ابوداؤد کتاب الوصایا باب ما جاء حتی ینقطع الیتم (۲۸۷۳) السنن الکبریٰ (۵۷/۷) (۳۲۰) المعجم الصغیر (۹۶/۱) الدر المنثور (۲۸۸/۱) کنز العمال (۱۵۰۵۴) (۹۰۴۹۹) نصب الرایہ (۲۱۹/۲)"}],[1329,"§۱۳۳۰ ۔ جردان\nذہبی نے اپنے استدراک میں جرثوم اور جر موز کے درمیان ان کا ذکر کیا ہے جبکہ وہ جودان واؤ سے ہے۔ درست نام گزر چکا ہے۔"],[1330,"§۱۳۳۱ ۔ جرجیس راہب\nباء میں بحیر کے تحت تذکرہ گزرا ہے۔"],[1331,"§۱۳۳۲ ۔ جرفد بن رداح الاسلمی(1)\nکنیت ابو عبد الرحمن، اہل صفہ میں سے تھے۔ ابن ابی حاتم(2) نے بحوالہ اپنے والد ان کا ذکر کیا ہے۔ اور جرہد بن خویلد اور ان میں فرق کیا حالانکہ دونوں ایک ہیں۔ اپنے دادا کی طرف منسوب ہوتے ہیں۔ صحیح رزاح (زاء سے ہے نہ کہ دال سے)۔ ابن سعد(3) اور ابو عبید نے لکھا ہے جرہد بن رزاح اسلمی کی کنیت ابو عبد الرحمن تھی، شریف النسب تھے۔ بغوی بحوالہ زہری لکھتے ہیں: جرہد بن خویلد اسلمی اور ابن قانع تحریر کرتے ہیں: جرہد بن عبد اللہ بن رزاح بن عدی بن سہم۔ یوں ذکر کر کے ان کے آباء کی پوری جماعت ساقط کر دی۔","",{"fn":"(1) اسد الغابۃ (۷۲۵) الاستيعاب (۳۶۲)\n(2) الجرح والتعدیل (۵۳۹/۲)\n(3) الطبقات (۳۳/۴)"}],[1332,"§۱۳۳۳ ۔ (ز) جرو بن جابر\nابو بکر بن عبد الرحمن بن حارث بن ہشام کے شیوخ میں سے ہیں۔ ثقات الثقات میں ابن حبان لکھتے ہیں: مراسیل روایت کرتے تھے۔"],[1333,"§۱۳۳۴ ۔ جویح بن سلامہ ابو شاہ\nابن شاہین نے ان کا ذکر تو کیا لیکن ان کا نام اور کنیت غلط لکھ دی۔ وہ حدیج (حاء بے نقطی اور دال سے ہے) اور ان کی کنیت ابو شاث (شین باء الف اور شاء سے ہے) حاء بے نقطی میں صحیح نام آئے گا۔"],[1334,"§۱۳۳۵ ۔ جریر یا ابو جریر\nدرست حاء بے نقطی سے آخر میں زا ہے۔ بغوی اور ابن مندہ نے جیم میں ان کا تذکرہ کیا ہے، ان کا تذکرہ ثابت نہیں۔"],[1335,"§۱۳۳۶ ۔ جشیش الکندی\nابن شاہین نے ان کا ذکر کیا ہے، درست فا کے اضافہ سے ہے جیسا پہلے ذکر ہوا۔"],[1336,"§۱۳۳۷ ۔ (ز) جفال\nازدی نے انہیں فاء مشدد سے ذکر کیا ہے، درست جعال ہے، جیسا کہ گزر گیا۔"],[1337,"§۱۳۳۸ ۔ جفشیش بن اسود الکندی\nذہبی(1) نے اپنے استدراک میں ان کا تذکرہ کیا ہے۔ ان میں اور جفشیش بن نعمان میں فرق کیا ہے حالانکہ دونوں ایک ہیں۔ یہ جفشیش بن نعمان ہیں۔ بقول بعض ابن اسود بن معدیکرب جیسا پہلے گزر گیا۔","",{"fn":"(1) التجرید (۲۵/۱)"}],[1338,"§۱۳۳۹ ۔ جعفر بن الزبیر(1)\nبن عوام قرشی اسدی، ابن مندہ نے ابراہیم بن العلاء کے طریق سے اور ابو نعیم نے حسن بن عرفہ کے طریق سے وہ دونوں ہشام بن عروہ سے وہ اپنے والد سے روایت کرتے ہیں کہ عبد اللہ بن زبیر اور جعفر بن زبیر نے اس وقت رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی جب یہ دونوں سات سال کے تھے۔(2) ابن مندہ کہتے ہیں: یہ وہم پر مبنی ہے، درست وہ ہے جو نعمان وغیرہ نے نقل کیا کہ اسماعیل سے اسی سند کے ذریعہ مروی ہے کہ عبد اللہ بن زبیر اور عبد اللہ بن جعفر نے بیعت کی۔ میں کہتا ہوں: اس میں غلطی اسماعیل سے واقع ہوئی ہے۔ اس لیے کہ ابراہیم بن العلاء اس میں منفرد ہیں۔ حق بات وہی ہے جو ابن مندہ نے کہی۔ وجہ یہ ہے کہ جعفر بن زبیر تو نبی صلی اللہ علیہ وسلم کی وفات کے کافی عرصہ بعد پیدا ہوئے۔ عمر میں وہ عمرو سے چھوٹے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۵۶)\n(2) اسد الغابۃ (۳۲۷/۱)"}],[1339,"§۱۳۴۰ ۔ (ز) جعفر ابو زمعہ البلوی(1)\nصحابی ہیں، جنہوں نے درخت تلے بیعت کی۔ پھر مصر رہائش اختیار کر لی۔ ان کے نام میں اختلاف ہے، کسی نے جعفر تو کسی نے عبد کہا ہے۔ ابن الاثیر(2) نے اپنے استدراک میں اسی طرح نقل کیا ہے کہ ابو موسیٰ نے عبد نامی لوگوں میں ان کا ذکر کیا لیکن جعفر میں ان کا تذکرہ نہیں کیا۔ میں کہتا ہوں: اس میں ابن الاثیر سے واضح غلطی ہوئی ہے اس لیے کہ ابو موسیٰ نے جو ذکر کیا وہ یہ ہیں: عبد بن زمعہ بلوی سے مروی ہے جو ان لوگوں میں سے تھے جنہوں نے درخت تلے بیعت کی، مصر میں سکونت اختیار کی، ان کے نام میں اختلاف ہے، جعفر نے کہا: بقول بعض عبد ہے۔ لگتا ہے ابن الاثیر والے نسخہ میں قلمی غلطی ہے جو جعفر سے ابو موسیٰ نے نقل کیا وہ مستغفری ہیں اور ابو موسیٰ اپنی کتاب میں ان سے بکثرت نقل کرتے ہیں۔ اسی بنا پر اکثر وہ ان کا نسب بیان نہیں کرتے۔","",{"fn":"(1) اسد الغابۃ (۷۵۷)\n(2) اسد الغابۃ (۳۹۱/۱)"}],[1340,"§۱۳۴۱ ۔ جعفر العبدی(1)\nتابعی ہیں جنہوں نے ایک مرسل حدیث نقل کی ہے جس کی وجہ سے علی بن سعید نے انہیں صحابہ میں ذکر کر دیا ہے۔ وہ حسن بن عرفہ سے بحوالہ معتمر وہ لیث سے وہ زید سے وہ جعفر عبدی سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت میں سے (دوسروں کو جھٹی یا جھنی کہنے کے لیے) تقسیم کھانے والوں کے لیے خرابی ہے“۔(2) ابو موسیٰ کہتے ہیں: اگر یہ جعفر بن زید عبدی ہیں تو وہ مشہور تابعی ہیں۔ ورنہ، میں انہیں نہیں جانتا۔ میں کہتا ہوں: یہ وہی ہیں۔ امام بخاری رحمہ اللہ نے تاریخ میں ان کا ذکر کیا اور معتمر کے طریق سے ان کے سوانح میں یہ حدیث ذکر کر کے فرمایا مرسل ہے۔","",{"fn":"(1) اسد الغابۃ (۷۶۰)\n(2) جامع المسانید (۱۰۱/۳)"}],[1341,"§۱۳۴۲ ۔ جعفر بن نسطور رومی\nان جھوٹوں میں سے ایک جھوٹا جنہوں نے نبی صلی اللہ علیہ وسلم کی وفات کے کئی سال بعد صحابی ہونے کا دعویٰ کیا تھا۔ میں نے ابن الاثیر کی کتاب پر استدراک میں مغلطائی کے قلم سے لکھا ہوا پڑھا ہے، ایسا ہی ابن دباغ نے ابن عبد البر کی کتاب پر اپنے استدراک میں ذکر کیا ہے اور تجرید میں ذہبی(1) نے بھی اپنے استدراک میں نقل کیا ہے۔ البتہ انہوں نے کہا: اس تک اسناد اندھیر ہی اندھیر ہے۔ اور متون باطل ہیں۔ وہ دجال (انتہائی جھوٹا) ہے یا اس کا وجود ہی نہیں۔ اسے ۳۵۰ھ میں ترک کی زمین فاراب میں دیکھا گیا۔ میں کہتا ہوں: قسم اول میں اس کا ذکر کرنے سے میرا دل خوش نہیں ہوا۔ منصور بن حکم زاہد فرغانی کے طریق سے، ان سے مروی ہمیں ایک نسخہ ملا جن میں سے ایک یہ ہے: مجھ سے جعفر بن نسطور رومی نے بیان کیا کہ میں غزوہ تبوک میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا، آپ صلی اللہ علیہ وسلم کے ہاتھ سے کوڑا گر گیا، میں اپنے گھوڑے سے اترا اور کوڑا اٹھا کر آپ صلی اللہ علیہ وسلم کو دے دیا۔ آپ صلی اللہ علیہ وسلم نے (دعا دیتے ہوئے) فرمایا: ”اللہ تمہاری عمر دراز کرے!“ اس کے بعد میں تین سو میں(2) سال زندہ رہا۔ ابو ہریرہ بن ذہبی نے اجازت حدیث میں ہمیں بحوالہ اسحاق بن یحییٰ آمدی، وہ یوسف بن خلیل سے، وہ مسعود جمال سے وہ ابو علی حداد سے وہ احمد بن محمد بن عمرو واعظ قومسی سے املاء (بول کر لکھوانا) نقل کرتے ہیں کہ شجاع بن عمرو بن علی عراقی نے بحوالہ منصور بن حکم ہمیں بتایا۔ ان میں سے ایک یہ ہے جو خیر کی جانب ننگے پاؤں چلا تو گویا وہ جنتی زمین پر چلا۔ (حدیث)۔ نیز میں نے اس کی ایک حدیث سنی ہے، ان کے آخری شیخ شہدہ بنت ابرى ہیں۔ نسطور رومی کے سوانح میں اس کا ذکر ہوگا۔ سلفی کہتے ہیں: عبد اللہ بن عمر بن خلف فروی نے ہمیں مہ ۹ھ میں بتایا کہ ہمیں علی بن حسین بن اسماعیل کاشغری نے بحوالہ ابو داؤد سلیمان بن نوح بن محمد مرغینانی، انہوں نے منصور بن حکم فقیہ سے نقل کیا پھر اس نسخہ کا ذکر کیا جو گیارہ احادیث پر مشتمل تھا، ان میں سے دو یہی مذکورہ حدیثیں تھیں۔ ان میں سے ایک یہ ہے کہ ایک دفعہ ہم لوگ نبی صلی اللہ علیہ وسلم کے سامنے بیٹھے تھے۔ آپ صلی اللہ علیہ وسلم نے مسواک کرتے وقت اپنے دائیں ہاتھ سے پھر بائیں ہاتھ سے اشارہ فرمایا۔ ہم نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہمیں تو کوئی نظر نہیں آ رہا۔ آپ کے اشارہ کر رہے ہیں؟ فرمایا: جبرائیل اور میکائیل میرے سامنے تھے۔ میں نے جبرائیل کی طرف اشارہ کیا تو انہوں نے کہا: ”میکائیل کو دیں وہ مجھ سے بڑے ہیں“۔(3) ایک اور نسخہ سے بھی انہوں نے روایت کی، اور ابو المظفر میمون بن محمود کے طریق سے بحوالہ شریف عبد الجلیل عمر بن حسین کاشغری وہ ابن نسطور وہ اپنے والد سے روایت کرتے ہیں۔ عنقریب نون میں ذکر ہوگا۔","",{"fn":"(1) التجرید (۲۵/۱)\n(2) اللآلی المصنوعة (۱۰۱/۱) تذکرة الموضوعات (۱۰۸)\n(3) اللآلی المصنوعة (۱۰۲/۱)"}],[1342,"§۱۳۴۳ ۔ (ز) جعفی بن سعد العشیرہ(1)\nاز قبیلہ مذحج۔ جن ایام میں نبی صلی اللہ علیہ وسلم کا(2) وصال ہوا انہی ایام میں جعفی کے وفد میں نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابن ابی حاتم نے اپنی کتاب میں ایسا ہی نقل کیا ہے۔ ابو عمر نے ان کی پیروی کرتے ہوئے ان سے نقل کیا اور ان کا تعاقب نہیں کیا۔ ابن الاثیر لکھتے ہیں: یہ صاحب علم کی عجیب بات ہے۔ اس لیے کہ جعفی بن سعد العشیرہ نبی صلی اللہ علیہ وسلم سے پہلے عرصہ ہوا فوت ہو گئے تھے اور جن لوگوں نے ان سے نشت و برخاست رکھی ان میں اور جعفی میں دس سے زیادہ پشتوں کا فاصلہ ہے۔ میں کہتا ہوں: میرے خیال میں انہوں نے مغازی میں وفد جعفی بن سعد العشیرہ از قبیلہ مذحج دیکھا جیسی ان مؤرخین کی عادت ہے کہ وہ شخصیات کے سوانح قبیلوں کے نام سے بیان کرتے ہیں۔ پھر ان لوگوں کے نام ذکر کرتے ہیں جو وفد میں ہوتے ہیں۔ انہیں گمان ہوا کہ وہ وفد میں آئے (جوفا کا زبر سمجھ لیا) جس سے یہ نتیجہ نکلا کہ جعفی بن سعد العشیرہ وہ وفد (یعنی آنے والے) تھے۔ حالانکہ ایسا ہے نہیں، اس لیے کہ انہوں نے اسم کو فعل اور قبیلے کے نام کو آنے والے کا نام بنا دیا۔ اس سلسلہ میں ابن ابی حاتم سے بڑھ کر ابو عمر زیادہ قابل ملامت ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۶۱) الاستيعاب (۳۸۵)\n(2) اسد الغابۃ (۳۳۰/۱) الاستيعاب (۳۴۲/۱)"}],[1343,"§۱۳۴۴ ۔ (ز) الجلاح ابو خالد\nذہبی نے سابقہ شخصیت پر زائد اپنے استدراک میں ان کا ذکر کیا ہے۔ اور اسے طبقات ابن سعد کی جانب منسوب کیا ہے حالانکہ لفظی غلطی کی۔ ان کا نام الجاج (دو جیموں سے ابتداء میں لام سے) ہے جیسا کہ حرف لام میں آئے گا۔"],[1344,"§۱۳۴۵ ۔ جمد الکندی(1)\nابن مندہ حماد کے طریق سے بحوالہ عاصم روایت کرتے ہیں کہ جمد الکندی نے کہا کہ مجھے ایک پیالہ پیش کیا جائے یہ مجھے بیٹے کی خوشخبری ملنے سے زیادہ پسند ہے۔ آپ صلی اللہ علیہ وسلم سے اس بات کا تذکرہ ہوا آپ نے فرمایا: ”وہ تو دل کا پھل ہوتے ہیں“۔(2) ابو نعیم لکھتے ہیں: مشہور یہ ہے کہ یہ بات اشعث نے کہی تھی، ہو سکتا ہے آپ نے اشعث کی کم رحی کو جماد سے تشبیہ دے کر ان کا لقب جماد رکھ دیا ہو۔ میں کہتا ہوں: ایسی بات نہیں۔ بلکہ مشہور یہ ہے کہ اشعث کو جمد الکندی کی بیٹی سے بیٹے کی خوشخبری دی گئی تو انہوں نے یہ کہا جو کچھ کہا۔ جمد ان چار بادشاہوں میں سے ایک ہے جو خلافت صدیقی میں مرتد ہو کر قتل کیے گئے تھے۔ اس کی بیٹی اشعث کے نکاح میں تھی۔","",{"fn":"(1) اسد الغابۃ (۷۷۵)\n(2) المستدرک (۲۳۹/۴) تہذیب تاریخ دمشق (۶۹/۳) جامع المسانید (۱۱۰/۳)"}],[1345,"§۱۳۴۶ ۔ جمیش بن یزید بن مالک نخعی\nبقول بعض انہیں خدمت نبوی میں آنے کی سعادت حاصل ہے۔ میں کہتا ہوں: ذہبی(1) نے یہ ذکر نہیں کیا کہ انہوں نے یہ بات کہاں سے نقل کی۔ اور نہ مجھے اسد الغابۃ کے باب ج م میں یہ نام ملا ہے۔ دراصل یہ لفظی غلطی ہے۔ یہ نام تو جمیش جیم ھا سے تصغیر تھا۔ قسم اول میں گزر چکا ہے۔ ذہبی نے اسے دوبارہ درست ذکر کیا لیکن کہا ہے کہ ابن کلبی نے ان کا ذکر کیا ہے۔","",{"fn":"(1) التجرید (۲۶/۱)"}],[1346,"§۱۳۴۷ ۔ جندب بن بجیلہ\nعبد اللہ کے بیٹے ہیں، تذکرہ آئے گا۔ میں کہتا ہوں: تجرید(1) میں ایسا ہی ہے۔ یہ بھی لفظی غلطی ہے۔ بعض طریق میں جندب بن بجیلہ لکھا ہے۔","",{"fn":"(1) التجرید (۲۶/۱)"}],[1347,"§۱۳۴۸ ۔ (ز) جندب بن زہیر العامری(1)\nابن فتحون نے ذیل میں، ان میں اور جندب بن زہیر الازدی میں فرق کیا ہے۔ حالانکہ دونوں ایک ہیں۔ وہ غامدی (غین دال سے) ہیں نہ کہ عامری (عین اور را سے) اور غامد ازد کا بطن ہے۔","",{"fn":"(1) اسد الغابۃ (۸۰۲)"}],[1348,"§۱۳۴۹ ۔ جندب(1)\nابو ناجیہ۔ ابن مندہ نے ان کا ذکر کیا اور ابراہیم بن ابی داؤد کے طریق سے بحوالہ خول بن ابراہیم، اسرائیل سے وہ مجزأۃ بن زاہر اسلمی سے وہ ناجیہ بن جندب سے وہ اپنے والد سے روایت کرتے ہیں۔ میں اس وقت نبی صلی اللہ علیہ وسلم کے پاس آیا جب آپ نے قربانی کا جانور روک لیا۔ میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! میرے ساتھ قربانی کا جانور بھیج دیجیے۔ (حدیث)۔(2) ایسا ہی باوردی اور طحاوی نے نقل کیا ہے ابن مندہ فرماتے ہیں: ابو حاتم رازی نے بحوالہ خول ان سے مخالف نقل کیا ہے۔ ابو نعیم لکھتے ہیں: اس میں بعض راویوں کو وہم ہوا ہے انہوں نے مجزأۃ کی روایت جو بحوالہ ان کے والد، ناجیہ سے بدل دی ہے اور مجزأۃ سے بحوالہ ناجیہ ان کے والد کر دی ہے پھر عمرو بن محمد عنقزی کے طریق سے بحوالہ اسرائیل صحیح نقل کی ہے فرماتے ہیں: اثبات کی روایت بحوالہ اسرائیل اس کے موافق ہے۔ میں کہتا ہوں: اسے نسائی نے بروایت عبد اللہ بن موسیٰ، بحوالہ اسرائیل، مجزأۃ سے روایت کیا ہے فرماتے ہیں: مجھے ناجیہ بن جندب نے بتایا، لہذا احتمال ہے کہ مجزأۃ نے ناجیہ سے اور اپنے والد سے بحوالہ ناجیہ سنی ہو۔ رہے جندب تو اسناد میں ان کا کوئی دخل نہیں۔ واللہ تعالیٰ اعلم","",{"fn":"(1) اسد الغابۃ (۸۰۹)\n(2) مسند احمد (۲۳۴/۴) المستدرک (۶۱۲/۳) کنز العمال (۱۲۷۱۹)"}],[1349,"§۱۳۵۰ ۔ جنید بن سمیع المزنی\nعقیلی نے ان کا صحابہ میں تذکرہ کیا ہے ایسا ہی تجرید(1) میں ہے حالانکہ وہ جنید بن سمیع ہیں جیسا کہ قسم اول میں گزر چکا ہے۔","",{"fn":"(1) التجرید (۲۶/۱)"}],[1350,"§۱۳۵۱ ۔ جنیفۃ النہدی\nعقیلی نے ان کا صحابہ میں ذکر کیا ہے اور تجرید(1) میں بھی ایسا ہے جبکہ یہ لفظی غلطی پر بنی ہے حالانکہ یہ نام جفیفہ (فاء نون سے پہلے) ہے جیسا کہ گزر گیا۔","",{"fn":"(1) التجرید ایضاً"}],[1351,"§۱۳۵۲ ۔ الجہدمہ(1)\n(بے نسبت) ابن شاہین نے حرف جیم کے آخر میں ان کا ذکر کیا ہے اور منصور بن ابی الاسود کے طریق سے بحوالہ جناب، ایاد سے وہ جہدمہ سے روایت کرتے ہیں۔ فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو اس وقت دیکھا جب آپ نماز کے لیے باہر تشریف لائے آپ کے سر پر مہندی کی خوشبو تھی۔(2) میں نے بعض حفاظ کے قلم سے اس پر حاشیہ لکھا دیکھا ہے: جہدمہ عورت ہے جو بشیر بن خصاصیہ کی بیوی ہے۔ مصنف نے نساء میں ان کا تذکرہ کیا ہے۔ لیکن قسم اول بحوالہ تجرید(3) ذہبی گزر چکا ہے کہ جہدمہ حاء بے نقطی سے ہے نہ کہ ھاء سے۔ اور یہ بھی ذکر کیا کہ بروایت ابو جناب، ایاد بن لقیط ان سے مروی ایک حدیث ہے۔ پھر کہا: بقول بعض: وہ ابو رمشہ اھ مجھے کوئی ایسا شخص معلوم نہیں جس نے ابو رمشہ کا یہ نام لیا ہو۔ کنیتوں میں ذکر ہوگا۔","",{"fn":"(1) اسد الغابۃ (۸۱۹)\n(2) مجمع الزوائد (۱۶۲/۵) جامع المسانید (۱۶۶/۳)\n(3) التجرید (۲۷/۱)"}],[1352,"§۱۳۵۳ ۔ جہم الاسلمی(1)\nابن مندہ نے ابن لہیعہ کے طریق سے بحوالہ یونس بن یزید، ابو اسحاق سے انہوں نے محمد بن طلحہ سے انہوں نے اپنے والد سے انہوں نے معاویہ بن جہم اسلمی سے، انہوں نے جہم سے نقل کیا ہے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر عرض کی: میرا جہاد کا ارادہ ہے:...... (حدیث)۔(2) میں کہتا ہوں: یہ غلط ہے اس میں ابن لہیعہ سے لفظی خطا ہوئی ہے۔ یوں ان کا نام اور نسبت غلط ہو گئی وہ تو جاہمہ سلمی ہیں جیسا کہ پہلے صحیح گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۲۱)\n(2) نسائی کتاب الجہاد باب الرخصة فی التخلف لمن لہ والدة (۳۱۰۴) ابن ماجہ کتاب الجہاد باب الرجل یغزو ولہ ابوان (۲۷۸) مسند احمد (۴۲۹/۳) المعجم الکبیر (۲۲۰۲/۲)"}],[1353,"§۱۳۵۴ ۔ جون بن قتادہ(1)\nبن اعور بن ساعدہ بن عوف بن کعب بن عبد شمس بن زید مناۃ بن تمیم تمیمی تابعی ہیں۔ کسی راوی کو وہم ہوا اور ان سے موصولا حدیث روایت کر دی جس میں صحابی کا نام ساقط کر دیا ہے اسی غلطی کی بنا پر بغوی وغیرہ نے انہیں صحابہ میں ذکر کر دیا۔ ان کے والد صحابی ہیں۔ جن کا اپنے مقام پر ذکر آئے گا۔ بغوی کہتے ہیں: ہمیں میرے دادا احمد بن منیع اور شجاع بن مخلد نے بتایا کہ ہمیں ہشیم نے بیان کیا۔ اور ابن قانع نے حسن بن عرفہ کے طریق سے روایت کیا ہے۔ ابن مندہ نے یحییٰ بن ایوب کے طریق سے دونوں سے بحوالہ منصور سے وہ حسن سے وہ جون بن قتادہ تمیمی سے، فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی سفر میں تھے آپ کا کوئی صحابی لٹکے مشکیزے کے پاس سے گزرا جس میں پانی تھا اس نے پانی پینا چاہا مشکیزے والے نے کہا: یہ مردار کی کھال کا مشکیزہ ہے لوگوں نے آپ صلی اللہ علیہ وسلم سے اس کا ذکر کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس کا پانی پی لو کیونکہ دباغت (چمڑے کو پختہ کرنا) ہی اس کی پاکی کا ذریعہ ہے۔(2) بغوی لکھتے ہیں: ایسا ہی اسے ہشیم نے بیان کیا اور جون بن قتادہ سے آگے تجاوز نہیں کیا۔ جون صحابی نہیں۔ ابن مندہ فرماتے ہیں: اس میں ہشیم کو وہم ہوا ہے۔ جون کو نہ شرف صحابیت حاصل ہے اور نہ رؤیت (دیدار) فرماتے ہیں: اسی روایت کو قتادہ نے بحوالہ حسن، جون سے انہوں نے سلمہ بن محبق سے روایت کیا ہے۔ ابو نعیم تحریر کرتے ہیں: اسے زکریا بن یحییٰ زحمویہ نے بحوالہ ہشیم روایت کیا۔ اور اسناد میں سلمہ بن محبق کا ذکر کیا پھر ان کے طریق سے ایسا ہی نقل کیا ہے۔ فرماتے ہیں: اسے زحمویہ نے بہترین انداز سے روایت کیا ہے۔ ان سے روایت کنندہ اسلم بن سہیل واسطی ہیں جو اہل واسط کے اکابر حفاظ علماء میں سے ہیں۔ اب ظاہر ہو گیا کہ وہم میں مبتلا ہونے والے ہشیم کے علاوہ کوئی ہیں۔ مزی نے ان کا تعاقب کرتے ہوئے لکھا ہے: کہ ابن مندہ کی بات درست ہے کہ وہم ہشیم سے ہوا ہے اور زحمویہ کی روایت شاذ ہے۔ میں کہتا ہوں: کہ احتمال ہے کہ ہشیم نے وہم کی بنا پر کئی بار اور درست ایک بار روایت کیا اور ابو محمد بن حزم کو ہشیم کی ظاہری اسناد سے دھوکا ہوا اور انہوں نے طبری کے طریق سے بحوالہ محمد بن حاتم، ہشیم سے روایت کر کے اسے ذکر کر دیا۔ جیسا کہ احمد بن منیع اور ان کے پیروکاروں نے روایت کیا ہے فرماتے ہیں: یہ صحیح حدیث ہے۔ جون کی صحابیت صحیح ہے۔ ابو بکر بن معوز نے ان کا تعاقب کر کے کہا: یہ غلطی ہے جون ایک نامعلوم تابعی ہیں جن سے صرف حسن نے روایت کی ہے اور اس حدیث کی ان کی طرف یہی روایت ہے جو سلمہ بن محبق سے مروی ہے۔ اس میں محمد بن حاتم سے غلطی ہوئی ہے۔ میں کہتا ہوں: انہوں نے اس سلسلہ میں محمد بن حاتم کی طرف غلطی کی نسبت کرنے میں صحیح اقدام نہیں کیا۔ ان کا یہ کہنا: کہ جون مجہول شخصیت ہے یہی بات ابو طالب اور اشرم نے بحوالہ امام احمد بن حنبل کہی ہے۔ ابو الحسن بن براء بحوالہ علی بن المدائنی فرماتے ہیں: جون معروف شخصیت ہے اگرچہ ان سے صرف حسن نے روایت لی ہے دوسرے مقام میں انہیں حسن کے مجہول (نامعلوم) شیوخ میں شمار کیا ہے۔ جون بن قتادہ نے زبیر بن عوام رضی اللہ عنہ سے بھی روایت کی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۲۶)\n(2) کنز العمال (۲۶۷۷۲) (۲۷۳۱۳) تہذیب تاریخ دمشق (۴۱۸/۳)"}],[1354,"§۱۳۵۵ ۔ حابس بن دغنہ الکلبی(1)\nنبوت کی نشانیوں کے بارے میں ان کی ایک روایت ہے۔ شرف صحابیت رکھتے ہیں۔ ابو عمر نے اسی طرح مختصر ان کا تذکرہ کیا ہے۔ مذکورہ روایت ہشام بن کلبی نے حدیث عدی بن حاتم نقل کی ہے کہ میرا ملازم جس کا کلب سے تعلق تھا اور اسے حابس بن دغنہ کہا جاتا تھا ایک دفعہ میں اپنے صحن میں بیٹھا ہوا تھا وہ ہانپتا کانپتا میرے پاس آیا، کہنے لگا: اپنے اونٹ سنبھال لیجیے! میں نے کہا: ہوا کیا ہے؟ کہنے لگا: میں وادی میں تھا اچانک پہاڑ کی گھاٹی سے بوڑھا شخص میری جانب بڑھا اس کا سر بالکل سفید تھا وہ زمین پر عقاب کی طرح بغیر کسی جنبش کے زری سے اترا، یہاں تک کہ اس کے پاؤں میدان پر ٹک گئے۔ مجھے جو کچھ نظر آ رہا تھا میں اسے عظیم سمجھ رہا تھا۔ پھر اس نے کہا: حابس بن دغنہ اے حابس! و سو سے تیرا دل ہرگز نہ موڑیں، روشنی اس کے ہاتھ سے ظاہر ہو چکی جس کے پاس چنگاری ہے۔ حق کی جانب مائل ہو جاؤ اور خود کو دھوکے میں نہ ڈالو، پھر وہ غائب ہو گیا۔ میں نے شام کو اونٹ لیے اور صبح کسی اور وادی میں چھوڑ دیے اور لیٹ گیا ایک سوار مجھے پاؤں کی ٹھوکر سے بیدار کر دیتا تو وہ وہی شخص تھا کہنے لگا: حابس! میں جو کچھ کہہ رہا ہوں اسے سنو ہدایت پاؤ گے۔ گمراہ اور پریشان و حیران ہدایت یافتہ کی طرح نہیں ہوتا، سیدھے راستے کی روش کو ہرگز نہ چھوڑنا دین احمد کی وجہ سے سارے مذاہب منسوخ ہو گئے۔ تو میں بے ہوش ہو گیا پھر تھوڑی دیر بعد مجھے افاقہ ہوا، اس کے بعد بقیہ واقعہ ذکر کیا۔ اس کے آخر میں ہے، حابس نے کہا: عدی اللہ نے میرے دل کو اسلام کے لیے منقّب فرما دیا ہے، پھر وہ مجھ سے جدا ہو گیا یہ اس کے ساتھ میری آخری گفتگو تھی۔","",{"fn":"(1) اسد الغابۃ (۸۲۴) استیعاب (۳۸۸)"}],[1355,"§۱۳۵۶ ۔ حابس بن ربیعہ\nلتمیمی،(1) بقول ابن حبان: حابس تمیمی صحابی ہیں۔ ابن السکن فرماتے ہیں: اہل بصرہ میں شمار ہوتے ہیں۔ ان سے ان کا بیٹا تحیہ روایت کرتا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: ”نظر (کا لگنا) حق ہے“۔(2) اسے امام، ترمذی، ابن خزیمہ اور امام بخاری نے اپنی تاریخ اور الاوب المفرد میں سب نے بطریق یحییٰ بن ابی کثیر عن حیہ نقل کیا ہے۔ اور شیبان فرماتے ہیں عن یحییٰ عن حیہ عن ابی ہریرہ، پہلی سند زیادہ صحیح ہے۔ ابن السکن فرماتے ہیں: بقول بعض: صحابی ہیں، یحییٰ بن ابی کثیر سے آگے راویوں میں اختلاف ہے ہمیں یہ روایت انہی کے طریق سے ملی ہے۔ بغوی فرماتے ہیں: ان کی صرف یہی حدیث معلوم ہے۔ ابن عبد البر کا قول ہے: ان کی حدیث کی اسناد میں اضطراب ہے۔ اور ان کے والد کا نام ربیعہ بتایا ہے۔ میں کہتا ہوں: اس کے کسی طریق میں ہے حیہ بن حابس یا عابس۔ اس میں جو اختلاف ہے وہ ابن ابی عاصم نے اور ابو یعلیٰ نے اور طریق عن یحییٰ بن ابی کثیر نقل کیا ہے کہ مجھ سے حیہ بن حابس نے بیان کیا میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔۔۔۔ حدیث۔ اس میں سے عن ابیہ کے الفاظ رہ گئے۔ ابو موسیٰ نے حرف حاء کے آخر میں ان کا ذکر کیا ہے لکھتے ہیں: ”حبّہ“ اور اس میں وہم کی طرف اشارہ کر دیا کہ درست عن حبّہ عن ابیہ عن النبی صلی اللہ علیہ وسلم ہے۔","",{"fn":"(1) اسد الغابۃ (۸۲۵) استیعاب (۳۹۰)\n(2) ترمذی کتاب الطب باب ما جاء ان العین حق حدیث (۲۱۴۰) مسند احمد (۳۱۹/۲) بخاری فی تاریخہ (۱۰۸/۳)"}],[1356,"§۱۳۵۷ ۔ حابس بن ربیعہ الیمانی\nبقول ابن حبان صحابی ہیں۔ باوردی کا قول ہے: امیر معاویہ کی طرفداری میں صفین میں شہید ہوئے۔ طبرانی نے بطریق عبد الواحد بن ابی عون روایت کی ہے سیدنا علی جنگ صفین میں حابس کے پاس سے گزرے پھر ایک واقعہ نقل کیا یہ عبادت گزاروں میں شمار ہوتے تھے۔ پھر قصہ ذکر کیا۔"],[1357,"§۱۳۵۸ ۔ حابس بن سعد(1)\nبن المنذر بن ربیعہ بن سعد بن بشر بن طائی۔ ابن سعد اور ابو زرعہ دمشقی نے شام میں فر و کش ہونے والے صحابہ میں ان کا تذکرہ کیا ہے اور ابن سمیع نے صحابہ کے پہلے طبقہ میں ان کا ذکر کیا ہے۔ امام بخاری(2) فرماتے ہیں: دور نبوی پایا ہے۔ امام احمد(3) نے عبد اللہ بن غابر کے طریق سے روایت کیا ہے۔ حابس بن سعد سحری کے وقت مسجد میں داخل ہوئے، انہوں نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا تھا لوگوں کو دیکھا کہ وہ مسجد کے چبوترے میں نماز پڑھ رہے ہیں۔ فرمایا: ”دکھلاوا کر رہے ہیں۔ انہیں دھمکاؤ! فرشتے سحری کے وقت مسجد کے اگلے حصہ میں نماز پڑھتے ہیں۔“ یہ حدیث موقوف ہے اگرچہ اس کی سند صحیح ہے، ابن السکن فرماتے ہیں: کسی نے ان سے ایک حدیث روایت کی ہے جس میں گمان کیا: کہ وہ صحابی ہیں۔ ابن ابی حاتم(4) خلیفہ اور کئی ایک حضرات نے ان کا ذکر کیا ہے۔ وہ جنگ صفین میں سیدنا معاویہ رضی اللہ عنہ کے ساتھ شہید ہوئے۔ گویا وہ ان کے نزدیک پہلے شخص ہیں۔ لیکن باوردی وغیرہ نے دونوں میں فرق کیا ہے۔ ابن عبد البر نے ان کا ذکر کیا ہے کہ وہ اہل شام میں یمانی سے مشہور تھے تاریخ سے واقف کسی شخص نے ذکر کیا کہ سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: میں تمہیں حمص کا قاضی بنانا چاہتا ہوں اور ان کے خواب میں چاند سورج کی لڑائی والا قصہ ذکر کیا کہ وہ چاند کے ساتھ تھے سیدنا عمر رضی اللہ عنہ نے فرمایا: تم ختم ہونے والی نشانی کے ساتھ تھے تم میرے کسی کام(5) کے ذمہ دار نہیں بن سکتے۔","",{"fn":"(1) اسد الغابۃ (۸۳۶) الاستيعاب (۳۸۹)\n(2) التاریخ الکبیر (۱۰۸/۱)\n(3) مسند احمد (۱۰۵۔۱۰۹/۴)\n(4) الجرح والتعدیل (۲۹۲/۳)\n(5) جامع المسانید (۱۷۴، ۱۷۵/۳)"}],[1358,"§۱۳۵۹ ۔ حابس بن سعد یمانی\nعبدالصمد بن سعید حمصی نے حمص فروکش ہونے والے صحابہ کے نام میں ان کا ذکر کیا ہے کہ وہ حمص اترے (کچھ عرصہ رہ کر) پھر وہاں سے کوچ کر گئے۔ یہ بات انہوں نے محمد بن عوف وغیرہ کے حوالہ سے نقل کی ہے۔ ان میں اور سابقہ حابس بن سعد کے درمیان فرق کیا ہے۔ یہ بھی احتمال ہے کہ دونوں ایک ہوں کیونکہ سعد اور سعید قریب قریب (نام) ہیں۔"],[1359,"§۱۳۶۰ ۔ حاجب بن زرارہ\nبن عدس بن زید بن عبداللہ بن دارم دارمی تمیمی، عطارد کے والد۔ حرف صاد بے نقطہ میں صفوان بن اسید کے سوانح میں ان کا ذکر آئے گا۔ اسی میں ان کے مسلمان ہونے کا قصہ ہے اور یہ کہ نبی صلی اللہ علیہ وسلم نے انہیں بنی تمیم کی زکوۃ وصول کرنے کے لئے بھیجا تھا۔ قسم ثالث میں اکثم بن صیفی کے حالات میں ان کا تذکرہ ہو چکا ہے اور خالد بن مالک کے سوانح میں ذکر ہوگا۔ مرزبانی لکھتے ہیں: وہ کئی مقامات پر بنی تمیم کے سردار رہے انہی نے بہت زیادہ مال کے بدلے میں کسریٰ کے پاس اپنی کمان رکھوائی تھی اور اس نے وہ مال انہیں ادا کیا تھا اور اسی کے بارے میں اشعار میں فخر کرتے ہیں۔ “ہم میں سے ہی ماء المزن اور محرق کا بیٹا ہے اور پھر ان میں بجیر اور حاجب ظاہر ہوئے تین بادشاہ جو ہماری گود میں پلے بڑھے اور ہم میں سے وہ فخر ہے جو جھوٹا نہیں”"],[1360,"§۱۳۶۱ ۔ حاجب بن زید(1)\nبن تیم بن امیہ بن خفاف بن بیاضہ انصاری اوسی ثم بیاضی، طبری نے ذکر کیا کہ وہ احد میں شریک تھے ایسا ہی ابن شاہین نے اپنے شیوخ سے نقل کیا ہے ابو عمر(2) نے ان کی روایت اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۳۹) الاستيعاب (۳۹۲)\n(2) الاستيعاب (۳۴۵/۱)"}],[1361,"§۱۳۶۲ ۔ حاجب(1)\nبن زید یا یزید انصاری اشہلی بقول بعض از دشتوں میں سے ان کے حلیف ہیں۔ جنگ یمامہ کے روز شہید ہوئے ایسا ہی تجرید میں (ذہبی نے) ذکر کیا ہے سیف نے جنگ یمامہ میں بنی عبد الاشہل کے شہداء میں ان کا ذکر کیا ہے اور ایک جماعت کا تذکرہ کرنے کے بعد فرماتے ہیں: حاجب بن زید اس پر اضافہ نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۸۴۰) الاستيعاب (۳۹۱)"}],[1362,"§۱۳۶۳ ۔ حارث بن اسد(1)\nبن عبد العزیٰ بن جعونہ بن عمرو بن القیس بن رزاح بن عمرو بن سعد بن کعب خزاعی۔ ہشام بن کلبی فرماتے ہیں: صحابی ہیں۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا، ابن ماکولا نے بھی ان کا تذکرہ کیا ہے۔ جمہرہ میں ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابۃ (۸۴۲)"}],[1363,"§۱۳۶۴ ۔ (ز) الحارث بن اقیش(1)\nقاف شین سے تصغیر سے بقول بعض وقیش عکلی ثم عوفی، انصار کے حلیف۔ انہیں حارث بن زہیر بن اقیش بھی کہا جاتا ہے۔ ابن ماجہ(2) نے شفاعت میں صحیح سند سے ان کی حدیث روایت کی ہے، ان کی ایک اور حدیث ان لوگوں کے بارے میں ہے جن کے تین بچے فوت ہو گئے۔ ابن خزیمہ(3) نے دوسری حدیث کے ساتھ جمع کر کے نقل کی ہے، بغوی میں نبی صلی اللہ علیہ وسلم سے ان کی سماعت کی تصریح موجود ہے۔","",{"fn":"(1) اسد الغابۃ (۸۴۴) الاستيعاب (۳۹۹)\n(2) ابن ماجہ کتاب الزهد باب صفة النار (۴۳۲۳)\n(3) مسند احمد (۲۱۲/۴) جامع المسانید (۱۹۲/۳)"}],[1364,"§۱۳۶۵ ۔ (ز) الحارث بن الاسلت\nابو قیس، اپنی کنیت سے مشہور ہیں، کنیتوں میں ذکر آئے گا۔"],[1365,"§۱۳۶۶ ۔ الحارث بن اشیم\nحارث بن اوس میں ذکر ہوگا۔"],[1366,"§۱۳۶۷ ۔ الحارث بن انس(1)\nبن رافع انصاری۔ ابن اسحاق نے شرکاء بدر میں ان کا تذکرہ کیا ہے۔ ابن شاہین نے شریک بن ابی الحیسر کے سوانح میں لکھا ہے کہ ابو الحیسر کا نام انس بن رافع بن امرئی القیس بن زید بن عبد الاشہل ہے۔ حارث بن انس رضی اللہ عنہ کے بھائی جو بدر میں شریک ہوئے، شریک اور ان کا بیٹا عبداللہ ان کے ساتھ اُحد میں شریک تھا۔ یہ بات ہمیں محمد نے بحوالہ محمد بن یزید ان کے رجال سے روایت کی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۴۵) الاستيعاب (۳۹۶)"}],[1367,"§۱۳۶۸ ۔ حارث بن انس بن مالک(1)\nابن عبید بن کعب انصاری، از بنی النبیت نون کا زبر باء کا زیر اس کے بعد یا ساکن ہے پھر تا ہے۔ موسیٰ بن عقبہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابو عمر(2) کہتے ہیں: مجھے خدشہ ہے یہ حارث بن انس بن رافع نہ ہوں۔ میں کہتا ہوں: بلکہ یہ ان کے علاوہ کوئی شخصیت ہے جیسا کہ بعد والے عنوان میں بیان کروں گا۔","",{"fn":"(1) اسد الغابۃ (۸۴۶) الاستيعاب (۳۹۷)\n(2) اسد الغابۃ (۳۶۱/۱) الاستيعاب (۳۴۷/۱)"}],[1368,"§۱۳۶۹ ۔ (ز) حارث بن انیس\nابو عبدالرحمن العمری، کنیتوں میں تذکرہ ہوگا بقول بعض یہ حارث بن یزید ہیں۔"],[1369,"§۱۳۷۰ ۔ (ز) حارث بن اہبان\nحارث بن وہبان میں ذکر ہوگا۔"],[1370,"§۱۳۷۱ ۔ حارث بن اوس(1)\nبن رافع بن امرئی القیس بن زید بن عبد الاشہل انصاری اوسی ثم الاشہلی۔ ابو معشر نے شرکاء بدر میں ان کا ذکر کیا ہے اور موسیٰ بن عقبہ ان کا تذکرہ کرتے ہوئے رقمطراز ہیں: حارث بن اوس لیکن ان کے دادا کا نام نہیں لیا۔ اور ابن لہیعہ نے بحوالہ ابو الاسود ان کا ذکر کیا مگر یوں کہا: حارث بن اشیم۔ طبرانی(2) نے ان کی حدیث نقل کی ہے، ان کے متعلق بعض کا قول ہے: حارث بن انس بن رافع۔","",{"fn":"(1) اسد الغابۃ (۸۵۲)\n(2) المعجم الکبیر (۳۳۲۲/۳)"}],[1371,"§۱۳۷۲ ۔ حارث بن اوس\nبن عتیک بن عمرو بن عبدالاعلم بن عامر بن زعوراء بن جشم بن حارث بن خزرج انصاری۔ قداح نے نسب الانصار میں ان کا ذکر کیا اور ابن سعد نے کہا: وہ احد اور بعد کے غزوات میں شریک رہے، جنگ اجنادین میں شہید ہوئے۔"],[1372,"§۱۳۷۳ ۔ حارث بن اوس(1)\nبن معاذ بن نعمان انصاری ثم الاوسی اوس کے سردار سعد بن معاذ کے بھتیجے۔ ایک صحیح حدیث میں ان کا تذکرہ آیا ہے جسے امام احمد رحمہ اللہ(2) نے علقمہ بن وقاص کے طریق سے بحوالہ سیدہ عائشہ رضی اللہ عنہا نقل کیا ہے، فرماتی ہیں: خندق کے روز میں باہر نکلی تو میں نے ایک آہٹ سنی، کیا دیکھتی ہوں کہ سعد بن معاذ ہیں اور ان کے ساتھ ان کا بھتیجا ڈھال اٹھائے ہے۔ (حدیث) ابن حبان نے اسے صحیح قرار دیا ہے۔ ابو عمر کہتے ہیں: بدر میں شرکت کی اور اُحد میں شہید ہوئے، اس وقت ان کی عمر اٹھائیس(۲۸) برس تھی۔ میں کہتا ہوں: اس سلسلہ میں انہوں نے ابن کلبی کی خوشہ چینی کی جو وہم پر مبنی ہے بعض اہل نسب نے ان کا تعاقب کیا کہ مجھے شہداء اُحد میں ان کا نام نہیں ملا۔ میں کہتا ہوں: یہ احتمال بھی ہے کہ اُحد میں کوئی اور شہید ہوا ہو، اس لئے کہ اُحد، خندق سے بہت مدت پہلے واقع ہوا ہے۔ ادھر ابن اسحاق نے شہدائے اُحد میں حارث بن اوس بن معاذ کا ذکر کیا لیکن انہوں نے سعد بن معاذ رضی اللہ عنہ کا بھتیجا نہیں کہا تو وہ کوئی اور ہیں۔ رہے سعد کے بھتیجے تو وہ کعب بن اشرف کے قتل میں بھی شریک ہوئے ہیں۔ عنقریب ابو نائلہ کے سوانح میں ان کا ذکر آئے گا جو کنیتوں میں حرف نون کا حصہ ہے کہ سعد بن معاذ نے ان سے فرمایا: اپنے ساتھ میرے بھتیجے حارث بن اوس کو لے جاؤ۔ بخاری میں یہ روایت ثابت ہے۔ حدیث جابر ہے کہ محمد بن سلمہ اپنے ساتھ دو شخص ابو قیس بن جابر اور حارث بن اوس، لائے اور وہ یہی ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۸۴۹) الاستيعاب (۳۹۳)\n(2) مسند احمد (۱۴۱/۶)"}],[1373,"§۱۳۷۴ ۔ حارث بن اوس\nبن المعلیٰ بن لوذان ابو سعد، کنیتوں میں ذکر آئے گا۔"],[1374,"§۱۳۷۵ ۔ حارث بن اوس ثقفی(1)\nابن سعد لکھتے ہیں: صحابی ہیں۔ ان میں اور حارث بن عبداللہ بن اوس میں فرق کیا ہے، یہی فرق ابو حاتم اور ابن حبان نے کیا ہے، بقول بعض دونوں ایک ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۴۷) الاستيعاب (۴۲۷)"}],[1375,"§۱۳۷۶ ۔ حارث بن بدل\nقسم اخیر میں ذکر ہوگا۔"],[1376,"§۱۳۷۷ ۔ حارث بن برصاء\nابن مالک ہیں، برضاء ان کی والدہ کا نام ہے، تذکرہ ہوگا۔"],[1377,"§۱۳۷۸ ۔ حارث بن بلال مزنی(1)\nسیف نے فتوح میں اپنے شیوخ سے ذکر کیا ہے کہ سیدنا خالد بن ولید رضی اللہ عنہ کے ساتھ شریک صحابہ۔ جب آپ سے تقسیم کا کہا تو آپ نے انہیں مثنیٰ بن حارثہ کے ساتھ چھوڑ دیا۔ دوسرے مقام پر ذکر کرتے ہیں کہ وہ بنی طے کے آدھے قبیلے کے رسول اللہ صلی اللہ علیہ وسلم کی طرف سے عامل (گورنر) تھے۔ یہ ان حارث بن بلال مزنی کے علاوہ ہیں جو قسم رابع میں آ رہے ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۵۵)"}],[1378,"§۱۳۷۹ ۔ حارث بن تبیع رعینی(1)\nعبد الغنی بن سعید نے بحوالہ ابو سعید بن یونس ذکر کیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ بعد میں فتح مصر میں بھی شریک رہے(2)۔ لفظ تبیع تصغیر ہے۔ بقول بعض بروزن عظیم ہے۔","",{"fn":"(1) اسد الغابۃ (۸۵۶) الاستيعاب (۴۰۱)\n(2) اسد الغابۃ (۳۶۴/۱) الاستيعاب (۳۴۸/۱)"}],[1379,"§۱۳۸۰ ۔ (ز) حارث بن تمیم\nحارث بن ابی وجزہ میں تذکرہ ہوگا۔"],[1380,"§۱۳۸۱ ۔ (ز) حارث بن ثابت(1)\nبن سعید بن عدی بن امرئ القیس بن مالک بن ثعلبہ بن کعب بن خزرج انصاری۔ ابن شاہین نے اپنے شیوخ کے حوالہ سے ذکر کیا کہ وہ احد میں شہید ہوئے۔ ابن عبدالبر(2) نے ان کا ذکر کیا تو ان کے دادا کا نام سعید کی بجائے سفیان لیا۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۸۵۷) الاستيعاب (۴۰۲)\n(2) الاستيعاب (۳۴۸/۱)"}],[1381,"§۱۳۸۲ ۔ حارث بن ثابت\nبن عبداللہ بن سعد بن عمرو بن قیس بن عمرو بن امرئی القیس بن ثعلبہ بن کعب بن خزرج۔ ابن شاہین نے اپنے شیوخ سے نقل کیا ہے کہ یہ بھی اُحد میں شہید ہوئے۔ ادھر ابن الاثیر نے یہ امکان ظاہر کیا ہے کہ یہ پہلے والے شخص ہیں، لیکن درست نہیں۔ اس واسطے کہ دونوں نسبوں میں اختلاف کی وجہ سے دوسری شخصیت ہے۔"],[1382,"§۱۳۸۳ ۔ حارث بن جماز(1)\nبن مالک ابن ثعلبہ بن عتبان۔ بنی ساعدہ کے حلیف۔ طبری نے شرکاء اُحد میں، ایسا ہی ابن شاہین نے بحوالہ اپنے شیوخ ذکر کیا کہ یہ کعب بن جماز کے بھائی ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۵۹)"}],[1383,"§۱۳۸۴ ۔ حارث بن جندب عبدی\nوفد عبدالقیس کے ایک فرد۔ ابن سعد نے ان کا تذکرہ کیا۔ ان شاء اللہ تعالیٰ صحار بن عباس کے سوانح میں ان کا ذکر آئے گا۔ وہ وفد کے ساتھ آئے اور اسلام قبول کر کے گئے۔"],[1384,"§۱۳۸۵ ۔ (ز) حارث بن جنید عبدی\nاسمعیلی نے صحابہ میں ان کا ذکر کیا ہے اور ایسی سند بیان کی ہے جس میں علی بن قرین سے بحوالہ سعد بن عمرو طائی فرمایا کہ میں نے بنی عصر کے حارث بن عصر نامی شخص کو کہتے سنا: میں نے حارث بن جنید کو فرماتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: “تم لوگ (بحث و مباحثہ میں) جھگڑے سے بچنا اس لیے کہ جھگڑنا بھلائی نہیں سمجھاتا۔” (حدیث) علی (بن قرین) کو ناقدین نے متہم بالکذب قرار دیا ہے۔"],[1385,"§۱۳۸۶ ۔ حارث بن حارث اشعری شامی(1)\nصحابی ہیں، جن سے روایت کرنے میں ابوسلام متفرد ہیں۔ یہ ازدی کا قول ہے۔ ان کی کنیت ابو مالک ہے۔ کئی لوگوں نے وہم کی وجہ سے انہیں ابو مالک اشعری سے ملا دیا ہے جبکہ ابو مالک اپنی کنیت سے شہرت رکھتے ہیں۔ ان کے نام میں اختلاف ہے نیز اُن کی وفات ان سے پہلے ہوئی۔ اور ان کی شہرت اپنے نام سے ہے اور ان کی وفات اتنے عرصہ بعد ہوئی کہ ابوسلام نے ان سے سماع کیا۔ تہذیب التہذیب میں نے ان کے حالات کی وضاحت کر دی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۶۱) الاستيعاب (۴۰۵)"}],[1386,"§۱۳۸۷ ۔ حارث بن حارث ازدی(1)\nزا کے سکون سے کبھی سین سے بدل جاتی ہے۔ باوردی اور طبری وغیرہ نے عبادہ بن نسی کے طریق سے بحوالہ عدی بن ہلال سلمی، حارث بن حارث ازدی سے روایت کی ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، آپ صلی اللہ علیہ وسلم کھانے سے فراغت کے بعد یہ دعا پڑھتے تھے: اللَّهُمَّ لَكَ الْحَمْدُ أَطْعَمْتَ وَسَقَيْتَ وَأَرْوَيْتَ لَكَ الْحَمْدُ۔ “اے اللہ! تیرے لیے ہی سب تعریفیں ہیں، تو نے (ہمیں) کھلایا پلایا اور سیراب کر دیا تو ہی تعریفوں کے لائق ہے۔” (حدیث)(2)","",{"fn":"(1) اسد الغابۃ (۸۶۰) الاستيعاب (۴۰۶)\n(2) المعجم الکبیر (۳۰۴/۳) المصنف لعبد الرزاق (۲۸۴۲) کنز العمال (۱۶۷۱۱) (۱۸۱۸۰) اتحاف السادۃ المتقین (۱۲۳/۷، ۱۲۴)"}],[1387,"§۱۳۸۸ ۔ حارث بن حارث غامدی(1)\nابو مخارق کنیت رکھتے تھے۔ بقول ابن السکن اہل حمص میں شمار ہوتے ہیں۔ امام بخاری نے تاریخ میں، ابو زرعہ دمشقی، بغوی، ابن ابی عاصم اور طبرانی(2) نے ولید بن عبد الرحمن جرشی کے طریق سے نقل کیا ہے، فرمایا: مجھ سے حارث بن حارث غامدی نے بیان کیا کہ ایک دفعہ ہم لوگ منیٰ میں تھے میں نے اپنے والد سے کہا: یہ لوگوں کی کیسی بھیڑ ہے؟ انہوں نے کہا: یہ لوگ اپنے ایک بے دین شخص کے پاس جمع ہیں۔ میں نے جھانک کر دیکھا تو رسول اللہ صلی اللہ علیہ وسلم لوگوں کو اللہ تعالیٰ کی توحید کی طرف بلا رہے ہیں اور وہ آپ صلی اللہ علیہ وسلم کی تردید کر رہے ہیں۔ (حدیث) اسی طرح امام بخاری اور ابن السکن نے شریح بن عبید کے طریق سے بحوالہ حارث بن حارث اور کثیر بن مرہ وغیرہ سے “سردار قریش سے ہوں” نقل کی ہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: اسے خالد بن معدان نے حارث بن حارث غامدی سے نقل کیا ہے اور ابن السکن نے سلیم بن عامر کے طریق سے بحوالہ حارث بن حارث غامدی روایت کیا ہے۔ انہوں نے دور نبوی پایا ہے اور آپ سے احادیث روایت کی ہیں۔ ابو القاسم بن عیسیٰ نے طبقات حمصیین میں بحوالہ محمد بن عوف نقل کیا، فرمایا: ان کے لائق نہیں کہ وہ اہل حمص سے ہوں۔ پھر یہ ذکر کیا کہ ان سے سلیم بن عامر خالد بن معدان اور شریح بن عبید روایت کرتے ہیں، ان کا کسی چشمہ پر کھجوروں کا ایک باغ تھا، اور وہ جنگ راہط میں شہید ہوئے۔","",{"fn":"(1) اسد الغابۃ (۸۶۲) الاستيعاب (۴۰۷)\n(2) المعجم الکبیر (۳۳۷۳/۳)"}],[1388,"§۱۳۸۹ ۔ حارث بن حارث(1)\nبن قیس بن عدی بن سعد بن سہم قرشی سہمی ابو الاسود نے بحوالہ عروہ شہدائے اجنادین میں ان کا ذکر کیا ہے، ایسا ہی ابو حذیفہ(2) بخاری نے مبتدا میں اور ابن اسحاق اور دیگر کئی لوگوں نے ان کا ذکر کیا ہے۔ سیف کی کتاب فتوح میں لکھا ہے کہ وہ جنگ یرموک میں شہید ہوئے۔ بلاذری فرماتے ہیں: “بعض نے ذکر کیا ہے کہ وہ اپنے بھائیوں کے ساتھ حبشہ ہجرت کر کے گئے”۔ فرماتے ہیں: ان کی ہجرت ثابت نہیں، ان کے والد کا تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابۃ (۸۶۳) الاستيعاب (۴۰۳)\n(2) اسد الغابۃ (۳۶۷/۱) الاستيعاب (۳۴۸/۱)"}],[1389,"§۱۳۹۰ ۔ حارث بن حارث(1)\nبن کلدہ بن عمرو بن علاج ثقفی۔ ابن عبدالبر(2) نے فرمایا: تالیف قلبی والوں میں سے تھے۔ جہاں تک ان کے والد کا تعلق ہے تو ان کا مسلمان ہونا صحیح نہیں۔ میں کہتا ہوں: اس کی تردید حارث بن کلدہ کے حالات میں آئے گی۔","",{"fn":"(1) اسد الغابۃ (۸۶۴) الاستيعاب (۴۰۴)\n(2) الاستيعاب (۳۴۸/۱)"}],[1390,"§۱۳۹۱ ۔ حارث بن ابی حارثہ\nابن فتحون نے بحوالہ طبری ذکر کیا کہ نبی صلی اللہ علیہ وسلم نے ان کی بیٹی جمرہ بنت حارث کے لئے نکاح کا پیام بھیجا، انہوں نے کہہ دیا کہ اسے کوئی بیماری ہے حالانکہ کچھ بھی نہ تھا۔ واپس آکر دیکھا تو اسے برص کی بیماری لگ چکی تھی۔"],[1391,"§۱۳۹۲ ۔ حارث بن حاطب(1)\nبن حارث بن معمر بن حبیب بن وہب بن حذافہ بن جمح قرشی جمحی۔ ان کے والد نے حبشہ ہجرت کی جہاں ان کے ہاں حارث اور محمد پیدا ہوئے۔ یہ زہری کا قول ہے اور مصعب کے کلام سے پتہ چلتا ہے کہ حارث ہجرت حبشہ سے پہلے پیدا ہوئے۔ اور وہاں جو پیدا ہوئے وہ ان کے بھائی محمد تھے۔ ابن مندہ سے نادانستہ غلطی ہوئی اور انہوں نے بحوالہ ابن اسحاق یہ نقل کر دیا: حبشہ ہجرت کرنے والوں میں حارث بن حاطب ہیں۔ مغازی ابن اسحاق اور اس کے اختصار میں جو ابن ہشام کی ہے یہ بات لکھی ہے کہ وہ حاطب بن حارث تھے۔ حارث بن حاطب کو نبی علیہ السلام سے روایت کرنا حاصل ہے ان کی روایت ابو داؤد(2) اور نسائی میں ہے ان سے حسین بن حارث جدلی وغیرہ روایت کرتے ہیں۔ مصعب زبیری نے لکھا ہے کہ مروان نے انہیں مدینہ میں زکوۃ کی وصولیابی پر مقرر کیا اور وہ مکہ میں ان کے بیٹے عبد الملک کے گورنر رہے۔ رہے ابن حبان تو انہوں نے انہیں تابعین میں ذکر کر کے وہم کیا ہے، اس لیے کہ ان کی حدیث کی نص یہ ہے ہمیں رسول اللہ صلی اللہ علیہ وسلم نے وصیت فرمائی۔","",{"fn":"(1) اسد الغابۃ (۸۶۵) الاستيعاب (۴۰۹)\n(2) ابو داؤد کتاب الصیام (۲۳۳۸)"}],[1392,"§۱۳۹۳ ۔ حارث بن حاطب(1)\nبن عمرو بن عبید بن امیہ بن زید انصاری اوسی، ثعلبہ بن حاطب کے بھائی۔ موسیٰ بن عقبہ نے شرکاء بدر میں ان کا ذکر کیا۔ انہی نے اور ابن اسحاق نے ذکر کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اور ابو لبابہ کو مقام روحاء سے واپس کر دیا تھا اور ان کا حصہ اور اجر مقرر فرمایا۔ ادھر ابن مندہ سے بھول ہوئی اور انہوں نے یہ بات سابقہ شخصیت کے ذیل میں ذکر کر دی۔ طبرانی(2) نے ایک ضعیف سند سے نقل کیا ہے کہ وہ سیدنا علی رضی اللہ عنہ کا ساتھ دینے کے لیے جنگ صفین میں شریک ہوئے۔","",{"fn":"(1) اسد الغابۃ (۸۶۶) الاستيعاب (۴۰۸)\n(2) المعجم الکبیر (۳۴۰۳/۲)"}],[1393,"§۱۳۹۴ ۔ حارث بن حباب(1)\nبن ارقم بن عوف بن وہب انصاری ابو معاذ القاری۔ حارثہ بن نعمان کے ماں شریک بھائی۔ غندوی نے شرکاء اُحد اور جسر ابی عبیدہ کے شہداء میں ان کا تذکرہ کیا ہے۔ یہ بات ابن شاہین نے اپنے شیوخ سے روایت کی ہے اور ابن السکن نے کہا: وہ خلافت فاروقی میں فوت ہوئے۔","",{"fn":"(1) اسد الغابۃ (۸۶۷)"}],[1394,"§۱۳۹۵ ۔ حارث بن حبال(1)\nبن ربیعہ بن عجل بن انس بن جبلہ بن مالک بن سلامان بن اسلم اسلمی۔ ابن کلبی نے شرکاء حدیبیہ میں ان کا تذکرہ کیا ہے۔ ابن جریر اور ابن شاہین نے ان کی پیروی کی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۶۸)"}],[1395,"§۱۳۹۶ ۔ (ز) حارث بن حبیب\nبن خزیمہ بن مالک بن حنبل بن عامر بن لؤی قرشی عامری۔ خلیفہ بن خیاط نے مصر فروکش ہونے والے صحابہ میں ان کا تذکرہ کیا کہ وہ معبد بن عباس بن عبد المطلب کی رفاقت میں افریقہ میں شہید ہوئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[1396,"§۱۳۹۷ ۔ حارث بن حسان(1)\nانہیں ابن یزید البکری الذہلی بھی کہا جاتا ہے بقول بعض ان کا نام حریث ہے شاید یہ تصغیر ہے۔ امام احمد، ترمذی، نسائی اور ابن ماجہ نے ان کی روایت نقل کی، ان کی حدیث کے بعض طرق میں ہے کہ وہ نبی صلی اللہ علیہ وسلم کے(2) پاس آئے۔ ان سے ابو وائل، سماک بن حرب اور ایاد بن لقیط روایت کرتے ہیں۔ بغوی فرماتے ہیں: وہ دیہات میں رہتے تھے۔ طبرانی نے سماک بن حرب کے طریق سے روایت کیا کہ حارث بن حسان نے شادی بھی کی اور وہ صحابی ہیں۔ اس وقت ایسا ہوتا کہ جب کسی کی شادی ہوتی تو وہ چند ایام پردے میں رہتا، اس کے متعلق ان سے کہا گیا تو فرمایا: اللہ کی قسم! وہ ایک بری عورت ہے جو مجھے نماز فجر باجماعت ادا کرنے سے منع کرے۔ ان کی حدیث سے پتہ چلتا ہے کہ وہ اس وقت نبی صلی اللہ علیہ وسلم کے پاس آئے جب آپ صلی اللہ علیہ وسلم سیدنا عمرو بن العاص رضی اللہ عنہ کو غزوہ سلاسل میں بھیج رہے تھے۔ مجھے فتوح سے پتہ چلا ہے کہ جب احنف نے خراسان فتح کیا تو حارث بن حسان کو سرخس بھیجا شاید وہ یہی ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۶۹) الاستيعاب (۴۱۰)\n(2) ترمذی کتاب التفسیر باب من سورۃ الذاریات (۳۲۷۳) (۳۲۷۴) ابن ماجہ کتاب الجہاد باب الرایات والالویۃ (۲۸۱۶) مسند احمد (۴۸۱/۳)"}],[1397,"§۱۳۹۸ ۔ (ز) حارث بن ابی حیسر\nحارث بن انس بن رافع پہلے تذکرہ ہو چکا ہے۔"],[1398,"§۱۳۹۹ ۔ حارث بن خالد(1)\nبن سحر بن عامر بن کعب بن سعد بن تیم بن مرہ قرشی تیمی ابن اسحاق(2) وغیرہ نے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ ابن عائذ نے عطاء خراسانی کے طریق سے بحوالہ عکرمہ، سیدنا ابن عباس رضی اللہ عنہما سے روایت کیا کہ حبشہ ہجرت کرنے والوں میں جعفر بن ابی طالب کے ساتھ حارث بن خالد بن سحر بھی تھے۔ اور ابن ابی شیبہ نے موسیٰ بن عبیدہ کے طریق سے محمد بن ابراہیم بن حارث روایت کیا ان کے دادا مہاجرین میں سے تھے۔ ابن اسحاق فرماتے ہیں: ان کی بیوی ریطہ بنت حارث بن جبلہ بن عامر بن کعب سے حبشہ میں موسیٰ اور عائشہ زینب اور فاطمہ پیدا ہوئیں۔ اور جب مدینہ آئے تو نبی صلی اللہ علیہ وسلم نے بنت عبد یزید بن ہاشم بن مطلب سے ان کی شادی کر دی۔ بقول بعض جب وہ حبشہ سے نکلے تو ان کی اولاد ان کے ساتھ تھی، راستے میں ان لوگوں نے پانی پیا تو حارث کے سوا سب فوت ہو گئے۔ ابن عبدالبر(3) نے بحوالہ مصعب زبیری ان کا ذکر کیا تو زینب کی جگہ ابراہیم کا تذکرہ کیا۔ اور ابراہیم بن حارث کے متعلق (فوت ہونے یا نہ ہونے کی) تفصیل پہلے(۵) میں گزر چکی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۷۲) الاستيعاب (۴۱۱)\n(2) السیرۃ النبویۃ (۲۵۸/۱)\n(3) الاستيعاب (۳۵۱/۱)"}],[1399,"§۱۴۰۰ ۔ (ز) حارث بن خالد قرشی(1)\nابن مندہ فرماتے ہیں: ان کی حدیث ہشیم بن عبد الرحمن عدوی، بحوالہ موسیٰ بن الاشعث روایت کرتے ہیں کہ قریش کے حارث بن خالد نامی شخص ایک سفر میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے۔ وضو کا پانی لایا گیا تو آپ صلی اللہ علیہ وسلم نے وضو فرمایا۔ (حدیث)(2) ابن الاثیر نے یہ امکان ظاہر کیا ہے کہ یہ پہلے والی شخصیت ہو سکتی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۷۳)\n(2) جامع المسانید (۲۱۳/۳)"}],[1400,"§۱۴۰۱ ۔ حارث بن خزمہ(1)\n(خاء کے زبر اور زا سے) ابن عدی بن ابی غنم بن سالم بن عوف بن عمرو بن عوف بن خزرج انصاری، موسیٰ بن عقبہ نے شرکاء بدر میں ان کا ذکر کیا ایسا ہی ابو الاسود نے بحوالہ عروہ روایت کیا ہے۔ طبری لکھتے ہیں: وہ بدر اور باقی غزوات میں شریک ہوئے اور ۴۰ھ مدینہ میں سرسٹھ(۶۷) سال کی عمر میں فوت ہوئے۔ ابن مندہ نے ضعیف سند سے حارث بن خزیمہ سے نقل کیا ہے، فرمایا: نبی صلی اللہ علیہ وسلم سوموار کے روز مبعوث ہوئے۔ ابن ابی داؤد کتاب المصاحف میں ابن اسحاق کے طریق سے بحوالہ یحییٰ بن عباد وہ اپنے والد عباد بن عبد اللہ بن زبیر سے روایت کرتے ہیں کہ حارث بن خزیمہ سیدنا عمر رضی اللہ عنہ کے پاس یہ دو آیتیں “تمہیں میں سے تمہارے پاس ایک رسول آیا” (سورۃ التوبہ: ۱۲۸)(2) اختتام سورۃ تک لے کر آئے۔ طبرانی فرماتے ہیں: وہ کوہ پیما تھے اور بنی عبد الاشہل کے مخالف تھے۔ کنیت ابو بشیر تھی رسول اللہ صلی اللہ علیہ وسلم نے ان میں اور ایاس بن بکیر میں رشتہ اخوت قائم فرمایا۔","",{"fn":"(1) اسد الغابۃ (۸۷۴) الاستيعاب (۴۱۲)\n(2) مسند احمد (۱۹۹/۱) جامع المسانید (۲۱۵/۳)"}],[1401,"§۱۴۰۲ ۔ حارث بن حضرامہ الضبی یا الہلالی\nح میں تذکرہ ہوگا۔"],[1402,"§۱۴۰۳ ۔ (ز) حارث بن خفاف\nبن ایماء بن رحضہ غفاری۔ بخاری کی روایت سے پتہ چلتا ہے یہ صحابی ہیں۔ پھر انہوں نے اسلم کے طریق سے بحوالہ سیدنا عمر رضی اللہ عنہ روایت کیا ہے، فرمایا: میں نے اس کے باپ کو دیکھا ہے، مراد بنت خفاف ہے اور اس کا بھائی ایک عرصہ تک قلعہ کے پاس تھا۔ (حدیث) مؤرخین نے مخلد کے سوا خفاف کی کسی اولاد کا ذکر نہیں کیا۔ حارث اور مخلد مشہور تابعی ہیں۔ سیدنا عمر رضی اللہ عنہ کی گفتگو صرف حارث کے بارے میں تھی۔ واللہ اعلم"],[1403,"§۱۴۰۴ ۔ (ز) حارث بن راشد الناجی\nان کا اور ان کے بھائی مخباب بن راشد کا تذکرہ ابو الحسن مدائنی اور سعید بن عمر نے ان لوگوں میں کیا جو خلافت عثمانی میں فارس کے ضلعوں کے گورنر بنائے گئے۔ جن کی نبی صلی اللہ علیہ وسلم سے ملاقات ہوئی اور آپ صلی اللہ علیہ وسلم پر ایمان لائے۔ دو عثمانی تھے، رہے حارث تو انہوں نے زمین پر فساد برپا کیا تو سیدنا علی رضی اللہ عنہ نے ان کی جانب ایک دستہ بھیجا جنہوں نے بنی ناجیہ پر حملہ کیا، پھر لمبا قصہ ذکر کیا۔ اور فتوح میں ذکر کیا ہے کہ وہ قبیلہ عبد القیس کے امیر تھے۔ جب اہل عمان مرتد ہو گئے تھے۔ ان کے ساتھ صعصعہ بن صوحان تھے۔"],[1404,"§۱۴۰۵ ۔ حارث بن رافع(1)\nعبدان مروزی نے فرمایا: میں نے احمد بن سیار سے بحوالہ حارث بن رافع فرماتے سنا: وہ صحابی رسول تھے اور ان لوگوں میں سے ہیں جو اُحد میں شہید ہوئے اور ان کی کوئی حدیث مشہور نہیں۔ ابو موسیٰ(2) نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۷۸)\n(2) اسد الغابۃ (۳۷۳/۱)"}],[1405,"§۱۴۰۶ ۔ حارث بن ربعی\nابو قتادہ انصاری۔ کنیتوں میں ذکر ہوگا۔"],[1406,"§۱۴۰۷ ۔ حارث بن ربیع(1)\nبن زیادۃ بن سفیان بن عبد اللہ بن ناشب بن ہدم بن عوذ بن وطیعہ بن عبس عبسی (باء سے)۔ ابن شاہین نے ہشام بن کلبی کے طریق سے بحوالہ ابو الجنب عبسی نقل کیا ہے کہ بنی عبس کے نو آدمی وفد کی صورت میں نبی صلی اللہ علیہ وسلم کے پاس آکر مسلمان ہوئے۔ آپ صلی اللہ علیہ وسلم نے ان کے لئے دعائے خیر فرمائی۔ ان میں سے ایک حارث بن ربیع بن زیاد تھے(2)۔ میں کہتا ہوں: یہ بات پہلے بشر بن حارث کے حالات میں گزر چکی ہے۔ ان کے والد وہ شخص ہیں جن کا نعمان بن مندہ کے ساتھ ایک قصہ پیش آیا۔ ان کے اور بھی واقعات ہیں۔ زمانہ جاہلیت میں وہ عرب کے معزز افراد سے تعلق رکھتے تھے۔","",{"fn":"(1) اسد الغابۃ (۸۸۰)\n(2) اسد الغابۃ (۳۷۳/۱)"}],[1407,"§۱۴۰۸ ۔ حارث بن ابی ربیعہ(1)\nبن مغیرہ بن عبد اللہ بن عمر بن مخزوم مخزومی۔ ابن مندہ نے قاسم جرمی کے طریق سے بحوالہ ثوری، اسمعیل بن ابراہیم بن ابی ربیعہ سے انہوں نے اپنے والد سے روایت کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ان سے تیس ہزار (درہم کا اسلحہ) قرض لیا جب آپ مکہ تشریف لائے۔ (حدیث)(2) یہ حدیث ان کے بھائی عبداللہ بن ابی ربیعہ سے مشہور ہے۔ ایسا ہی ابن المبارک نے بحوالہ ثوری اس سند سے روایت کیا ہے۔ اور حاتم بن اسمعیل نے اسے بحوالہ اسمعیل بن ابراہیم بن عبداللہ بن ابی ربیعہ روایت کیا وہ اپنے والد سے وہ اپنے دادا سے نقل کرتے ہیں۔ اور ابن ابی عاصم نے ابن ابی فدیک کے طریق سے بحوالہ موسیٰ اور اسمعیل جو دونوں ابراہیم کے صاحبزادے ہیں، نقل کیا وہ اپنے والد عبداللہ بن ابی ربیعہ سے روایت کرتے ہیں: یہ بھی احتمال ہے کہ مذکورہ حدیث عبداللہ اور حارث دونوں سے مروی ہو۔ واللہ اعلم","",{"fn":"(1) (۸۸۱)\n(2) ابن ماجہ کتاب الصدقات باب حسن القضاء (۲۴۲۴) السنن الکبریٰ (۳۵۵/۵) الترغیب والترہیب (۵۶۶/۲)"}],[1408,"§۱۴۰۹ ۔ حارث بن زہیر(1)\nابن اقیش العکلی۔ ابن شاہین نے حارث بن یزید عکلی کے طریق سے بحوالہ قبیلہ کے شیوخ وہ حارث بن اقیش سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے لئے اور ان کی قوم کے لئے ایک تحریر لکھوائی جس کی عبارت یہ تھی: بسم اللہ الرحمن الرحیم یہ خط محمد نبی رسول اللہ کی طرف سے بنی اقیش کے لیے ہے۔ حمد و صلوٰۃ کے بعد۔۔۔۔ (حدیث)(2) ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن الاثیر کا گمان ہے کہ یہ وہی حارث بن اقیش ہیں جن کا ذکر پہلے ہوا ہے، جبکہ ایسا نہیں جیسا وہ سمجھے ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۸۲)\n(2) مسند احمد (۷۷/۵) کنز العمال (۲۴۶۳۰) جامع المسانید (۲۱۸/۳)"}],[1409,"§۱۴۱۰ ۔ حارث بن زیاد انصاری ساعدی(1)\nابن ابی شیبہ اور طبرانی(2) نے سعید بن المنذر کے طریق سے بحوالہ حمزہ بن ابی اسید حارث بن زید سے نقل کیا اور ان کا تعلق اصحاب بدر سے ہے۔ امام احمد(3) اور ابو داؤد نے فضائل انصار میں، ابن ابی خیثمہ، امام بخاری نے تاریخ میں اور بغوی وغیرہ عبدالرحمن بن غسیل کے طریق سے بحوالہ حمزہ بن ابی اسید سے روایت کیا۔ اور ان کے والد بدری صحابی تھے۔ وہ حارث بن زیاد ساعدی سے روایت کرتے ہیں کہ وہ نبی صلی اللہ علیہ وسلم کے پاس خندق کے روز آئے آپ لوگوں سے ہجرت پر بیعت لے رہے تھے۔ میں نے عرض کیا یا رسول اللہ صلی اللہ علیہ وسلم! ان سے بھی ہجرت پر بیعت لیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “یہ کون ہیں؟” میں نے عرض کیا: حوط بن یزید، میرے چچا زاد بھائی ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اے جماعت انصار! تم کسی کی طرف ہجرت نہیں کرو گے بلکہ لوگ (تم میں رسول اللہ صلی اللہ علیہ وسلم ہونے کی وجہ سے) تمہاری طرف ہجرت کریں گے۔” ابن قانع نے یہ سمجھ لیا کہ یہ براء بن عازب کے ماموں ہیں، جبکہ ان سے چوک ہوئی، وہ تو حارث بن عمرو ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۸۳) الاستيعاب (۴۱۵)\n(2) المعجم الکبیر (۲۹۹/۳)\n(3) مسند احمد (۴۲۹/۲)"}],[1410,"§۱۴۱۱ ۔ (ز) حارث بن زید بن ابی انیسہ عامری\nحارث بن یزید میں تذکرہ ہوگا۔"],[1411,"§۱۴۱۲ ۔ حارث بن زید(1)\nبن حارثہ بن معاویہ بن ثعلبہ بن جذیمہ بن عوف بن بکر بن عوف بن انمار کنیت ابو عتاب تھی، عبدان مروزی نے لکھا ہے کہ میں نے احمد بن یسار کو فرماتے سنا: وہ صحابی ہیں۔ ۲۱ھ میں ان کی شہادت ہوئی۔ ابو موسیٰ(2) نے ان کا ذکر اپنے استدراک میں کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۸۵)\n(2) اسد الغابۃ (۳۷۵/۱)"}],[1412,"§۱۴۱۳ ۔ حارث بن زید(1)\nبن عطاف بن ضبیعہ بن زید بن مالک بن عوف بن عمرو بن مالک بن اوس انصاری اوسی ابن مندہ اور ابو نعیم نے بحوالہ ابن اسحاق ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۸۶)"}],[1413,"§۱۴۱۴ ۔ (ز) حارث بن زید\nبن ہبیشہ حارث بن یزید میں ذکر ہوگا۔"],[1414,"§۱۴۱۵ ۔ حارث بن ابی سبرہ جعفی\nسبرہ بن ابی سبرہ کے بھائی۔ ان کے متعلق کہا جاتا ہے کہ سبرہ وہی حارث بن ابی سبرہ ہیں، اپنے دادا کی طرف منسوب کیے جاتے ہیں۔ ابو سبرہ کا نام یزید ہے جس کا بیان سبرہ میں ان شاء اللہ تعالیٰ آئے گا۔"],[1415,"§۱۴۱۶ ۔ حارث بن سراقہ(1)\nبن حارث انصاری نجاری۔ ابوالاسود نے بحوالہ عروہ شہدائے بدر میں ان کا ذکر کیا ہے۔ بقول بعض درست حارثہ بن سراقہ ہے جیسا کہ آئے گا۔ ہو سکتا ہے حارث نامی ان کا بھائی ہو۔","",{"fn":"(1) اسد الغابۃ (۸۹۰)"}],[1416,"§۱۴۱۷ ۔ حارث بن سعید(1)\nبن قیس بن حارث بن شیبان بن فاتک بن معاویہ اکرمین کندی۔ ابن شاہین نے اپنی سند سے بحوالہ ابن کلبی نبی صلی اللہ علیہ وسلم کے پاس آنے والوں میں ان کا ذکر کیا ہے۔ ایسا ہی طبری اور ابن ماکولا وغیرہ نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۹۲)"}],[1417,"§۱۴۱۸ ۔ حارث بن سفیان\nبن عبدالاسد مخزومی ابوسلمہ بن عبد الاسد کے بھتیجے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[1418,"§۱۴۱۹ ۔ حارث بن سفیان(1)\nبن معمر بن حبیب بن وہب بن حذافہ بن جمح قرشی سہمی۔ اپنے والد کے ہمراہ ہجرت حبشہ(2) سے آئے۔ ابن عبدالبر نے ان کے والد کے سوانح میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۹۳)\n(2) اسد الغابۃ (۳۷۷/۱)"}],[1419,"§۱۴۲۰ ۔ حارث بن سلمہ عجلانی(1)\nابن اسحاق(2) نے شرکاء اُحد میں ان کا ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: ان کی کوئی روایت مشہور نہیں۔","",{"fn":"(1) اسد الغابۃ (۸۹۴)\n(2) السیرۃ النبویۃ (۲۹۷/۳)"}],[1420,"§۱۴۲۱ ۔ حارث بن سُلیم(1)\nبن ثعلبہ بن کعب بن حارثہ۔ نسب انصار میں عدوی لکھتے ہیں: بدر میں شریک اور اُحد میں شہید ہوئے۔ ابن فتحون اور ابن الامین نے ان کا اپنے استدراک میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۹۵)"}],[1421,"§۱۴۲۲ ۔ حارث بن سہل(1)\nبن ابی صعصعہ انصاری نفیلی نے ان کا تذکرہ بحوالہ محمد بن سلمہ، ابن اسحاق(2) سے نقل کرتے ہوئے جنگ طائف کے شہداء میں کیا ہے۔ بقول بعض درست حارث کی جگہ حباب ہے، ممکن ہے دونوں بھائی ہوں۔","",{"fn":"(1) اسد الغابۃ (۸۹۶) الاستيعاب (۴۴۹)\n(2) السیرۃ النبویۃ (۱۰۲/۴)"}],[1422,"§۱۴۲۳ ۔ حارث بن سہم نضری\nحارث بن نصر سہمی میں ذکر ہوگا۔"],[1423,"§۱۴۲۴ ۔ (ز) حارث بن سواد انصاری(1)\nابوالاسود نے بحوالہ عروہ شرکاء بدر میں ان کا ذکر کیا اور طبرانی نے اسے نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۹۷)"}],[1424,"§۱۴۲۵ ۔ حارث بن سوید(1)\nبن الصامت انصاری اوسی، ان کے بھائی جلاس کا تذکرہ پہلے جیم میں ہو چکا ہے۔ ابن الاثیر فرماتے ہیں: اہل نقل کا اس پر اتفاق ہے کہ انہوں نے مجذر بن زیاد کو قتل کیا تھا جس کے بدلہ میں آپ صلی اللہ علیہ وسلم نے انہیں قتل کرنے کا حکم دیا۔ ابن الاثیر کے اعتماد میں تامل ہے۔ اس واسطے کہ عدوی، ابن کلبی اور قاسم بن سلام نے یہ یقین دہانی کی ہے کہ مذکورہ قصہ ان کے بھائی جلاس کے ساتھ پیش آیا ہے۔ لیکن مشہور یہ ہو گیا کہ حارث کے ساتھ یہ واقعہ پیش آیا ہے۔ عبدالرزاق نے اپنی تفسیر اور مسدد نے اپنی مسند میں بحوالہ جعفر بن سلیمان روایت کیا۔ باوردی اور ابن مندہ نے جعفر کے طریق سے بحوالہ حمید الاعرج مجاہد نقل کیا کہ حارث بن سوید مسلمان آدمی تھے بعد میں مرتد ہو کر کفار سے جا ملے جس پر یہ آیت نازل ہوئی: “کیسے ہو سکتا ہے کہ اللہ تعالیٰ ان لوگوں کو ہدایت دے جنہوں نے ایمان لانے کے بعد کفر اختیار کیا۔” (آل عمران: ۸۶) کسی شخص نے یہ آیت لے جا کر ان کے سامنے پڑھی، تو حارث بول اٹھے: “اللہ کی قسم! تم سچے ہو اور اللہ تعالیٰ تو سب سے بڑھ کر سچا ہے۔” پھر اسلام لے آئے۔(2) عبد بن حمید اور فریابی ابن ابی شیخ کے طریق سے بحوالہ مجاہد اس آیت کے متعلق روایت کرتے ہیں کہ بنی عمرو بن عوف کے ایک شخص کے بارے میں نازل ہوئی۔ اور بطریق سدی مروی ہے کہ حارث بن سوید کے بارے میں نازل ہوئی جو بنی عمرو بن عوف کے ایک فرد ہیں۔ نسائی، ابن حبان اور حاکم نے داؤد بن ابی ہند کے طریق سے بحوالہ عکرمہ، سیدنا ابن عباس رضی اللہ عنہما سے نقل کیا، ایک شخص تھا جو پہلے مسلمان تھا پھر مرتد ہو گیا پھر اسی جیسی حکایت ذکر کی۔ اور ان صاحب کا نام نہیں لیا۔ طبری نے اس روایت کو داؤد کے طریق سے موصول اور مرسل دونوں طرح روایت کیا ہے۔ احمد بن منیع کے ہاں علی بن عاصم سے بحوالہ داؤد ان الفاظ میں منقول ہے: ایک انصاری شخص مرتد ہو گیا۔ پھر موصول حدیث ذکر کی۔ ان کی مجذر کو قتل کرنے کی یہ وجہ بنی کہ مجذر نے جاہلیت میں ان کے والد سوید بن صامت کو قتل کیا تھا۔ تو حارث نے اُحد کے روز دھوکے سے قتل کر دیا اور بھاگ کھڑے ہوئے جس کے متعلق حسان(3) بن ثابت رضی اللہ عنہ فرماتے ہیں: “اے حارث! کیا تو اپنوں کی نیند کی غفلت و اونگھ میں تھا یا تو جبرائیل سے دھوکے میں تھا تیرا ناس ہو، یا جس وقت تو اے ابن زیاد! اسے دھوکے سے قتل کر رہا تھا زمین کی نامعلوم فضا میں تھا۔” ابن عبدالبر کے ہاں حارث بن سوید نے لکھا ہے، بقول بعض ابن مسلم مخزومی، مرتد ہو کر کفار سے مل گئے جس پر آیت: “کیسے ہو سکتا ہے کہ اللہ اس قوم کو ہدایت دے” (آل عمران: ۸۶) نازل ہوئی۔ میں کہتا ہوں: مشہور یہ ہے کہ وہ انصاری ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۹۸) الاستيعاب (۴۴۸)\n(2) اسد الغابۃ (۳۷۷/۱)\n(3) دیوانہ (۳۱۸)"}],[1425,"§۱۴۲۶ ۔ حارث بن شریح(1)\nبن ذؤیب بن ربیعہ بن حارث بن نمیر بن عامر نمیری۔ امام بخاری نے تاریخ میں لکھا ہے وہ بنی نمیر کے وفد میں نبی صلی اللہ علیہ وسلم کے پاس آئے۔ باوردی اور یعقوب بن سفیان نے یحییٰ بن راشد کے طریق سے بحوالہ دلہم بن دہشم، عائذ بن ربیعہ قریشی سے وہ قرہ بن دعموس سے وہ حارث بن شریح سے روایت کرتے ہیں کہ وہ نبی صلی اللہ علیہ وسلم کے پاس۔۔۔۔ پھر لمبی حدیث ذکر کی۔(2) یزید بن عمیر کے حالات میں ان کا ذکر آئے گا۔ قیس بن حفص بحوالہ دلہم بن دہشم، قرہ سے کہ وہ بھی وفد میں تھے پھر اسی مفہوم کی حدیث نقل کی۔ قاف میں آئے گی۔ حکیم ترمذی نے عائذ بن ربیعہ کے طریق سے نقل کیا، فرمایا: میں نے حارث بن شریح سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے آپ سے ماعون کے متعلق کیا فرمایا؟ انہوں نے کہا: “پتھر، لوہا اور پانی” ابن السکن(3) نے اسے طویل طور پر روایت کیا ہے۔ عمر بن شبہ کے ہاں شریح بن حارث لکھا ہے جو الٹ ہے۔","",{"fn":"(1) اسد الغابۃ (۹۰۰) الاستيعاب (۴۵۱)\n(2) اسد الغابۃ (۳۷۸/۱)\n(3) الدر المنثور (۴۰۰/۶)"}],[1426,"§۱۴۲۷ ۔ (ز) حارث بن شعیب العبدی\nنووی نے شرح مسلم میں تجرید کے مصنف کے حوالہ سے شرح مسلم میں لکھا ہے کہ وہ از جملہ وفد عبدالقیس سے تھے۔ یہ بات تامل کی محتاج ہے، حارث بن عبس عبدی کا ذکر آئے گا۔"],[1427,"§۱۴۲۸ ۔ حارث بن الصمہ(1)\n(صاد کے زیر اور میم کی تشدید سے) ابن عمرو بن عتیک بن عمرو بن عامر بن مالک بن النجار ابو جہیم کے والد۔ موسیٰ بن عقبہ اور ابن اسحاق(2) وغیرہ نے اہل بدر میں ان کا ذکر کیا ہے۔ لوگوں نے ذکر کیا کہ وہ مقام روحاء میں شکست سے دو چار ہوئے تو آپ نے انہیں واپس کر دیا اور ان کا حصہ مقرر کیا۔ وہی ان اشعار کے قائل ہیں: “اے رب! حارث بن صمہ اپنے اہم کاموں میں آگے بڑھا۔ وہ اُمت کے ہادی رسول کا حدی خواں ہے”(3) ابن اسحاق نے مغازی میں روایت کی ہے کہ وہ بئر معونہ کے روز شہید ہوئے۔ ایسا ہی ان کا ذکر ابوالاسود نے بحوالہ عروہ کیا ہے۔ ابن شاہین فرماتے ہیں نبی صلی اللہ علیہ وسلم نے ان کے اور صہیب بن سنان کے درمیان رشتہ اخوت قائم فرمایا۔ طبرانی نے عاصم بن عمرو کے طریق سے بحوالہ محمود بن لبید نقل کیا کہ حارث بن صمہ نے فرمایا: اُحد کے روز گھائی میں مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: عبدالرحمن بن عوف کس طرف ہے؟ میں نے عرض کیا: میں نے انہیں پہاڑ کی جانب دیکھا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس کی معیت میں فرشتے جنگ کر رہے ہیں۔ (حدیث) میں کہتا ہوں: جس نے یہ سمجھا کہ یہ ابو جہیم ہیں، جیسا کہ مسلم نے کنیتوں میں اور ان کے متبعین نے سمجھا ہے، تو اسے وہم ہوا ہے۔ درست یہ ہے کہ ابو جہیم ان کا بیٹا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۰۳) الاستيعاب (۴۲۳)\n(2) السیرۃ النبویۃ (۱۳۱/۳)\n(3) الابیات فی الاستيعاب (۲۹۳/۱) السیرۃ النبویۃ (۱۳۱/۳) المعجم الکبیر (۳۳۸۱/۳) (۳۳۸۳/۳)"}],[1428,"§۱۴۲۹ ۔ حارث بن ابی ضرار(1)\nبن حبیب بن حارث بن عائذ بن مالک بن المصطلق، ابو مالک خزاعی ثم مصطلقی۔ ام المومنین جویریہ رضی اللہ عنہا کے والد گرامی ابن اسحاق(2) نے مغازی میں ذکر کیا کہ وہ مدینہ آئے تو ان کے ساتھ اپنی بیٹی کو چھڑانے کا فدیہ تھا۔ جبکہ وہ قید ہو کر نبی صلی اللہ علیہ وسلم سے منسوب ہو چکی تھیں۔ فرماتے ہیں: جب وہ وادی عقیق میں پہنچے تو اپنے اونٹوں پر نظر پڑی جن میں سے دو اونٹ انہیں بھلے لگے اور انہیں گھائی میں غائب کر دیا۔ بقیہ اونٹ نبی صلی اللہ علیہ وسلم کے پاس لا کر کہنے لگے: محمد (صلی اللہ علیہ وسلم)! یہ میری بیٹی کا فدیہ ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: دو اونٹ کہاں ہیں جنہیں تم نے وادی عقیق میں غائب کر دیا ہے؟ تو حارث بولے: میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی عبادت کے لائق نہیں اور آپ صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ اللہ کی قسم! ان کے بارے میں اللہ کے سوا کسی کو علم نہیں۔ فرماتے ہیں: جب وہ مسلمان ہوئے تو ان کے دونوں بیٹے اور ساتھ آئے ہوئے ان کی قوم کے لوگ بھی اسلام لے آئے۔ یہ بات ابن عائذ نے مغازی میں بحوالہ محمد بن شعیب، عبداللہ بن زیاد سے منقطع نقل کیا ہے۔ امام احمد، طبرانی، مطین، ابن السکن اور ابن مردویہ نے عیسیٰ بن دینار موذن کے طریق سے وہ اپنے والد سے روایت کرتے ہیں کہ انہوں نے حارث بن ابی ضرار کو فرماتے سنا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے مجھے اسلام کی دعوت دی تو میں حلقہ اسلام میں داخل ہو گیا، پھر لمبی حدیث ذکر کی جس میں ولید بن عقبہ کا قصہ ہے۔ جب وہ ان کے پاس زکوۃ وصول کرنے آئے۔ اور اس آیت: “اے ایمان والو! جب تمہارے پاس کوئی فاسق شخص کوئی اطلاع لائے تو اس کی چھان بین کر لیا کرو”۔ (الحجرات: ۶) کا شان نزول ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۹۰۵) الاستيعاب (۴۲۴)\n(2) السیرۃ النبویۃ (۲۳۲/۳)"}],[1429,"§۱۴۳۰ ۔ (ز) حارث بن طفیل\nبن عمرو الدوسی۔ ان کے والد کا تذکرہ ہوگا ابوالفرج اصبہانی نے ذکر کیا طفیل اور ان کے گھرانے کے افراد اسلام لے آئے۔ طفیل شاعر اور شہسوار تھے۔ ان کے اشعار بھی درج کیے جو انہوں نے قبیلہ دوس اور بنی حارث بن یشکر کے مابین جنگ کے موقع پر زمانہ جاہلیت میں کہے تھے۔"],[1430,"§۱۴۳۱ ۔ حارث بن ظالم\nبقول بعض ابو الاعور بن حارث یہی ہیں۔"],[1431,"§۱۴۳۲ ۔ حارث بن عبد اللہ(1)\nبن اوس ثقفی طائف کے رہائشی تھے۔ اپنے دادا کی طرف نسبت کیے جاتے ہیں۔ بقول بعض (نہیں بلکہ) دو شخص ہیں۔ ان کی حدیث ابو داؤد، نسائی(2) اور ترمذی(3) نے کتاب الحج میں روایت کی جس کی سند صحیح ہے۔ انہیں سیدنا عمر رضی اللہ عنہ سے بھی روایت حاصل ہے جبکہ ان سے عمرو بن اوس اور ولید بن عبد الرحمن جرشی روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۹۱۰) الاستيعاب (۴۲۷)\n(2) ابوداؤد کتاب المناسک باب الحائض تخرج بعد الافاضۃ (۲۰۰۴)\n(3) ترمذی کتاب الحج باب من حج او اعتمر فلیکن آخر عہدہ بالبیت (۹۴۶)"}],[1432,"§۱۴۳۳ ۔ (ز) حارث بن عبد اللہ الجہنی(1)\nان کی حدیث ابن سعد(2) وغیرہ نے روایت کی، جو سعید بن خالد جہنی کے طریق سے مروی ہے۔ فرمایا: مجھے ضحاک بن قیس نے حارث بن عبد اللہ جہنی کے پاس بھیجا۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے یمن بھیجا۔ اگر مجھے گمان بھی ہوتا کہ آپ فوت ہو جائیں گے میں آپ سے جدا نہ ہوتا۔ فرماتے ہیں: میں چلا گیا، میرے پاس ایک یہودی عالم آ کر کہنے لگا: محمد (صلی اللہ علیہ وسلم) فوت ہو گئے۔ فرماتے ہیں: میری حالت یہ ہو رہی تھی کہ میں قتل کرنے والا تھا کہ اتنے میں میرے پاس اس بارے میں سیدنا ابو بکر رضی اللہ عنہ کا خط آ گیا۔ بعد میں میں نے اس عالم کو بلایا کہ تمہیں کیسے پتہ چلا؟ اس نے کہا: ہماری کتاب میں آپ کا ذکر ہے۔ میں نے کہا: اب ان کے بعد کیا ہوگا؟ وہ کہنے لگے: پینتیس(۳۵) سال تک تم میں (خلافت کی) چکی چلتی رہے گی۔ اس کی سند ضعیف ہے۔ ابو موسیٰ نے یہ دعویٰ کیا ہے کہ درست نام جریر بن عبد اللہ بجلی ہے۔ جبکہ اس میں تامل ہے اس لیے کہ دونوں قصے مختلف ہیں۔ چنانچہ سیدنا جریر کا قصہ بخاری میں آتا ہے جس میں یہ سیاق نہیں۔ اور حارث کا یہ قصہ ہے جس کی سند میں حماد بن عمرو متروک راوی ہے۔","",{"fn":"(1) اسد الغابۃ (۹۱۱)\n(2) الطبقات الکبریٰ (۱۸/۵)"}],[1433,"§۱۴۳۴ ۔ حارث بن عبد اللہ(1)\nبن سائب بن مطلب بن اسد بن عبد العزیٰ بن قصی قرشی اسدی۔ ابن شاہین نے ابن ابی داؤد سے صحابہ میں ان کا ذکر کیا ہے۔ ابن ابی داؤد کے سیاق سے پتہ چلتا ہے کہ ان کی کنیت ابوالحارث ہے۔ چنانچہ ان کی جو حدیث انہوں نے ابو معشر کے طریق سے بحوالہ سعید المقبری روایت کی ہے وہ ابو حارث سے مروی ہے۔ پھر وہ حدیث ذکر کی۔(2)","",{"fn":"(1) اسد الغابۃ (۹۱۳)\n(2) المصنف لعبد الرزاق (۱۹۸۹۳) المصنف لابن ابی شیبہ (۱۶۷/۱۲) کنز العمال (۳۳۸۴۶)"}],[1434,"§۱۴۳۵ ۔ حارث بن عبد اللہ(1)\nبن سعد بن عمرو بن قیس بن امرئ القیس بن مالک الاغر بن ثعلبہ بن کعب بن خزرج بن حارث بن خزرج انصاری۔ ابو عمر(2) فرماتے ہیں: اُحد کے روز شہید ہوئے۔ بقول بعض ان کا نام حارث بن ثابت بن عبد اللہ بن سعد ہے جس سے یہ احتمال ہوتا ہے کہ وہ ان کے چچا ہوں۔","",{"fn":"(1) اسد الغابۃ (۹۱۴) الاستيعاب (۴۲۵)\n(2) الاستيعاب (۳۵۷/۱)"}],[1435,"§۱۴۳۶ ۔ (ز) حارث بن عبد اللہ\nانہیں ابن عبید ازدی ابو علکتہ بھی کہا جاتا ہے۔ کنیتوں میں ذکر ہوگا۔"],[1436,"§۱۴۳۷ ۔ حارث بن عبد اللہ(1)\nبن کعب بن عمرو بن عوف بن مبذول انصاری اوسی۔ عدوی فرماتے ہیں: حدیبیہ اور بعد کے غزوات میں شریک تھے۔ حرہ کے واقعہ میں شہید ہوئے۔ ابن فتحون وغیرہ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ اور ذہبی نے یہ بات ابو عمر کی جانب منسوب کی ہے۔ جس سے یہ مغالطہ ہوتا ہے کہ انہوں نے ان کا عنوان قائم کیا ہے حالانکہ واقعہ یہ نہیں۔ ابن الاثیر(2) نے تو جب ان کا استدراک میں ذکر کیا یہ کہا ہے: ابو عمر نے انہی کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۱۶)\n(2) اسد الغابۃ (۳۸۳/۱)"}],[1437,"§۱۴۳۸ ۔ حارث بن عبد اللہ(1)\nبن وہب دوسی، ابن مندہ فرماتے ہیں: امام بخاری نے ان کا صحابہ میں ذکر کیا ہے۔ پھر ایک ضعیف سند سے روایت کیا جو مغراء بن عیاض بن حارث بن عبد اللہ بن وہب دوسی سے مروی ہے۔ حارث اپنے والد کے ہمراہ نبی صلی اللہ علیہ وسلم کے پاس ان ستر آدمیوں سمیت آئے جو دوس سے چلے تھے۔ حارث نے کچھ ایام نبی علیہ السلام کے پاس قیام کیا جبکہ ان کے والد سرداروں کی طرف لوٹ آئے ان کے بہت سے پھلدار درخت تھے۔ ان کے والد عبداللہ بن وہب کے حالات میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابۃ (۹۱۷) الاستيعاب (۴۲۶)"}],[1438,"§۱۴۳۹ ۔ حارث بن عبد شمس خثعمی(1)\nامام بخاری(2) اور ابن حبان نے صحابہ میں ان کا تذکرہ کیا ہے۔ ابن مندہ فرماتے ہیں: ان کا شمار اہل شام میں ہے۔ پھر ایک غریب سند سے بحوالہ حمیری بن حارث بن عبد شمس وہ اپنے والد سے روایت کرتے ہیں کہ وہ نبی علیہ السلام کی طرف نکلے۔ آپ صلی اللہ علیہ وسلم نے ان کے لئے ایک تحریر لکھوائی۔ اور ان کے لئے اور ان کے ساتھیوں کے لئے فلاں جگہ سے فلاں جگہ تک کا علاقہ (استعمال کے لیے) مباح قرار دیا۔ (حدیث)","",{"fn":"(1) اسد الغابۃ (۹۱۹)\n(2) التاریخ الکبیر (۲۶۱/۲)"}],[1439,"§۱۴۴۰ ۔ حارث بن عبد العزیٰ(1)\nبن برفاعہ بن ملان بن ناصرہ بن قصبہ بن نصر بن سعد بن بکر بن ہوازن سعدی، حلیمہ سعدیہ نبی صلی اللہ علیہ وسلم کی رضاعی والدہ کے خاوند۔ ابن سعد فرماتے ہیں: ان کی کنیت ابو ذویب ہے۔ ابن اسحاق نے سیرۃ میں ذکر کیا: مجھے میرے والد نے بنی سعد کے رجال کے حوالہ سے بتایا، وہ کہتے ہیں: نبی صلی اللہ علیہ وسلم کے رضاعی والد الحارث مکہ میں نبی صلی اللہ علیہ وسلم کے پاس آئے۔ لوگ ان سے کہنے لگے: تم نے سنا ہے تمہارا (رضاعی) بیٹا کیا کہتا ہے؟ کہ موت کے بعد لوگوں کو اٹھایا جائے گا۔ وہ کہنے لگے: بیٹا! یہ تم کیا بات کہتے ہو؟ آپ نے فرمایا: “ہاں! جب قیامت کے روز ایسا ہوا تو میں آپ کا ہاتھ پکڑ کر اس دن آپ کو یہ بات یاد دلاؤں گا”۔(2) بعد میں حارث اسلام لے آئے اور پختہ اسلام شخص بن گئے۔ فرمایا کرتے تھے: “اگر میرے بیٹے نے میرا ہاتھ پکڑ لیا تو مجھے جنت پہنچا کر ہی چھوڑے گا”۔ میں کہتا ہوں: ابن سعد کے ہاں دوسری حدیث ہے جو مرسل ہے کہ یہ واقعہ حارث کے بیٹے کے ساتھ پیش آیا۔ چنانچہ یحییٰ بن ابی کثیر کے طریق سے بحوالہ اسحاق بن عبداللہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے ایک رضاعی بھائی تھے۔ انہوں نے نبوت کے بعد نبی علیہ السلام سے کہا: آپ کا کیا خیال ہے کہ بعثت ہوگی؟ آپ نے فرمایا: “اس ذات کی قسم! جس کے قبضہ قدرت میں میری جان ہے۔ قیامت کے دن میں ضرور تمہارا ہاتھ تھام کر تمہیں یاد دلاؤں گا”۔ فرماتے ہیں: بعد میں جب وہ نبی علیہ السلام پر ایمان لے آئے تو بیٹھ کر رویا کرتے تھے، فرماتے: مجھے پوری اُمید ہے کہ نبی علیہ السلام قیامت کے روز میرا ہاتھ پکڑیں گے۔ یہ بھی احتمال ہے کہ یہ واقعہ باپ بیٹے دونوں کے ساتھ پیش آیا ہو۔ بعض نے ان کا نام عبد اللہ بتایا اور انہیں صحابہ میں ذکر کیا ہے۔ یہی نام ابن سعد نے ذکر کیا جب اولاد حلیمہ کا ذکر کیا، عنقریب عورتوں کے ناموں میں حرف شین میں شیماء کے ذیل میں تذکرہ ہوگا۔ ابو داؤد(3) نے عمر بن حارث کے طریق سے بحوالہ عمر بن سائب نقل کیا کہ انہیں یہ روایت پہنچی کہ رسول اللہ صلی اللہ علیہ وسلم تشریف فرما تھے کہ اتنے میں ان کے رضاعی والد تشریف لے آئے۔ آپ نے اپنی چادر کا کچھ حصہ ان کے لئے بچھایا جس پر وہ بیٹھ گئے۔ (حدیث) ابن اسحاق نے ذکر کیا کہ انہیں یہ بات پہنچی ہے کہ حارث نبی علیہ السلام کی وفات کے بعد مسلمان ہوئے۔ واللہ اعلم بقول بعض: وہ نبی علیہ السلام کو گود لینے والے ابو کبشہ ہیں جن کا ذکر کنیتوں میں آئے گا۔","",{"fn":"(1) اسد الغابۃ (۹۲۰) جامع المسانید (۲۲۸/۳)\n(2) الطبقات الکبریٰ (۷۱/۱)\n(3) ابوداؤد کتاب الادب باب فی بر الوالدین (۵۱۴۵)"}],[1440,"§۱۴۴۱ ۔ حارث بن عبد قیس(1)\nبن لقیط بن عامر بن امیہ بن النظرب بن حارث بن قہر قرشی فہری۔ انہیں حارث بن قیس بھی کہا جاتا ہے۔ ابن اسحاق اور ابن داب نے مہاجرین حبشہ میں ان کا تذکرہ کیا ہے۔ بلاذری نے کہا: واقدی نے ان لوگوں میں ان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۹۲۱) الاستيعاب (۴۴۰)"}],[1441,"§۱۴۴۲ ۔ حارث بن عبد کلال(1)\nبن نصر بن سہل بن عریب بن عبد کلال بن عبید بن فہر بن زید المیری (یمن کے ایک رئیس) نبی علیہ السلام نے ان کی طرف خط بھیجا جیسا کہ ان کے بھائی شرحبیل وغیرہ کے سوانح میں آئے گا۔ انساب میں ہمدانی نے لکھا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے حارث اور ان کے بھائی کو خط لکھا اور اپنے قاصد کو حکم دیا کہ ان کے سامنے سورۃ “لم یکن” پڑھنا۔ حارث آپ کے پاس آ کر مسلمان ہو گئے آپ صلی اللہ علیہ وسلم نے ان سے معانقہ کیا اور ان کی خاطر اپنی چادر بچھائی۔ ان کی آمد سے پہلے آپ صلی اللہ علیہ وسلم نے فرمایا: “اس راستے (یمن کی طرف اشارہ تھا) سے تمہارے پاس معزز ددھیال اور ننھیال والا ایک شخص آئے گا۔ جس کے رخسار گورے مائل بزردی ہوں گے۔ تو وہ ایسے ہی تھے۔ زیادہ روایات سے پتہ چلتا ہے کہ انہوں نے اپنے اسلام لانے کا پیام بھیجا تھا اور یمن میں مقیم ہو گئے تھے۔ ابن اسحاق تبوک سے نبی صلی اللہ علیہ وسلم کی واپسی کے موقع پر حمیر کے بڑے بڑے بادشاہوں نے اپنے اسلام لانے کی اطلاع بھیجی۔ ان میں سے حارث بن عبد کلال بھی تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کی طرف مہاجر بن ابی امیہ کو بھیجا تھا تو وہ (ان کی تبلیغ پر) اسلام لے آئے اور آپ صلی اللہ علیہ وسلم کی خدمت میں یہ اشعار لکھ کر بھیجے: “آپ صلی اللہ علیہ وسلم کا دین برحق ہے جس میں پاکیزگی ہے اور جس کا آپ حکم دیتے ہیں”۔ یوں ہی دار قطنی نے نافع کے طریق سے بحوالہ ابن عمر رضی اللہ عنہما انہیں روایت کیا ہے۔ اسی طرح ابوالحسن مدائنی نے “رسل النبی صلی اللہ علیہ وسلم” میں (نبی صلی اللہ علیہ وسلم کے قاصدین) نامی کتاب میں اس کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۲۲) مسند احمد (۳۶۰/۴) الطبقات الکبریٰ (۶۱/۶) السیرۃ النبویۃ (۱۷۹/۴)"}],[1442,"§۱۴۴۳ ۔ حارث بن عبد مناف(1)\nعبدان محمد بن عمرو کے طریق سے بحوالہ شریک بن ابی عمیر، حارث بن عبد مناف سے روایت کرتے ہیں، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم سے پھوپھی اور خالہ کی میراث کے متعلق پوچھا گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “مجھے جبرائیل علیہ السلام نے بتایا کہ ان دونوں کا میراث (یعنی بھانجے بھانجی اور بھتیجا بھتیجی کے مال) میں کوئی حق نہیں۔” اس روایت کو حاکم(2) نے مستدرک میں محمد بن عمر کے طریق سے نقل کیا ہے۔ لیکن مستدرک کے نسخہ میں صرف حارث بن عبد لکھا ہے۔ واللہ اعلم۔ ذہبی(3) لکھتے ہیں: اگر یہ بات صحیح ہے تو یہ روایت مرسل ہے۔","",{"fn":"(1) اسد الغابۃ (۹۲۳)\n(2) المستدرک (۳۴۲/۴)\n(3) تجرید (۳۰)"}],[1443,"§۱۴۴۴ ۔ حارث بن عبید\nبن رزاح بن کعب انصاری ظفری۔ ابو عمر: انہیں اور ان کے بیٹے نصر بن حارث کو شرف صحابیت حاصل ہے۔"],[1444,"§۱۴۴۵ ۔ (ز) حارث بن عبید ازدی\nحارث بن عبد اللہ میں ذکر ہوا ہے۔"],[1445,"§۱۴۴۶ ۔ (ز) حارث بن عبیدہ(1)\nبن حارث بن عبد المطلب بن عبد مناف قرشی مطلبی، بلاذری اور دیگر نسب دانوں نے انہیں عبیدہ کی اولاد میں ذکر کیا ہے۔ عبیدہ تو بدر میں شہید ہو چکے تھے اس لئے ان کے یہ بیٹے صحابی ہوں گے۔ شاید نبی صلی اللہ علیہ وسلم کی حیات میں ہی ان کی وفات ہوئی ہو۔","",{"fn":"(1) اسد الغابۃ (۹۲۴)"}],[1446,"§۱۴۴۷ ۔ حارث بن عتیک(1)\nبن قیس بن ہیشہ بن حارث بن امیہ بن معاویہ بن مالک بن عمرو بن عوف انصاری جبر (جو تیک بن عتیک کے والد ہیں) ان کے بھائی۔ عدوی: شرکاء بدر میں۔ ابن شاہین: اپنے رجال سے ان کا ذکر تو کیا لیکن ان کے والد کا نام عقیق لکھا ہے کہ وہ ان کے والد اور چچا بدر میں شریک ہوئے تھے۔ ابن سعد بحوالہ واقدی بدری صحابہ میں اور ابن عمارہ نے یوں ذکر کیا ہے: حارث بن قیس بن ہیشہ بدر میں شریک ہوئے۔","",{"fn":"(1) اسد الغابۃ (۹۲۶)"}],[1447,"§۱۴۴۸ ۔ حارث بن عتیک(1)\nبن نعمان بن عمرو بن علی بن عمرو بن مبذول انصاری بخاری، کنیت ابو احزم تھی، احد اور دیگر غزوات میں شریک ہوئے۔ بقول واقدی جسر ابی عبیدہ میں شہادت پائی۔","",{"fn":"(1) اسد الغابۃ (۹۲۷) استیعاب (۴۳۸)"}],[1448,"§۱۴۴۹ ۔ حارث بن عدی(1)\nبن خرشہ بن امیہ بن عامر بن حکیمہ انصاری خطمی۔ اُحد میں شہید ہوئے۔ ابو عمر(2) نے ابن کلبی کے اتباع میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۲۹) استیعاب (۴۳۶)\n(2) استیعاب (۳۶۱/۱)"}],[1449,"§۱۴۵۰ ۔ حارث بن عدی\nبن مالک بن حزام بن خدیج بن معاویہ انصاری معاوی۔ عدوی: اُحد میں شریک ہوئے۔ موسیٰ بن عقبہ: جسر ابی عبید میں ۱۵ھ میں شہید ہوئے۔"],[1450,"§۱۴۵۱ ۔ حارث بن عرفجہ(1)\nبن حارث بن مالک بن کعب انصاری اوسی۔ موسیٰ بن عقبہ وغیرہ: بدری صحابہ ہیں۔ ابو عمر کا گمان ہے کہ: “ابن اسحاق نے ان کا ذکر چھوڑ دیا ہے”۔ جبکہ ان کا گمان غلط ہے۔ ابن فتحون اس پر متنبہ کر چکے ہیں کہ ابن اسحاق نے حارث بن عرفجہ کو شرکاء بدر میں ذکر کیا ہے۔ ابن ہشام نے ان کا یوں نسب بیان کیا ہے: ابن کعب بن النجار بن کعب۔","",{"fn":"(1) اسد الغابۃ (۹۳۰) استیعاب (۴۴۱)"}],[1451,"§۱۴۵۲ ۔ حارث بن عفیف الکندی\nابن مندہ: امام بخاری نے صحابہ میں ان کا تذکرہ کیا ہے۔ یہ بھی احتمال ہے کہ وہ ابن غطیف ہوں جن کا تذکرہ آ رہا ہے۔"],[1452,"§۱۴۵۳ ۔ حارث بن عقبہ(1)\nبن قابوس المزنی۔ مغازی میں واقدی ذکر کرتے ہیں کہ وہ اور ان کے چچا وہب بن قابوس اپنی بکریاں لے کر مدینہ پہنچے تو مدینہ کو خالی پایا۔ وہاں سے سیدھے اُحد پہنچے اور اسلام لانے کے بعد مشرکین سے جنگ میں شریک ہو گئے۔ بالآخر دونوں شہید ہو گئے۔ سیدنا عمر رضی اللہ عنہ فرمایا کرتے تھے: “مجھے ان دو مزنیوں کی موت پہ رشک آتا ہے۔”","",{"fn":"(1) اسد الغابۃ (۹۳۲) استیعاب (۹۳۷)"}],[1453,"§۱۴۵۴ ۔ حارث بن عمرو\nبن حرام بن عمرو بن زید بن نعمان بن مالک بن ثعلبہ بن کعب بن خزرج بن حارث بن خزرج انصاری خزرجی۔ ابن سعد(1) نے ذکر کیا کہ وہ اور ان کے بھائی اُحد میں شریک ہوئے۔ ابن کلبی کا بیان ہے کہ وہ دونوں جنگ صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ تھے۔ اور ابن سعد کا قول ہے کہ کوفہ شہر میں سعد کی اولاد ہے۔ اور عمرو بن حرام جو جابر بن عبد اللہ بن حرام کے دادا ہیں۔ ان کے والد نہیں بلکہ وہ دوسری شخصیت ہیں وہ تو ابن حرام بن ثعلبہ بن حرام بن کعب ہیں۔","",{"fn":"(1) الطبقات الکبریٰ (۴۲/۵)"}],[1454,"§۱۴۵۵ ۔ حارث بن عمرو بن غزیہ\nبن ثعلبہ بن خنساء بن مبذول بن عمرو بن غنم بن مازن بن تیم اللہ بن ثعلبہ بن عمرو بن خزرج انصاری خزرجی۔ ابن السکن نے صحابہ میں ان کا ذکر کیا ہے۔ یہ حجاج، سعید اور عبدالرحمن کے بھائی ہیں جن کا ذکر آ رہا ہے۔ ابو عمر فرماتے ہیں: میرے خیال میں یہ حارث بن غزیہ ہیں یعنی جن کا ذکر آ رہا ہے۔ فرماتے ہیں: بظاہر وہ اور ہیں۔ ابن قانع نے انہی حارث بن عمرو بن غزیہ کا عنوان قائم کر کے حارث کی ایک حدیث نقل کی ہے۔ یوں دونوں کو ایک شخصیت قرار دیا ہے۔"],[1455,"§۱۴۵۶ ۔ حارث بن عمرو\nبن مؤمل بن حبیب بن تمیم بن عبداللہ بن قرط بن رزاح بن عدی بن کعب بن لوی بن غالب قرشی عدوی، ابو عمر نے لکھا ہے: یہ ان ستر لوگوں میں سے ایک ہیں جنہوں نے خیبر کے سال مدینہ کی طرف ہجرت کی تھی۔"],[1456,"§۱۴۵۷ ۔ (ز) حارث بن عمرو الطائی\nابن حبان نے صحابہ میں ان کا ذکر کر کے لکھا ہے کہ انہیں شرف صحابیت حاصل ہے۔ اہل شام میں شمار ہوتے ہیں اور ارمیڈیا کی جنگ لڑتے ہوئے شہید ہوئے۔ وہ لشکر کے سپہ سالار بھی تھے۔"],[1457,"§۱۴۵۸ ۔ حارث بن عمرو انصاری(1)\nبراء بن عازب کے چچا بقول بعض ان کے ماموں ہیں۔ امام احمد(2) نے اشعث بن سوار کے طریق سے بحوالہ عدی بن ثابت، براء سے روایت نقل کی ہے، فرمایا: حارث بن عمرو گزرے۔ رسول اللہ صلی اللہ علیہ وسلم نے انہیں ایک جھنڈا بنا کر دیا تھا۔ تو میں نے پوچھا: چچا جان! کہاں کا ارادہ ہے؟ فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے ایسے شخص کی گردن اتارنے بھیجا ہے جس نے اپنے والد کی بیوی سے شادی کی ہے۔ ابن السکن نے اسی سند سے نقل کر کے لکھا ہے: میرے چچا حارث بن عمرو میرے پاس سے گزرے۔ عبدالرزاق نے اس روایت کو اپنے طریق سے نقل کیا تو لکھا: “میری اپنے چچا سے ملاقات ہوئی۔” اس میں ان کا نام نہیں لیا۔ اور دوسری سند سے روایت کیا کہ اشعث سے مروی ہے، فرمایا: میں اپنے ماموں سے ملا۔ ایسا ہی ابن ماجہ نے نقل کیا ہے۔ ایک جماعت نے یہ روایت عدی بن ثابت سے نقل کی ہے لیکن اس کی سند میں ان سے اوپر اختلاف ہے۔ بعض نے ان کے حوالہ سے کہا: میں نے براء سے سنا، بعض نے کہا: ان سے وہ یزید بن براء سے وہ اپنے والد سے روایت کرتے ہیں۔ یہ روایت ابو مریم عبدالغفار بن قیس بن عدی بن قیس سے بحوالہ یزید وہ اپنے والد سے فرمایا: میں اپنے ماموں سے ملا، ان کے پاس ایک جھنڈا تھا۔ میں نے عرض کیا: کہاں کا ارادہ ہے؟ پھر حدیث ذکر کی اور ان کا نام نہیں لیا۔","",{"fn":"(1) اسد الغابۃ (۹۳۴) استیعاب (۴۳۱)\n(2) مسند احمد (۲۹۰/۴)"}],[1458,"§۱۴۵۹ ۔ حارث بن عمرو بن ثعلبہ(1)\nبقول بعض حارث بن عمرو بن حارث بن ایاس بن عمرو بن سہم بن نصلہ بن غنم بن ثعلبہ بن معن بن مالک بن اعصر بابلی ثم سہمی۔ ابو منقبہ (میم پر زبر، سین ساکن، قاف پر زبر اور پھر باء ہے) جیسا کہ میں نے مغلطائی کے قلم سے لکھا، پڑھا ہے کہ “کمال” کے مصنف نے یہ نام غلط لکھا ہے اور مزی نے بھی ان کا اتباع کیا ہے۔ چنانچہ انہوں نے لکھا ہے: ابوسفینہ بصرہ میں فروکش ہوئے۔ انہوں نے ایک حدیث روایت کی جو امام بخاری رحمہ اللہ نے الادب المفرد میں اور ابوداؤد، نسائی وغیرہ نے نقل کی اور حاکم نے اسے صحیح قرار دیا۔ بعض نے اسے زرارہ بن کریم بن حارث بن عمرو کے طریق سے طویل ذکر کیا ہے۔ فرمایا: “میں رسول اللہ صلی اللہ علیہ وسلم کے پاس منیٰ یا عرفات میں آیا، لوگوں نے آپ صلی اللہ علیہ وسلم کے گرد گھیرا بنا رکھا تھا۔”۔ (حدیث) اور بیٹی(2) بن زرارہ کے طریق سے ہے مجھے میرے والد نے بحوالہ اپنے دادا حارث بتایا، اور بغوی نے یہ حدیث یحییٰ بن حارث کے طریق سے نقل کی، فرمایا: مجھے میرے والد نے اپنے دادا حارث کے حوالہ سے بتایا انہوں نے دور جاہلیت اور اسلام پایا تھا۔ پھر استغفار، بتوں کے لیے سر کی چوٹی اور ان کے نام ذبح کی جانے والی بکری کے متعلق کوئی حدیث نقل کی۔ ان سے ان کا بیٹا عبداللہ بن حارث اور پوتا زرارہ بن کریم بن حارث روایت کرتا ہے۔ حرف کاف میں کریم کے سوانح میں ان کا کچھ تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابۃ (۹۳۵) استیعاب (۴۲۹)\n(2) ابوداؤد کتاب المناسک باب من المواقیت حدیث (۱۷۴۲) المستدرک (۳۴۲/۴)"}],[1459,"§۱۴۶۰ ۔ (ز) حارث بن عمرو اسدی\nابو مکعت، کنیت سے شہرت رکھتے ہیں۔ ابن ماکولا نے مرزبانی کے اتباع میں ان کا یہی نام لیا ہے۔ جبکہ ابن قانع اور ابن مندہ وغیرہ نے ان کا نام عرفطہ بن نصلہ لیا ہے۔ یہی زیادہ مشہور ہے۔ ان شاء اللہ تعالیٰ کنتیوں میں ان کا تذکرہ آئے گا۔"],[1460,"§۱۴۶۱ ۔ حارث بن عمیر ازدی(1)\nثم الھی لام کے زیر اور ھا کے سکون سے۔ واقد نے عمرو بن حکم سے نقل کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اپنا خط دے کر بصریٰ کے بادشاہ کی طرف بھیجا تھا۔ جب یہ موتہ فروکش ہوئے تو شرحبیل بن عمرو غسانی راستے میں مل گیا، اس نے انہیں گرفتار کر لیا اور ان کی گردن اتار دی۔ اس کے علاوہ نبی صلی اللہ علیہ وسلم کا کوئی قاصد قتل نہیں ہوا۔ جب رسول اللہ صلی اللہ علیہ وسلم کو اس کی اطلاع ملی تو آپ صلی اللہ علیہ وسلم نے موتہ(2) ایک مہم روانہ فرمائی۔ ابن شاہین نے محمد بن یزید کے طریق سے بحوالہ اپنے رجال اس واقعہ کے بغیر ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۳۹) استیعاب (۱۹۰/۱)\n(2) الطبقات الکبریٰ (۲۵۵/۴)"}],[1461,"§۱۴۶۲ ۔ حارث بن عوف(1)\nبن ابی حارثہ مزنی، جاہلیت کے مشہور شہسوار۔ ابو عبید نے کتاب الدیباج میں ذکر کیا ہے جس سے پتہ چلتا ہے کہ وہ اسلام لے آئے تھے۔ ایسا ہی دوسرے لوگوں نے نقل کیا ہے۔ ابو عبید لکھتے ہیں: عرب کی تین جنگیں زیادہ لمبے عرصے کی تھیں۔ قیلہ کے دونوں بیٹوں اوس اور خزرج کی لڑائی، حراس اور غبراء کی جنگ جو بنی عبس اور فزارہ کے درمیان ہوئی۔ اور وائل کے دو بیٹوں بکر اور تغلب کی جنگ، پھر دو اٹھانے والوں نے ان کے خون اٹھائے۔ وہ خارجہ بن سنان اور حارث بن عوف تھے۔ انہی ایام میں اللہ تعالیٰ نے نبی صلی اللہ علیہ وسلم کو مبعوث فرمایا، لیکن ابھی حارث بن عوف پر ان کے خون کا کچھ حصہ دینا باقی تھا جسے اسلام میں بذر (ضائع) قرار دیا گیا۔ آپ صلی اللہ علیہ وسلم نے ان کے ہاں ان کی بیٹی کے لیے پیام نکاح بھیجا جس پر وہ کہنے لگے: چونکہ اس میں ایک عیب ہے اس لیے میں اسے آپ کے لیے پسند نہیں کرتا، حالانکہ کوئی عیب نہ تھا۔ جب واپس آکر دیکھا تو اسے برص کی بیماری ہو چکی تھی۔ جس سے اس کے چچا زاد یزید بن جمرہ نے شادی کر لی تو ان کے ہاں شبیب پیدا ہوا جو ابن برصاء نام سے مشہور ہوا۔ برصاء کا نام قرصافہ تھا، یہ رشاطی کا بیان ہے۔ ان کے علاوہ کسی نے ذکر کیا ہے کہ اس کے والد نے کہا: اس کے سفیدی ہے اور عرب اس سے برص مراد لیتے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “سو ایسے ہی ہو۔” چنانچہ وہ اسی وقت برص والی ہو گئی۔ واقدی کا قول ہے: مجھے عبدالرحمن بن ابراہیم مدنی نے بحوالہ اپنے شیوخ بیان کیا۔ بنی مرہ کا تیرہ افراد پر مشتمل ایک وفد نبی صلی اللہ علیہ وسلم کے پاس آیا جس کا سردار حارث بن عوف تھا۔ اس وقت آپ صلی اللہ علیہ وسلم تبوک سے واپس تشریف لائے تھے۔ یہ لوگ بنت حارث کے گھر فروکش ہوئے اور پھر مسجد میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ حارث کہنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! ہم آپ کی قوم اور آپ کے رشتہ دار ہیں، لوی بن غالب کی اولاد ہیں، پھر ایک قصہ ذکر کیا۔ زبیر لکھتے ہیں: مجھے میرے چچا مصعب نے بتایا کہ حارث بن عوف نبی صلی اللہ علیہ وسلم کے پاس آ کر کہنے لگے: میرے ساتھ ایسا شخص روانہ فرمائیے جو آپ کے دین کی دعوت دے۔ میں اس کا ذمہ دار ہوں۔ چنانچہ آپ صلی اللہ علیہ وسلم نے اس کے ساتھ انصار کا ایک شخص بھیجا جس سے حارث کے رشتہ داروں نے بغاوت کر کے اسے شہید کر دیا۔ اس پر سیدنا حسان بول اٹھے: “اے حارث! تم میں سے کون اپنے پڑوسی سے بغاوت کرتا ہے، سو محمد (صلی اللہ علیہ وسلم) یہی تو کسی سے دھوکا نہیں کرتے۔” حارث آ کر معذرت کرنے لگے اور انصار کو دیت دی اور کہنے لگے: “اے محمد (صلی اللہ علیہ وسلم)! میں حسان کی زبان سے آپ کی پناہ چاہتا ہوں۔”","",{"fn":"(1) اسد الغابۃ (۹۴۱) استیعاب (۹۳۴)"}],[1462,"§۱۴۶۳ ۔ حارث بن عوف\nانہیں عوف بن حارث اور حارث بن مالک لیثی ابو واقد بھی کہا جاتا ہے۔ کنیت سے مشہور ہیں۔ ان کے حالات کنتیوں میں آئیں گے۔"],[1463,"§۱۴۶۴ ۔ حارث بن عیسیٰ\nبقول بعض باء سے عبس عبدی ثم صباحی (صاد کے پیش اس کے بعد با مخفف ہے) وفد عبد القیس کے ایک فرد ہیں۔ ابو عبیدہ نے ان میں ذکر کیا ہے۔ ابن الامین اور ابن بشکوال نے اپنے اپنے استدراک میں ان کا ذکر کیا ہے۔ رشاطی فرماتے ہیں: ابو عمر اور ابن فتحون نے ان کا ذکر نہیں کیا۔"],[1464,"§۱۴۶۵ ۔ حارث بن غزیہ انصاری\nانہیں غزیہ بن حارث بھی کہا جاتا ہے۔ ابن السکن، باوردی اور ابن مندہ کتاب الصحابہ میں اور حسن بن سفیان نے اپنی مسند میں اسحاق بن عبد اللہ بن ابی فروہ (جو متروک راوی ہے) کے طریق سے بحوالہ عبد اللہ بن رافع نقل کیا ہے، انہوں نے بحوالہ حارث بن غزیہ بتایا، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا فتح مکہ کا دن تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: “فتح کے بعد ہجرت نہیں رہی۔” (حدیث)(1)","",{"fn":"(1) المعجم الکبیر (۲۶۳/۱۸) کنز العمال (۳۰۱۶۴)"}],[1465,"§۱۴۶۶ ۔ حارث بن غطیف(1)\n(غین سے تصغیر ہے) سکونی شامی۔ ان کی حدیث معاویہ بن صالح نے بحوالہ یونس بن سیف ان سے نقل کی ہے۔ اس میں اختلاف ہے۔ چنانچہ ابو صالح اور حماد بن خالد فرماتے ہیں، معاویہ سے یہ روایت ہے: “میں اس بات کو نہیں بھولا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز میں بائیں ہاتھ پر دایاں ہاتھ رکھے دیکھا۔”(2) اسے بغوی اور سمویہ نے بھی نقل کیا ہے۔ عبدالرحمن بن مہدی اور زید بن حباب بحوالہ معاویہ اسی طرح نقل کرتے ہیں، البتہ انہوں نے شک کی بنا پر کہا: “غطیف بن حارث یا حارث بن غطیف”۔ اسے ابن ابی شیبہ اور ابن السکن نے نقل کیا ہے۔ ابن وہب اور بدین بن سعد نے بحوالہ معاویہ ابو صالح کی روایت کی طرح بلاشک روایت کی ہے۔ لیکن یونس اور حارث کے درمیان ابوراشد حمرانی کا اضافہ کر دیا۔ ابن مندہ باوردی اور ابن شاہین نے اسے نقل کیا ہے۔ ابن مندہ لکھتے ہیں: ابن راشد نے اس میں اضافہ نقل کیا ہے۔ معین بحوالہ معاویہ فرماتے ہیں: غضیف بن حارث (ضاد نقطے والا) اسے ابن مندہ نے نقل کر کے کہا: پہلا قول زیادہ صحیح ہے۔ ابن السکن بحوالہ ابن معین روایت کرتے ہیں: درست نام حارث بن غطیف ہے۔ ابن السکن فرماتے ہیں: جس نے غضیف لکھا، اس نے لفظی غلطی کی ہے اس لیے کہ غضیف بن حارث دوسری شخصیت ہیں جن کی کنیت ابو اسما تھی۔","",{"fn":"(1) اسد الغابۃ (۹۴۳) استیعاب (۴۴۴)\n(2) جامع المسانید والسنن (۲۳۲/۳)"}],[1466,"§۱۴۶۷ ۔ حارث بن فروہ(1)\nبن شیطان بن خدیج بن امرئ القیس بن حارث بن معاویہ بن حارث بن معاویہ بن ثور کندی، ابن کلبی، ابن سعد، اور طبری نے ذکر کیا ہے کہ انہیں وفد میں آنے کی سعادت حاصل ہے۔ امام ابن الاثیر(2) فرماتے ہیں: ابوموسیٰ کے ذیل میں: حارث بن قرہ (قاف سے) لکھا ہے۔ اور جمہرہ میں فروہ فا اور واؤ کے اضافہ سے ہے جو صحیح ہے۔ لکھا ہے کہ ان کے دادا کا نام خوبصورتی کی وجہ سے ’شیطان‘ پڑ گیا تھا۔","",{"fn":"(1) اسد الغابۃ (۹۴۴)\n(2) اسد الغابۃ (۳۸۹/۱)"}],[1467,"§۱۴۶۸ ۔ (ز) حارث بن ابی قارب قرشی سہمی\nموسیٰ بن عقبہ نے جنگ اجنادین میں شہید ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ اور ابن فتحون نے اپنے استدراک میں ان کا تذکرہ کیا ہے۔"],[1468,"§۱۴۶۹ ۔ حارث بن قیس(1)\nبن حارث بن اسماء بن مر بن شہاب بن ابی شمر غسانی، شہسوار و شاعر تھے۔ ابن کلبی نے نبی صلی اللہ علیہ وسلم کے پاس بصورت وفد آنے والوں میں ان کا ذکر کیا ہے۔ ابن ماکولا نے بھی ان کا ذکر کیا ہے اور ابن الامین اور ابن فتحون نے بحوالہ ابن دباغ اپنے اپنے استدراک میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۴۵)"}],[1469,"§۱۴۷۰ ۔ حارث بن قیس\nبن علدہ انصاری ثم زرقی، کنیت سے مشہور ہیں۔ ابو خالد کنیت تھی، کنیتوں میں تذکرہ ہوگا۔"],[1470,"§۱۴۷۱ ۔ حارث بن قیس(1)\nبن عدی سہمی۔ ان کے والد حارث کا تذکرہ گزر چکا ہے۔ رہے یہ تو ابن ابی خیثمہ نصر بن مزاحم کے طریق سے بحوالہ معروف بن خربوذ روایت کرتے ہیں، فرمایا: جاہلیت میں شرافت دس قریشی آدمیوں پر ختم تھی، پھر اسلام سے مل گئی۔ پھر ان لوگوں کا تذکرہ کیا، فرمایا: بنی سہم حارث بن قیس، جنہیں حکومت و اموال میسر تھے۔ میں کہتا ہوں: ممکن ہے ان کی اس بات “پھر اسلام سے مل گئی” سے مراد ان کی اولاد سے مل گئی ہو۔ اس سے یہ معلوم نہیں ہوتا کہ وہ صحابی تھے لہذا غور کر لینا چاہیے۔ پھر مجھے ابن عبدالبر کی کتاب میں ابن ابی خیثمہ جیسی روایت ملی لیکن اس میں اضافہ ہے کہ وہ اسلام لے آئے اور اپنے بیٹوں حارث، بشر اور معمر کے ساتھ حبشہ ہجرت کی۔ ابن الاثیر ان کا تعاقب کرتے ہوئے لکھتے ہیں کہ زبیر اور ابن کلبی نے ذکر کیا ہے کہ وہ ان میں یہ اضافہ ہے کہ سوائے ابو عمر کسی نے ان کا اسلام لانا ذکر نہیں کیا۔ میں کہتا ہوں: ابو عبید، مصعب اور طبری وغیرہ نے اسلام لانے والوں میں ان کا ذکر کیا ہے۔ لہذا اس میں کوئی ممانعت نہیں کہ وہ تائب ہو گئے ہوں اور شرف صحابیت حاصل کر کے ہجرت کر لی ہو۔ لہذا دونوں اقوال میں کوئی منافات و تعارض نہیں۔ رہا ارشادِ باری تعالیٰ: “ہم استہزاء و مزاح کرنے والوں سے آپ کی کفایت کرنے والے ہیں۔ (سورۃ الحجر: ۹۵) کسی کی توبہ نہ کرنے میں واضح نہیں ہے، جس کی تائید اس سے بھی ہوتی ہے کہ ابن اسحاق نے استہزاء کرنے والوں میں سے ہر ایک کی موت کا ذکر کیا ہے کہ وہ کیسے مرا۔ حارث بن طلاطلہ کی موت کا ذکر کر کے پھر عکرمہ اور سعید بن جبیر کے طریق سے روایت نقل کی ہے، فرمایا: حارث بن عطلہ، رہے عکرمہ تو انہوں نے حارث بن قیس کہا۔ اور ابن اسحاق نے یزید بن رومان سے بحوالہ ان کا نسب خزاعی ذکر کیا ہے جو کہی کے علاوہ ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۹۴۸) استیعاب (۴۴۵)"}],[1471,"§۱۴۷۲ ۔ حارث بن قیس\nانہیں قیس بن حارث بھی کہا جاتا ہے، قاف میں تذکرہ ہوگا۔"],[1472,"§۱۴۷۳ ۔ (ز) حارث بن قیس الفہری\nابن عبدالقیس میں تذکرہ ہو چکا ہے۔"],[1473,"§۱۴۷۴ ۔ حارث بن کرز\nعبد الصمد بن سعید نے حمص فروکش ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان سے مہاجر بن حبیب روایت کرتے ہیں۔ تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے، میں نے مغلطائی کے قلم سے لکھا ہوا نقل کیا ہے۔"],[1474,"§۱۴۷۵ ۔ حارث بن کعب\nبقول بعض یہ اسلع کا نام ہے جن کا ذکر ہمزہ میں ہو چکا ہے۔"],[1475,"§۱۴۷۶ ۔ حارث بن کعب(1)\nبن عمرو بن عوف بن مبذول بن عمرو بن غنم بن مازن بن النجار انصاری، بخاری ثم مازنی۔ ابن کلبی فرماتے ہیں: صحابی ہیں اور یمامہ میں شہید ہوئے۔ ایسا ہی عدوی کا قول ہے جس سے تجرید کے قول کہ صرف کلبی نے ان کا ذکر کیا ہے“ کی تردید ہو جاتی ہے۔","",{"fn":"(1) اسد الغابۃ (۹۵۱)"}],[1476,"§۱۴۷۷ ۔ حارث بن کلدہ(1)\nبن عمرو بن ابی علاج بن ابی سلمہ بن عبد العزی بن عبیدہ بن عوف بن قصی ثقفی عرب کے طبیب، مغازی میں ابن اسحاق(2) تھا فرماتے ہیں: مجھے ایسے شخص نے بتایا جس پر مجھے کسی قسم کا شبہ نہیں۔ عبداللہ بن مکرم سے وہ ثقیف کے ایک شخص سے روایت کرتے ہیں، اس نے کہا کہ جب اہل طائف مسلمان ہوئے تو ان غلام لوگوں کے بارے میں ایک جماعت نے لب کشائی کی۔ یعنی جو نبی صلی اللہ علیہ وسلم کی طرف اتر آئے اور اسلام قبول کر لیا تھا۔ آپ نے انہیں آزاد کر دیا تھا۔ نبی صلی اللہ علیہ وسلم نے فرمایا تھا: ”یہ اللہ تعالیٰ کے آزاد کردہ ہیں۔“ ان کے متعلق گفتگو کرنے والے حارث بن کلدہ بھی تھے۔ ان کے علاوہ کا قول ہے کہ ازرق مولیٰ حارث بھی ان میں شامل تھے۔ ابو داؤد(3) نے ابن ابی نجیح کے طریق سے بحوالہ مجاہد، سعد بن ابی وقاص سے نقل کیا، فرماتے ہیں: میں بیمار ہوا تو نبی صلی اللہ علیہ وسلم میرے پاس تشریف لائے، آپ نے فرمایا: ”تمہیں دل کی تکلیف ہے۔ ثقیف کے بھائی حارث بن کلدہ کے پاس جاؤ کیونکہ وہ علاج معالجہ کرتا ہے اسے کہا کہ سات کھجوریں لے اور انہیں کوٹ لے“۔ ابن مندہ نے اسمعیل بن محمد بن سعد کے طریق سے وہ اپنے والد سے نقل کرتے ہیں، فرمایا: سیدنا سعد بیمار ہوئے تو نبی صلی اللہ علیہ وسلم ان کی عیادت کرنے تشریف لائے۔ آپ نے فرمایا: ”مجھے امید ہے کہ اللہ تعالیٰ تمہیں صحت یاب کرے گا“۔ پھر حارث بن کلدہ سے فرمایا: ”سعد کی بیماری کا علاج کرو“۔ پھر وہ حدیث ذکر کی۔ ابن ابی حاتم(4) فرماتے ہیں ان کے مسلمان ہونے کا واقعہ صحیح نہیں۔ اس حدیث سے معلوم ہوا کہ ذمیوں سے طب و علاج میں امداد لینا جائز ہے۔ میں کہتا ہوں: مجھے ان کے متعلق ایک روایت ملی ہے، جسے ہم نے امالی معاملیہ کے جزء تاسع (نویں) میں روایت کیا ہے اور عسکری کی کتاب تصحیف میں شریک بن عبد الملک بن عمیر کے طریق سے حارث بن کلدہ سے مروی ہے جو عرب کے بڑے طبیب تھے۔ وہ اپنی ایک سایہ دار جگہ میں بیٹھا کرتے تھے، اس کے متعلق کسی نے ان سے پوچھا، انہوں نے کہا: ”دھوپ ہوا کو آلود کرتی، کپڑے بوسیدہ کرتی اور چھپی بیماریاں پیدا کرتی ہے۔“ طب میں حارث کی باتیں بہت زیادہ ہیں جن میں سے جوہری نے صحاح میں ایک روایت نقل کی ہے کہ سیدنا عمر رضی اللہ عنہ نے حارث بن کلدہ سے (جو عرب کے طبیب تھے) پوچھا: علاج کیا ہے؟ اس نے کہا: پرہیز۔ پھر مجھے یہ روایت ابراہیم حربی کی کتاب ”غریب الحدیث“ میں ابن ابی بیچ کے طریق سے ملی کہ سیدنا عمر رضی اللہ عنہ نے پوچھا پھر اسے ذکر کیا۔ عبدالملک بن حبیب کی کتاب الطب النبوی میں عروہ بن زبیر کی مرسل روایت بحوالہ عمر بنی شیخہ مروی ہے۔ اور داؤد بن رشید نے بحوالہ عمرو بن معروف روایت کیا ہے: حارث کے آخری وقت لوگ اس کے پاس جمع ہوئے اور کہا ہمیں کوئی وصیت کرو۔ اس نے کہا: صرف جوان لڑکی سے شادی کرنا، صرف پکا ہوا پھل کھانا، جب تک کسی کا بدن بیماری برداشت کر سکے ہرگز علاج نہ کرنا، ہر ماہ چونے کا استعمال کرنا، اس سے بلغم ختم ہو جاتی ہے، جو دوپہر کا کھانا کھا لے وہ سو جائے اور جو رات کا کھانا کھائے اس کے بعد چالیس قدم چلے۔ کسریٰ کے ساتھ اس کا مشہور قصہ ہے جسے ہم بیان کر کے کتاب کو لمبا نہیں کرنا چاہتے۔ بقول بعض اس کی موت کی وجہ یہ بنی کہ اسے ایک سانپ نظر آیا۔ تو کہنے لگا بعض دفعہ عالم کا علم تریاق (زہر کا توڑ) کا سا کام کرتا ہے۔ تو کسی نے اس سے کہہ دیا: ابو وائل! کیا تم اس سانپ کو نہیں پکڑتے؟ تو تکبر نے اسے سانپ پکڑنے پر مجبور کیا۔ ہاتھ بڑھایا ہی تھا کہ سانپ نے اپنی فطرت ظاہر کی اور اسے ڈس لیا جس سے وہ بے ہوش ہو کر گر پڑا اور کچھ ہی دیر بعد چل بسا۔","",{"fn":"(1) اسد الغابۃ (۹۵۴)\n(2) السیرۃ النبویۃ (۱۰۱/۴)\n(3) ابوداؤد کتاب الطب باب ترمۃ العجوۃ (۳۸۷۵)\n(4) الجرح والتعدیل (۸۷/۳)"}],[1477,"§۱۴۷۸ ۔ حارث بن مالک\nابو واقد لیثی کنتیوں میں تذکرہ ہوگا ان کے والد کا نام بھی واقدی نے یہی بتایا ہے۔"],[1478,"§۱۴۷۹ ۔ حارث بن مالک(1)\nبن قیس بن عوز بن جابر بن عبد مناف بن شجع بن عامر بن لیث بن بکر کنانی لیثی، ابن برصاء سے مشہور ہیں۔ برصاء ان کی والدہ ہیں، بقول بعض ان کی دادی ہیں۔ پہلے کہہ چکا ہوں کہ مدینہ رہائش پذیر ہوئے۔ اور ابن حبان(2) نے ان کی حدیث نقل کی اور اسے صحیح قرار دیا ہے اور دارقطنی نے شعیبی کے طریق سے بحوالہ ان کے نقل کیا ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے موقع پر فرماتے سنا: “آج کے بعد قیامت تک مکہ پر چڑھائی نہیں ہو گی”۔ اور زہیر بن بکار نے مسور بن عبدالملک پر یولی سے بحوالہ ان کے والد وسعید بن المسیب سے روایت کرتے ہیں کہ ابن برصاء مروان بن حکم کے ہمنشینوں میں سے تھے، اس کے ساتھ رات کو بات چیت کرتے۔ ایک رات مالی غنیمت کا تذکرہ ہوا، لوگوں نے کہا مالی غنیمت تو اللہ تعالیٰ کا مال ہے۔ اور سیدنا عمر رضی اللہ عنہ نے اسے اس کی جگہ صرف کیا اس پر مروان نے کہا: مالی غنیمت امیر المومنین معاویہ کا مال ہے جہاں چاہیں صرف کریں۔ تو ابن البرصاء وہاں سے چلے گئے۔ سیدنا سعد بن ابی وقاص سے ملے اور انہیں ساری بات بتائی۔ سعید فرماتے ہیں: میں مسجد کے ارادے سے جا رہا تھا کہ سیدنا سعد سے ملاقات ہو گئی۔ فرمایا: میرے ساتھ آؤ، میں آپ کے پیچھے یہاں تک کہ مروان کے پاس جا پہنچے۔ آپ نے اسے سخت ست کہا، پھر قصہ ذکر کیا۔ فرماتے ہیں کہ مروان نے کہا: آپ نے کب دیکھا؟ یہ بات اس شیخ سے کس نے کی ہے؟ لوگوں نے کہا: ابن البرصاء نے۔ چنانچہ انہیں لایا گیا۔ ابھی کوڑے مارنے کے لیے ان کے کپڑے اتروائے ہی تھے تو اتنے میں دربان حکیم بن حزام کے لیے اجازت لینے آ گیا۔ مروان نے کہا: اسے اس کے کپڑے واپس دے دو۔ اور باہر نکال دو، ہمارے لیے اس دوسرے بوڑھے کو نہ بڑھکا دے۔ پھر لمبا قصہ ذکر کیا۔ جس سے معلوم ہوتا ہے کہ حارث خلافت معاویہ میں اشنہ تک زندہ رہے۔ یہی ان کی نسبت کے متعلق مشہور ہے۔ امام احمد رحمہ اللہ نے اپنی مسند میں جب ان کی مرفوع حدیث بحوالہ سفیان نقل کی تو فرمایا وہ خزاعی ہیں۔","",{"fn":"(1) اسد الغابۃ (۹۵۶) استيعاب (۴۱۸)\n(2) ترمذی کتاب السیر باب ما قال النبی صلی اللہ علیہ وسلم یوم فتح مکۃ ان ھذہ لا تغزی ... (حدیث ۱۶۱۱)"}],[1479,"§۱۴۸۰ ۔ حارث بن مالک انصاری(1)\nابن المبارک نے کتاب الزہد میں ان کی حدیث بحوالہ معمر، صالح بن مسمار سے نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: حارث بن مالک! صبح کیسے ہوئی؟ عرض کیا: ایمان و یقین سے۔ آپ نے فرمایا: ہر چیز کی ایک حقیقت ہوتی ہے، تمہارے ایمان کی حقیقت کیا ہے؟ عرض کیا:(2) میں نے اپنے آپ کو دنیا سے روکا جس کے نتیجہ میں رات بیدار رہا، دن کے وقت پیاسا رہا، گویا مجھے اپنے رب کا عرش نظر آ رہا ہے اور مجھے اس میں اہل جنت ایک دوسرے کی زیارت کرتے نظر آ رہے ہیں۔ اور گویا میں جہنمیوں کا شور سن رہا ہوں۔ آپ علیہ السلام نے فرمایا: “مومن کا دل اللہ تعالیٰ منور کر دیتا ہے۔” یہ روایت معضل ہے۔ اسی طرح عبدالرزاق نے معمر سے بحوالہ صالح بن مسمار اور جعفر بن برقان نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے حارث سے فرمایا، اور اسے تفسیر میں ثوری سے بحوالہ عمرو بن قیس ملائی، زید سلمی سے نقل کیا۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے حارث سے فرمایا: حارث! صبح کیسے ہوئی؟ عرض کیا: ایمان والوں میں سے؟ آپ نے فرمایا: جانتے ہو کیا کہہ رہے ہو؟ پھر اسی طرح کے مفہوم کی روایت نقل کی۔ اس کے آخر میں یہ اضافہ نقل کیا ہے: یا رسول اللہ صلی اللہ علیہ وسلم! میرے لیے شہادت کی دعا فرمائیے۔ آپ نے ان کے لیے دعا فرمائی، انہی دنوں مدینہ کے مویشیوں پر حملہ ہوا تو یہ بچاؤ کے لیے نکلے اور لڑتے لڑتے شہید ہو گئے۔ دوسرے طریق سے یہ حدیث موصولاً بھی مروی ہے۔ طبرانی(3) نے سعید بن ابی ہلال کے طریق سے بحوالہ محمد بن ابی انجم روایت کی ہے جبکہ ابن مندہ نے سلیمان بن سعید کے طریق سے بحوالہ ربیع بن لوظ، دونوں حارث بن مالک انصاری سے روایت کرتے ہیں کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگے: یا رسول اللہ صلی اللہ علیہ وسلم! میں یقیناً ایمان والوں سے ہوں۔ آپ نے فرمایا: دیکھو کیا کہہ رہے ہو؟ (الحدیث) اس کے آخر میں ہے: “جو کسی ایسے شخص کو دیکھنے کا خواہشمند ہو جس کا دل اللہ تعالیٰ نے منور کر دیا ہے تو وہ حارث بن مالک کو دیکھ لے”۔ ابن مندہ فرماتے ہیں: اسے زید بن ابی انیسہ نے عبد الکریم بن حارث سے انہوں نے حارث بن مالک کے حوالہ سے نقل کیا ہے۔ اور جریر بن عقبہ بن عبد الرحمن نے بحوالہ اپنے والد، انس بن مالک رضی اللہ عنہ سے نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم مسجد میں داخل ہوئے تو وہاں حارث بن مالک تھے، جنہیں آپ صلی اللہ علیہ وسلم نے اپنے پاؤں سے حرکت دی۔ پھر وہ حدیث ذکر کی۔ اور بیہقی نے “شعب” میں یوسف بن عطیہ الصفار کے طریق سے (جو بے حد ضعیف راوی ہے) بحوالہ انس رضی اللہ عنہ روایت کیا ہے کہ ایک دن نبی صلی اللہ علیہ وسلم کی حارث بن مالک سے ملاقات ہوئی، آپ نے فرمایا: حارث! صبح کیسے ہوئی؟ عرض کیا: میں نے ایمان و یقین کی حالت میں صبح کی ہے۔ حدیث طویل ہے۔ جس کے آخر میں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: “حارث! جب تم پہچان گئے تو اسے نہ چھوڑنا”۔ بیہقی(4) فرماتے ہیں: یہ روایت منکر ہے، جس میں یوسف کو خبط ہو گیا۔ چنانچہ ایک مرتبہ اس نے حارث کہا اور دوسری بار حارثہ کہہ دیا۔ ابو عاصم حشیش بن اصرم نے اپنی کتاب الاستقامہ میں عبد العزیز بن ابان سے بحوالہ مالک بن مغول، فضیل بن غزوان لکھا ہے کہ مدینہ کے مویشیوں پر حملہ ہوا، جس کے لیے حارث بن مالک نکلے اور ان کے آٹھ آدمی مار ڈالے پھر خود شہید ہو گئے۔ یہ وہی ہیں جن سے نبی صلی اللہ علیہ وسلم نے فرمایا تھا: “حارثہ! صبح کیسے ہوئی؟” ابن ابی شیبہ(5) نے، ابن نمیر سے بحوالہ مالک بن مغول یہ روایت مرفوع نقل کی ہے جس میں فضیل بن غزوان کا ذکر نہیں کیا۔ ابن صاعد اس روایت کو حسین بن حسن مروزی سے بحوالہ ابن المبارک نقل کرنے کے بعد لکھتے ہیں: میرے علم میں صالح بن مسمار نے صرف ایک حدیث مسنداً نقل کی ہے اور یہ حدیث موصولاً ثابت نہیں۔","",{"fn":"(1) اسد الغابۃ (۹۵۷)\n(2) المصنف لابن ابی شیبہ حدیث (۴۲/۱۱) اتحاف السادۃ المتقین (۳۲۷/۹) کنز العمال (حدیث ۳۶۹۸۹)\n(3) المعجم الکبیر (۳۳۶۷/۳) کنز العمال (۳۳۲۴۴)\n(4) الزهد الکبیر (۹۷۱)\n(5) المصنف لابن ابی شیبہ حدیث (۴۳/۱۱)"}],[1480,"§۱۴۸۱ ۔ حارث بن مُحاشن(1)\nابو عمر فرماتے ہیں: قاضی اسمعیل نے علی بن مدینی کے حوالہ سے مہاجرین میں ان کا تذکرہ کیا ہے۔ ان کی قبر بصرہ میں ہے۔","",{"fn":"(1) اسد الغابۃ (۹۵۹) استيعاب (۴۱۹)"}],[1481,"§۱۴۸۲ ۔ (ز) حارث بن مرہ الجہنی(1)\nسیف نے فتوح میں ذکر کیا ہے کہ سیدنا خالد بن ولید رضی اللہ عنہ نے خلافت صدیقی میں قضاعہ کا امیر مقرر فرمایا تھا اور اس وقت خود عراق کی طرف روانہ ہوئے تھے۔ وہ جنگجو صحابہ میں سے تھے۔ ان کی ایک روایت کا بھی ذکر کیا ہے جو ارطاۃ بن ابی ارطاۃ شخصی کے ذریعہ ان سے بحوالہ ابن مسعود رضی اللہ عنہ مروی ہے۔","",{"fn":"(1) استيعاب (۳۵۴/۱)"}],[1482,"§۱۴۸۳ ۔ حارث بن مسعود(1)\nبن عبدہ بن مظہر (میم کے پیش اور خا کے زبر، ہاء مشدد زیر والی ہے) ابن قیس بن امیہ بن معاویہ بن مالک بن عوف بن عمرو بن عوف انصاری اوسی، موسیٰ بن عقبہ اور ابن اسحاق نے یوم جسر کے شہداء میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۶۱) استيعاب (۴۱۹)"}],[1483,"§۱۴۸۴ ۔ حارث بن مسلم تمیمی\nان شاء اللہ تعالیٰ مسلم بن حارث میں تذکرہ ہوگا۔"],[1484,"§۱۴۸۵ ۔ حارث بن مسلم حجازی(1)\nابوالمغیرہ مخزومی، امام بخاری لکھتے ہیں: انہیں شرف صحابیت حاصل ہے۔ ایسا ہی ابن ابی حاتم نے بحوالہ اپنے والد لکھا ہے، ابن دباغ اور ابن فتحون نے اپنے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن الاثیر کی کتاب میں ان کے دادا کا نام مغیرہ لکھا ہے اور یہ وہم دیا ہے کہ ابن ابی حاتم کی کتاب میں یونہی لکھا ہے، جبکہ ان کے ہاں ابوالمغیرہ ہی لکھا ہے جیسا کہ امام بخاری رحمہ اللہ کے ہاں ہے۔ اس سلسلہ میں ابن عبدالبر نے جو کچھ حارث بن سوید کے حالات میں لکھا ہے، وہ پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۶۳) الجرح والتعدیل (۹۰/۳)"}],[1485,"§۱۴۸۶ ۔ حارث بن مضرس(1)\nبن عبد بن رزاح انصاری۔ بغوی لکھتے ہیں: درخت والی بیعت میں شریک تھے اور قادسیہ میں شہید ہوئے، ان کی اولاد اور، ہے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابو عمر نے حارث بن عبد بن رزاح کا ذکر کیا ہے، شاید وہ یہی ہوں۔","",{"fn":"(1) اسد الغابۃ (۹۶۴)"}],[1486,"§۱۴۸۷ ۔ حارث بن معاذ انصاری ظہری\nابوذرہ۔ کنیتوں میں ذکر ہوگا۔"],[1487,"§۱۴۸۸ ۔ حارث بن معاذ\nبن نعمان بن امرئ القیس بن زید بن عبد الاشہل انصاری اشہلی سعد بن معاذ کے بھائی۔ ابو الاسود نے بحوالہ عروہ شرکاء بدر(1) میں ان کا ذکر کیا ہے، ان کے بھتیجے حارث بن اوس بن معاذ کا تذکرہ پہلے گزر چکا ہے۔","",{"fn":"(1) المعجم الکبیر (۳۳۷۹/۳)"}],[1488,"§۱۴۸۹ ۔ (ز) حارث بن معاویہ(1)\nالسکونی۔ بنی ہاشم کے حلیف، ابن حبان لکھتے ہیں: شرف صحابیت رکھتے ہیں، جب سیدنا حسین اور سیدنا معاویہ رضی اللہ عنہما کی صلح ہوئی اس وقت کوفہ میں انتقال کیا۔","",{"fn":"(1) اسد الغابۃ (۹۶۵)"}],[1489,"§۱۴۹۰ ۔ حارث بن معاویہ(1)\nبن زمعہ الکندی، ان کے صحابی ہونے میں اختلاف ہے ابن مندہ نے کتاب الصحابہ میں اور ابونعیم نے انہی کے اتباع میں ذکر کیا ہے۔ اور ان کا تعلق مقدام رہاوی کی حدیث سے ذکر کیا ہے جس میں فرماتے ہیں کہ عبادہ بن الصامت، ابودرداء اور حارث بن معاویہ اکٹھے بیٹھے تھے کہ سیدنا ابو درداء رضی اللہ عنہ بولے تم میں سے کسے یاد ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے غنیمت کے ایک اونٹ کو سترہ بنا کر نماز پڑھی تھی؟ تو عبادہ رضی اللہ عنہ بولے: مجھے یاد ہے۔ پھر حدیث ذکر کی۔(2) ابو نعیم لکھتے ہیں: اس روایت کو ابو سلام نے مقدام کندی سے نقل کیا تو حارث بن معاویہ کندی نے کہا۔ ابن سعد اور ابوزرعہ دمشقی نے شام کے طبقہ اولی کے تابعین میں ان کا ذکر کیا ہے۔ ابو مسہر نے ابو درداء رضی اللہ عنہ کے اکابر شاگردوں میں ان کا شمار کیا ہے۔ عجلی لکھتے ہیں: اکابر تابعین سے ہیں۔ امام بخاری، مسلم، ابو حاتم، ابن سمیع اور ابن حبان نے تابعین میں ان کا ذکر کیا ہے۔ ابو وہب کلامی بحوالہ مکحول حارث بن معاویہ کندی سے روایت کرتے ہیں کہ میں اور ابو جندل بن سہل وضو کر رہے تھے، پھر موزوں پر مسح کرنے کا قصہ ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۹۶۶)\n(2) المصنف لابن ابی شیبہ (۳۸۵/۱) جامع المسانید (۲۳۷/۳)"}],[1490,"§۱۴۹۱ ۔ حارث بن معلی\nبقول بعض حارث بن نفیع بن معلی۔ یہ وہی ابوسعید ہیں جو اپنی کنیت سے شہرت رکھتے ہیں کنیتوں میں ذکر آئے گا۔"],[1491,"§۱۴۹۲ ۔ حارث بن معمر(1)\n(تشدید ہے) ابن حبیب بن وہب بن حذافہ بن جمح قرشی جمحی حاطب کے والد اور حارث بن حاطب کے دادا جن کا ذکر قریب ہی گزرا ہے۔ ابوالاسود نے بحوالہ عروہ مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ یہ سب مہاجرین حبشہ کے سلسلہ میں آتے ہیں۔ حارث، ان کے والد حاطب اور ان کے دادا حارث۔ رہی وہ روایت جو ابن عائذ نے نقل کی اور انہی کے طریق سے ابن مندہ نے اور عطاء خراسانی کی روایت سے بحوالہ ان کے والد ابن عباس رضی اللہ عنہ سے مہاجرین حبشہ کے بارے میں نقل کی ہے: حارث بن معمر حبشہ میں تھے کہ ان کے ہاں حاطب بن حارث پیدا ہوئے، بالکل غلط ہے۔ وہاں تو ان کے بیٹے حاطب کے ہاں ولادت ہوئی اور پیدا ہونے والے حارث بن حاطب ہیں جیسا گزر گیا اور آئے گا بھی۔","",{"fn":"(1) اسد الغابۃ (۹۶۸)"}],[1492,"§۱۴۹۳ ۔ حارث بن نبیہ(1)\nانس بن حارث کے والد، انہیں اور ان کے بیٹے کو شرف صحابیت حاصل ہے۔ ان کے بیٹے کا تذکرہ پہلے ہو چکا ہے۔ ابو عبد الرحمن سلمی نے اصحاب صفہ میں ان کا تذکرہ کیا ہے ان سے ان کے بیٹے انس ایک حدیث روایت کرتے ہیں۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ انس بن حارث میں بھی ان کا تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۷۰)"}],[1493,"§۱۴۹۴ ۔ حارث بن نضر سہمی\nیا، حارث بن سہم بصری، زبیر بن بکار نے موفقیات میں محمد بن اسحاق کے طریق سے سقیفہ بنی ساعدہ کے قصہ میں انصار کے بارے میں ان کے اشعار ذکر کیے ہیں، جن کا مطلع یہ ہے: میری قوم کے لوگ کم عقلی کی وجہ سے اور لغزش کے انتظار کی وجہ سے اس سے پہلے اللہ اور رسول کی طرف بلانے والے تھے۔ اور اسلام کی باگیں تھے، ہمارے سامنے حکومت والے قریش ہی ہیں۔ اور قریش ہی عقلمند ہیں۔ دھیمہ نے ذکر کیا کہ جب خلافت کے بارے مہاجرین و انصار کا تنازعہ ہوا تو حارث بن نضر کھڑے ہو کر اپنی قوم سے مخاطب ہوئے جس میں پہلے اور تیسرے شعر کے ساتھ یہ اضافہ ذکر کیا: “اے اوس و خزرج کی جماعت! اللہ تعالیٰ سے ڈرو اور گناہوں کے انجام سے بچو!” ان کے دوسرے اشعار کا ذکر بھی کیا جو خالد بن ولید رضی اللہ عنہ کے یمامہ میں مرتدوں کے ساتھ جنگ کرنے کے موقع پر امیر مقرر کرنے کے سلسلہ میں کہے تھے۔ یہ بات اس کے خلاف ہے جو زبیر نے ان کے والد اور ان کی نسبت کے متعلق لکھی ہے۔ واللہ اعلم"],[1494,"§۱۴۹۵ ۔ حارث بن نضر\nبن حارث انصاری، عدوی نے نسب الانصار میں لکھا ہے کہ انہیں شرف صحابیت حاصل ہے اور قداح نے لکھا ہے کہ وہ بیعت رضوان میں شریک تھے، ان کے والد صحابی ہیں۔ جیسا کہ آئندہ آئے گا ان کے نام کو قلم بند کرنے میں اختلاف ہے۔"],[1495,"§۱۴۹۶ ۔ حارث بن نعمان(1)\nبن اساف بن نضلہ بن عبد عوف بن غنم بن مالک بن النجار انصاری نجاری۔ ابن اسحاق(2) نے شہدائے موتہ میں ان کا ذکر کیا ہے۔ ایسا ہی ابوالاسود نے بحوالہ عروہ کہا ہے۔ عدوی لکھتے ہیں: وہ بدر و احد اور باقی غزوات میں شریک رہے۔ بالآخر موتہ میں شہید ہوئے۔ میں کہتا ہوں: صحیح یہ ہے کہ بدر میں شریک ہونے والے ان کے بعد والے ہیں۔","",{"fn":"(1) اسد الغابۃ (۹۷۱)\n(2) السیرۃ النبویۃ (۲۵/۴)"}],[1496,"§۱۴۹۷ ۔ حارث بن نعمان(1)\nبن امیہ بن امرئ القیس بن البرک بن ثعلبہ بن عمرو بن عوف بن مالک بن اوس انصاری اوسی۔ ابن سعد(2) فرماتے ہیں کہ ابن اسحاق کے علاوہ موسیٰ بن عقبہ، ابن عمارہ، ابو معشر اور واقدی نے بدری صحابہ میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: کہ ابوالاسود نے بحوالہ عروہ اور ابن کلبی نے ان کا ذکر کیا ہے۔ طبرانی نے عبید اللہ بن ابی رافع کے طریق سے ذکر کیا کہ انہوں نے سیدنا علی رضی اللہ عنہ کے ساتھ شرکاء صفین میں ان کا تذکرہ کیا ہے۔ ابن مندہ کہتے ہیں: ان کی کوئی حدیث مشہور نہیں۔","",{"fn":"(1) اسد الغابۃ (۹۷۲) استيعاب (۴۲۲)\n(2) الطبقات الکبریٰ (۴۴/۳)"}],[1497,"§۱۴۹۸ ۔ حارث بن نعمان(1)\nبن قورمہ بن ابی خزمہ، بقول بعض خزیمہ بن ثعلبہ بن عمرو بن عوف انصاری اوسی۔ عبدان نے صحابہ میں ان کا تذکرہ کیا ہے۔ ان میں اور حارثہ بن نعمان میں فرق کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۷۳) استيعاب (۴۱۳)"}],[1498,"§۱۴۹۹ ۔ حارث بن نعمان(1)\nبن رافع بن ثعلبہ بن جشم اوسی۔ ابن مندہ فرماتے ہیں: ان کی حدیث سلیمان بن عبید اللہ نے بحوالہ عبید اللہ بن عمرو، عبدالکریم جزری سے انہوں نے حارث بن نعمان کے کسی بیٹے سے انہوں نے اپنے والد سے نقل(2) کی ہے۔","",{"fn":"(1) اسد الغابۃ (۹۷۴)\n(2) السیرۃ النبویۃ (۲۵۱/۲)"}],[1499,"§۱۵۰۰ ۔ حارث بن نعمان\nحارثہ بن نعمان میں ذکر ہوگا۔"],[1500,"§۱۵۰۱ ۔ حارث بن نفیع\nبقول بعض ابو سعد بن معلی کا نام ہے۔"],[1501,"§۱۵۰۲ ۔ حارث بن نوفل(1)\nبن حارث بن عبد المطلب بن ہاشم ہاشمی۔ عبداللہ جن کا لقب بہہ ہے (دو باؤں سے جن میں سے دوسری مشدد ہے)۔ ابن حبان(2) نے صحابہ میں ان کا ذکر کیا ہے اور کہا ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں مکہ کے بعض کاموں کا نگران بنایا تھا۔ ایسا ہی زبیر بن بکار نے کہا ہے۔ ابن ابی خیثمہ فرماتے ہیں: ہمیں مصعب نے بتایا کہ حارث بن نوفل صحابی ہیں اور روایت بھی کرتے ہیں۔ نبی صلی اللہ علیہ وسلم کے دور میں ان کے ہاں عبداللہ پیدا ہوا جس کا لقب بہہ تھا۔ زبیر بن بکار فرماتے ہیں کہ نوفل اپنے والد کے سب سے بڑے لڑکے تھے۔ ان کا ایک بیٹا حارث تھا جس سے وہ اپنی کنیت رکھتے تھے جو ان کا سب سے بڑا بیٹا تھا۔ امام بخاری نے تاریخ میں عبداللہ بن حارث کے طریق سے نقل کیا کہ ان کا والد مکہ کا گورنر تھا۔ ابن السکن اور طبرانی(3) بحوالہ عاصم بن عبد اللہ کے طریق سے بحوالہ عبداللہ بن حارث بن نوفل وہ اپنے والد سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم جب مؤذن کی آواز سنتے تو وہی الفاظ دہراتے، جب مؤذن حی علی الصلاۃ کہتا، آپ صلی اللہ علیہ وسلم نے فرمایا: “لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللہ”(4) ان کی اور بھی احادیث ہیں۔ نسائی نے ابو مجلز کے طریق سے بحوالہ حارث بن نوفل، سیدہ عائشہ رضی اللہ عنہا سے نقل کیا ہے، فرماتی ہیں: میں آپ صلی اللہ علیہ وسلم کے کپڑوں سے منی کے داغ کھرچ دیا کرتی تھی۔ مزی نے ذکر کیا کہ وہ یہی حارث ہیں، اور ابن حبان کے ہاں وہ کوئی اور ہیں۔ اس واسطے کہ انہوں نے حارث بن نوفل بن حارث کو صحابہ میں ذکر کیا ہے۔ اور سیدہ عائشہ رضی اللہ عنہا سے روایت کرنے والے کو تابعین میں شمار کیا ہے۔ یہی زیادہ ظاہر ہے۔ ابن کلبی لکھتے ہیں یہی اس آیت کا سبب نزول بنے: “اللہ ایسا نہیں کہ آپ کے ان میں ہوتے ہوئے انہیں عذاب دے”۔ (الانفال: ۳۳) ابو حاتم(5) فرماتے ہیں: سیدنا عثمان رضی اللہ عنہ کی خلافت کے آخری دور بصرہ میں فوت ہوئے۔ ابن سعد فرماتے ہیں: مجھے علی بن عیسی بن عبد اللہ بن حارث نے بتایا کہ حارث نبی صلی اللہ علیہ وسلم کے صحابی ہیں۔ آپ نے انہیں مکہ میں کسی کام پر مقرر فرمایا تھا۔ سیدنا ابوبکر وعمر اور عثمان رضی اللہ عنہم نے انہیں اس پر برقرار رکھا۔ پھر وہ بصرہ منتقل ہو گئے، وہاں ایک حویلی بنائی اور سیدنا عثمان رضی اللہ عنہ کی خلافت کے دور میں وہیں فوت ہوئے۔ ان کے علاوہ ان کے گھرانے کے کسی شخص نے بتایا: امیر معاویہ کے دور خلافت میں فوت ہوئے۔ حضور نبی کریم صلی اللہ علیہ وسلم کے ساتھ مشابہت رکھتے تھے۔ رہے زبیر بن بکار تو یہ آخری بات ان کے بھائی عبد اللہ بن نوفل کے سوانح میں ذکر کی ہے۔","",{"fn":"(1) اسد الغابۃ (۹۷۶) استيعاب (۴۲۱)\n(2) الثقات (۹۱/۳)\n(3) المعجم الکبیر (۳۲۶۵/۳)\n(4) بخاری کتاب الاذان باب ما یقول اذا سمع المنادی (حدیث ۶۱۳) المعجم الکبیر (حدیث ۲۹۱/۱۳) الدر المنثور (۲۲۳/۴) کنز العمال (۱۷۷۱) التاریخ الکبیر (۱۰۰/۱)\n(5) الجرح والتعدیل (۹۱/۳)"}]])